INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('67', 'tob', 'Tobit', 1, 1, 'Kitab kisah Tobit bin Tobiel bin Ananiel bin Aduel bin Gabael bin Rafael bin Raguel dari keturunan Asiel dari suku Naftali.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 2, 'Di zaman Salmaneser, raja orang-orang Asyur, Tobit diangkut tertawan dari Tisbe yang terletak di sebelah selatan Kudios-Naftali di Galilea atas di atas Hazor, yakni di sebelah barat, dan di sebelah utara Fogor.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 3, 'Aku, Tobit menempuh jalan kebenaran dan kesalehan seumur hidupku dan banyak melakukan kebajikan kepada para saudara dan segenap bangsaku yang bersama dengan daku telah berangkat ke pembuangan, ke negeri Asyur ke kota Niniwe.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 4, 'Waktu aku masih tinggal di tanah airku, yaitu di tanah Israel, dan ketika aku masih muda, maka seluruh suku Naftali moyangku memberontak terhadap keluarga Daud bapaku dan terhadap Yerusalem, kota yang telah dipilih dari antara semua suku Israel, supaya di sana semua suku mempersembahkan korban. Memang di sanalah Bait Tuhan, yaitu kediaman Allah, telah dibangun dan ditahbiskan untuk segala keturunan sepanjang sekalian abad.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 5, 'Tetapi semua saudaraku dan juga rumah bapaku Naftali mempersembahkan korban kepada anak lembu yang telah dibuat Yerobeam, raja Israel, di kota Dan yang terletak di pegunungan Galilea.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 6, 'Pada hari-hari raya sering kali hanya aku seorang diri sajalah yang pergi ke Yerusalem, sebagaimana yang tersurat bagi segenap Israel sebagai hukum abadi. Pergilah aku ke Yerusalem dengan membawa buah bungaran dan anak sulung dari ternak serta bagian sepersepuluh dari hewan dan lagi guntingan pertama bulu domba.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 7, 'Semuanya kuberikan kepada para imam, keturunan Harun, untuk mezbah. Bagian sepersepuluh dari gandum, anggur, minyak, buah zaitun, buah delima dan hasil bumi lainnya kuberikan kepada kaum Lewi yang menyelenggarakan kebaktian di Yerusalem. Selama enam tahun akupun memungut bagian sepersepuluh yang kedua dan setiap tahun aku pergi membiayakannya di Yerusalem.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 8, 'Adapun bagian sepersepuluh yang ketiga kuberikan kepada para yatim piatu, para janda dan kaum perantau yang tinggal di tengah-tengah orang Israel. Tiga tahun sekali bagian sepersepuluh itu kubawa untuk diberikan kepada mereka. Itupun kami makan pula menurut aturan yang ditetapkan perihal mereka dalam hukum Taurat Musa dan sesuai dengan perintah yang telah diberikan Debora, yaitu ibu Ananiel ayahku. Sebab waktu berpulang ayahku meninggalkan aku sebagai yatim piatu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 9, 'Setelah menjadi dewasa aku mengambil isteri dari keluarga kami sendiri, Hana namanya. Dari padanya kuperanakkan seorang anak laki-laki yang kunamai Tobia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 10, 'Ketika diangkut tertawan dan diasingkan ke negeri Asyur aku pergi ke kota Niniwe. Semua saudaraku dan kaum sekeluarga makan makanan bangsa asing,', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 11, 'tetapi aku mencegah diriku jangan makan makanan itu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 12, 'Sebab dengan segenap hatiku aku ingat kepada Allah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 13, 'Oleh Yang Mahatinggi dianugerahkan kepadaku kerelaan dan penghormatan dari pihak raja Salmaneser. Maka aku menjadi pembelanja segala sesuatunya yang diperlukan raja.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 14, 'Dari sebab itu aku biasa pergi ke negeri Media untuk berbelanja baginya di sana sampai raja mangkat. Sekali kutitipkan sebuah pundi-pundi pada Gabael, saudara Gabria di negeri Media, yang sepuluh talenta perak isinya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 15, 'Semangkatnya Salmaneser maka puteranya Sanherib menjadi raja akan gantinya. Kemudian jalan-jalan di negeri Media tidak terpakai lagi, sehingga aku tidak dapat pergi ke Media lagi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 16, 'Di zaman Salmaneser aku telah banyak melakukan kebajikan kepada para saudara sebangsaku.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 17, 'Makananku kuberikan kepada orang yang kelaparan dan pakaianku kepada orang telanjang. Apabila kulihat seseorang sebangsa yang telah meninggal dan terbuang di belakang tembok kota Niniwe, maka kukuburkan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 18, 'Manakala seseorang dibunuh oleh raja Sanherib, setelah raja pulang kalah dari daerah Yehuda di masa ia dihukum oleh Raja Sorgawi karena hujatnya, maka kukuburkan juga. Sebab banyak dari orang Israel dibunuh oleh raja Sanherib karena kemurkaannya. Tetapi dengan diam-diam kukuburkan semua. Memang mayat-mayat mereka dicari raja, tapi tidak ditemukan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 19, 'Maka salah seorang penduduk kota Niniwe pergi melaporkan kepada raja perihal diriku, bahwa akulah yang menguburkan mayat-mayat itu. Kemudian terpaksa aku bersembunyi. Ketika aku dapat tahu, bahwa hal itu ketahuan oleh raja dan aku dicari-carinya untuk dibunuh, maka aku ketakutan dan melarikan diri.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 20, 'Dari sebab itu segala harta bendaku disita dan tidak ada lagi sisa padaku yang tidak diangkut ke istana raja, kecuali Hana, isteriku, dan Tobia, anakku.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 21, 'Tetapi belum juga empat puluh hari berlalu maka raja Sanherib dibunuh oleh putera-puteranya yang segera melarikan diri ke gunung Ararat. Sesudahnya putera Sanherib, yaitu Esarhadon, menjadi raja. Ahikar bin Anael, saudaraku, diangkat olehnya menjadi ketua dewan keuangan kerajaannya dan kepala urusan istana.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 1, 22, 'Maka Ahikar menjadi pembicara baik bagiku, sehingga aku dapat pulang ke Niniwe. Di masa pemerintahan Sanherib, raja Asyur, Ahikar telah menjadi juru minuman, penjaga cincin meterai dan pengurus istana dan ia dipertahankan oleh raja Esarhadon. Dia itu saudara sepupuku.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 1, 'Jadi, di masa pemerintahan Esarhadon aku kembali ke rumahku. Juga isteriku Hana dan anakku Tobia diserahkan kembali kepadaku. Sekali peristiwa pada hari raya Pentakosta, yaitu hari raya Tujuh Minggu, disajikanlah kepadaku suatu jamuan makan yang baik. Akupun telah duduk untuk makan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 2, 'Sebuah meja ditempatkan di hadapanku dan kepadaku disajikan banyak hidangan. Tetapi berkatalah aku kepada anakku Tobia: "Nak, pergilah dan jika kaujumpai seorang miskin dari saudara-saudara kita yang diangkut tertawan ke Niniwe dan yang dengan segenap hati ingat kepada Tuhan, bawalah ke mari, supaya ikut makan. Aku hendak menunggu, anakku, hingga engkau kembali."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 3, 'Maka keluarlah Tobia untuk mencari seorang saudara kita yang miskin. Sepulangnya berkatalah ia: "Pak!" Sahutku: "Ada apa, nak?" Jawabnya: "Salah seorang dari bangsa kita sudah dibunuh. Ia dicekik dan dibuang di pasar. Masih ada disitu juga!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 4, 'Aku melonjak berdiri dan jamuan itu kutinggalkan sebelum kukecap. Mayat itu kuangkat dari lapangan dan kutaruh di dalam salah satu rumah hingga matahari terbenam, untuk kukuburkan nanti.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 5, 'Kemudian aku pulang, membasuh diriku, lalu makan dengan sedih hati.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 6, 'Maka teringatlah aku kepada firman yang diucapkan nabi Amos mengenai kota Betel ini: "Hari-hari rayamu akan berubah menjadi hari sedih dan segala nyanyianmu akan menjadi ratap!" Lalu menangislah aku.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 7, 'Setelah matahari terbenam aku pergi menggali liang lalu mayat itu kukuburkan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 8, 'Para tetangga menertawakan aku, katanya: "Ia belum juga takut! Sudah pernah ia dicari untuk dibunuh karena perkara yang sama. Dahuli ia melarikan diri dan sekarang ia menguburkan mayat lagi!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 9, 'Pada malam itu juga aku membasuh diriku, lalu pergi ke pelataran rumah dan tidur dekat pagar temboknya. Mukaku tidak tertudung karena panas.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 10, 'Aku tidak tahu bahwa ada burung pipit di tembok tepat di atas diriku. Maka jatuhlah tahu hangat ke dalam mataku. Muncullah bintik-bintik putih. Akupun lalu pergi kepada tabib untuk berobat. Tetapi semakin aku diolesnya dengan obat, semakin buta mataku karena bintik-bintik putih itu, sampai buta sama sekali. Empat tahun lamanya aku tidak dapat melihat. Semua saudaraku merasa sedih karena aku. Dua tahun lamanya aku dipelihara oleh Ahikar sampai ia pindah ke kota Elumais.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 11, 'Di masa itu isteriku Hana mulai memborong pekerjaan perempuan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 12, 'Pekerjaan itupun diantarkannya kepada para pemesan dan ia diberi upahnya. Pada suatu hari, yaitu tanggal tujuh bulan Dustus, diselesaikannya sepotong kain, lalu diantarkannya kepada pemesan. Seluruh upahnya dibayar kepadanya dan ditambah juga seekor anak kambing jantan untuk dimakan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 13, 'Tetapi setiba di rumahku maka anak kambing itu mengembik. Lalu isteriku kupanggil dan berkata: "Dari mana anak kambing itu? Apa itu bukan curian? Kembalikanlah kepada pemiliknya! Sebab kita tidak diperbolehkan makan barang curian!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 2, 14, 'Sahut isteriku: "Kambing itu diberikan kepadaku sebagai tambahan upahku." Tetapi aku tidak percaya kepadanya. Maka kusuruh kembalikan kepada pemiliknya -- Karena perkara itu aku merah padam karena dia! -- Tetapi isteriku membantah, katanya: "Di mana gerangan kebajikanmu? Di mana amalmu itu? Betul, sudah ketahuan juga gunanya bagimu!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 1, 'Maka aku sedih hati, mengeluh dan menangis. Dengan keluh kesah aku angkat doa begini:', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 2, '"Engkaulah adil, ya Tuhan, semua perbuatanMupun adil pula; semua tindakanMu belas kasihan dan kebenaran, dan dunia semesta diadili olehMu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 3, 'Oleh sebab itu, ya Tuhan, ingatlah kepadaku, pandangilah aku! Jangan aku Kauhukum sekedar segala dosaku dan setimpal dengan kekhilafanku kepadaMu, atau sekedar dosa yang diperbuat nenek moyangku!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 4, 'Aku telah tidak taat kepada segala perintahMu, maka kami Kauserahkan untuk dirampasi, dan untuk ditawan dan dibunuh, dan untuk menjadi sindiran, tertawaan dan orang ternista di tengah sekalian bangsa dimana kami Kaucerai-beraikan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 5, 'Segala hukumanMu memang benar, apabila kini aku Kauperlakukan sekedar segala dosaku. Karena kami tidak memenuhi perintah-perintaMu, dan tidak berjalan benar di hadapanMu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 6, 'Kini berbuatlah kepadaku menurut apa yang berkenan kepadaMu, dan sudilah mencabut nyawaku, sehingga lenyaplah aku dari muka bumi dan kembali menjadi debu. Sebab mati lebih berguna bagiku dari hidup, karena aku mesti mendengar nista dan fitnah dan sangat sedih rasa hatiku. Ya Tuhan, suruhlah supaya aku lepas dari susah ini, biarlah aku lenyap menuju tempat abadi; janganlah wajahMu Kaupalingkan dari padaku, ya Tuhan. Sebab lebih bergunalah mati saja dari pada melihat banyak susah dalam hidupku. Nista tidak dapat kudengar lagi!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 7, 'Pada hari yang sama terjadilah bahwa Sara anak perempuan Raguel di kota Ekbatana di negeri Media mendengar nista dari pihak seorang pelayan perempuan ayahnya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 8, 'Adapun Sara itu sudah diperisterikan kepada tujuh laki-laki. Tetapi mereka semua sudah dibunuh oleh Asmodeus, setan jahat itu, sebelum Sara bersetubuh dengan mereka, sebagaimana pantasnya bagi para isteri. Kata pelayan itu kepada Sara: "Engkau sendirilah yang membunuh para suamimu! Engkau sudah diperisterikan kepada tujuh orang, tetapi tidak ada seorangpun yang engkau nikmati juga!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 9, 'Masakan kami kaucambuki karena mereka mati! Baiklah engkau menyusul mereka saja, supaya seorang anak laki-laki atau perempuan dari engkau jangan pernah kami lihat!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 10, 'Maka pada hari itu juga Sara sangat sedih hati, lalu menangis tersedu-sedu. Kemudian ia naik ke bilik atas kepunyaan ayahnya dengan maksud menggantung diri. Tetapi berpikir dan berkatalah ia di dalam hati: "Kiranya ayahku nanti dinistakan karena hal itu dan orang akan berkata kepadanya: Bapak hanya punya satu anak perempuan yang kekasih. Celakalah, ia telah menggantung diri! Niscaya karena sedihnya, maka uban ayahku kubawa ke dunia orang mati. Lebih baiklah aku tidak menggantung diri, melainkan berdoa kepada Tuhan, supaya aku mati saja sehingga tidak usah mendengar lagi nista selama hidupku."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 11, 'Segera tangan dikedangkanlah ke arah jendela, lalu berdoa. Katanya: "Terpujilah Engkau, ya Allah penyayang! Moga-moga terpujilah namaMu selama-lamanya, dan semoga segala buatanMu memuji Engkau selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 12, 'Kini kuangkat mukaku kepadaMu dan kuarahkan mataku.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 13, 'Aku mohon: Biarlah aku dilenyapkan dari muka bumi ini, nista tidak mau kudengar lagi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 14, 'Sebab Engkau tahu, ya Tuhan, bahwa aku bersih dari segala pencemaran oleh seorang laki-laki,', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 15, 'bahwa namakupun tidak kunodai dan tidak pula nama ayahku di tanah pembuanganku. Aku ini anak tunggal ayahku dan ia tidak mempunyai anak lain sebagai waris; tiadapun seorang saudara padanya dan tidak pula sanak saudara lain, sehingga aku mesti memelihara diriku untuk menjadi isterinya. Aku sudah kehilangan tujuh orang; apa lagi gunanya hidup bagiku? Apabila Engkau tidak berkenan membiarkan aku mati, maka dengarkanlah nistaku ini, ya Tuhan!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 16, 'Pada saat itu juga kedua orang itu, yakni Tobit dan Sara, dikabulkan permohonannya di hadapan kemuliaan Allah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 3, 17, 'Diutuslah Rafael untuk menyembuhkan kedua-duanya, yaitu dengan menghapus bintik-bintik putih dari mata Tobit sehingga ia dapat melihat cahaya Allah dengan matanya sendiri, dan dengan memberikan Sara anak perempuan Raguel kepada Tobia bin Tobit sebagai isteri dan dengan melepaskannya dari Asmodeus, setan jahat itu. Memang Tobia lebih berhak memperoleh Sara dari semua orang lain yang ingin mengambilnya. Pada saat yang sama Tobit kembali dari pelataran itu masuk ke rumahnya dan Sara anak Raguel turun dari bilik atas itu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 1, 'Pada hari itu juga Tobit ingat kepada uang yang pernah dititipkannya pada Gabael di Ragai di negeri Media itu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 2, 'Lalu ia berpikir: "Aku sudah sampai meminta kematian bagi diriku. Mengapa gerangan tidak kupanggil anakku Tobia untuk kuberi petunjuk mengenai uang itu sebelum aku meninggal?"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 3, 'Maka dipanggilnya anaknya Tobia yang segera datang juga. Lalu kata Tobit: "Nak, apabila aku sudah mati nanti, kuburkanlah aku sebagaimana mestinya. Hormatilah ibumu dan jangan kautinggalkan sepanjang umur hidupnya. Lakukanlah apa yang menyenangkan hatinya dan jangan hatinya kausedihkan dengan kelakuanmu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 4, 'Ingatlah, nak, bahwa oleh karena engkau telah ditanggungnya banyak bahaya, yaitu waktu engkau masih dalam kandungannya. Setelah ibumu meninggal, kuburlah di sampingku dalam satu kubur.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 5, 'Nak, ingatlah juga kepada Tuhan; sepanjang umur hidupmu jangan sampai berdosa dan melanggar perintah-perintahNya. Hendaklah berbuat baik sepanjang hidupmu dan jangan menempuh jalan kelaliman.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 6, 'Sebab orang yang menjalankan kebenaran akan berhasil dalam segala usahanya,', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 7, 'sebagaimana halnya dengan semua orang yang berbuat baik. [Berilah sedekah dari harta milikmu. Matamu jangan menyesal apabila engkau memberikan sedekah. Muka jangan kaupalingkan dari seorang miskin, niscaya wajah Allahpun tidak akan dipalingkan dari padamu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 8, 'Berikanlah sedekah sesuai dengan besarnya kekayaanmu. Jika engkau hanya mempunyai sedikit, jangan takut memberikan sedekah seadanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 9, 'Dengan jalan itu kautimbun simpanan bagi dirimu untuk masa darurat.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 10, 'Memang sedekah melepaskan dari maut dan tidak membiarkan orang masuk ke dalam kegelapan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 11, 'Sedekah merupakan persembahan yang baik di hadapan Yang Mahatinggi bagi semua orang yang memberikannya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 12, 'Nak, jauhilah percabulan. lebih-lebih ambilah isteri keturunan nenek moyangmu. Jangan mengambil isteri luar yang tidak berasal dari suku ayahmu. Sebab kita ini adalah keturunan para nabi -- Nuh, Abraham, Ishak, Yakub, nenek moyang kita dari abad-abad yang lampau -- Ingatlah, nak, bahwa mereka mengambil isteri dari kaum kerabat mereka sendiri. Maka mereka diberkati dalam anak-anaknya. Ingatlah pula bahwa keturunan mereka akan mewarisi tanah yang telah dijanjikan Tuhan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 13, 'Oleh sebab itu, nak, cintailah sanak saudaramu dan jangan meninggikan hatimu terhadap sanak saudaramu serta anak-anak lelaki dan perempuan bangsamu, sehingga engaku enggan mengambil isterimu dari kalangan mereka. Sebab di dalam kecongkakan terletak kebinasaan dan banyak kegelisahan, dan dalam kemalasan terletak kepapaan dan kekurangan besar. Memang kemalasan adalah ibu kelaparan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 14, 'Janganlah upah orang manapun yang bekerja padamu sampai bermalam padamu. Sebaliknya bayarkanlah segera kepadanya. Apabila engkau mengabdi kepada Allah, niscaya engkau mendapat ganjaran. Berjaga-jagalah, nak, dalam segala pekerjaanmu dan hendaklah berlaku sebagai seorang yang terdidik baik dalam segenap tingkah lakumu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 15, 'Apa yang tidak kausukai sendiri, janglah kauperbuat kepada siapapun. Jangan minum anggur sampai mabuk dan kemabukan jangan menyertai dirimu di jalan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 16, 'Dari makananmu sendiri berikanlah kepada yang lapar dan dari pakaianmu sendiri kepada yang telanjang. Apa yang berlebih-lebihan padamu berikanlah sebagai sedekah; dan matamu jangan menyesal apabila engkau memberikan sedekah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 17, 'Sajikanlah dengan berlimpah-limpah makanan di atas kubur orang benar, tetapi jangan kauberikan kepada orang-orang berdosa.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 18, 'Mintalah setiap nasehat dari setiap orang yang arif dan jangan kauhina nasehat yang bermanfaat.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 19, 'Pujilah Tuhan Allah setiap waktu dan mintalah kepadaNya, supaya segala jalan hidupmu menjadi lurus dan supaya segala usaha serta rencanamu berhasil baik. Sebab tiada bangsa satupun mempunyai nasehat], melainkan segala nasehat yang baik diberikan oleh Tuhan. Tetapi kalau Tuhan mau maka Ia merendahkan sampai ke lubuk dunia orang mati, sebagaimana yang dikehendakiNya. Dan kini, nak, ingatlah kepada segala petunjukku dan jangan sampai terhapus dari hatimu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 20, 'Oleh sebab itu, nak, aku hendak memberitahukan kepadamu tentang sepuluh talenta perak yang telah kutitipkan pada Gabael bin Gabria di Ragai di negeri Media.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 4, 21, 'Jangan takut-takut, nak, oleh karena kita sudah jatuh miskin. Memang harta milikmu banyak, apabila engkau takut akan Allah dan menjauhkan diri dari setiap dosa lagi melakukan apa yang berkenan pada Tuhan Allahmu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 1, 'Maka menjawablah Tobia kepada Tobit, ayahnya: "Pak, semuanya yang telah bapak perintahkan kepadaku hendak kulakukan juga.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 2, 'Tetapi bagaimana aku dapat mengambil uang itu dari Gabael? Ia tidak mengenal aku dan akupun tidak mengenal orang itu pula. Tanda apa yang mesti kuberikan kepadanya, supaya ia mengenal aku, percaya kepadaku dan uang itu diserahkannya. Aku tidak mengenal pula jalan-jalan di negeri Media yang harus kutempuh.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 3, 'Maka jawab Tobit kepada anaknya Tobia: "Gabael telah memberikan tanda tangan kepadaku yang dibubuh pada sebuah naskah dan demikian akupun kepadanya pula. Maskah itu telah kubagikan jadi dua dan kami masing-masing mengambil separuhnya. Lalu kutitipkan uang itu kepadanya. Sekarang sudah dua puluh tahun uang itu sudah kutitipkan. Lagi, anakku, carilah untukmu seseorang yang dapat dipercaya dan yang mau pergi bersama denganmu. Kita memang akan memberikan upah kepadanya hingga engkau kembali. Kemudian pergilah mengambil uang itu dari pada Gabael."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 4, 'Maka keluarlah Tobia untuk mencari seseorang yang mau pergi bersama dengannya ke negeri Media dan yang tahu jalannya. Didapatinya malaekat Rafael yang berdiri di hadapan Tobia. Hanya Tobia tidak tahu bahwa dia itu seorang malaikat Tuhan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 5, 'Berkatalah Tobia kepadanya: "Darimana engkau, hai pemuda?" Sahutnya: "Dari saudara-saudaramu, orang Israel. Aku datang kemari untuk mencari pekerjaan." Tobia pun lalu bertanya kepadanya: "Tahukah engkau jalan ke negeri Media?"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 6, 'Jawabnya: "Aku tahu! Seringkali aku kesana dan akupun mengenal segala jalan juga. Sudah kerapkali aku ke negeri Media dan aku sudah pernah menginap pada Gabael, saudara kita yang bertempat di Ragai, di negeri Media, yang terletak di pegunungan. Perjalanannya dari kota Ekbatana hingga ke kota Ragai dua hari biasa."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 7, 'Lalu kata Tobia kepadanya: "Tunggu dahulu, hai pemuda. Aku hendak mengatakannya kepada ayahku di rumah. Perlulah kiranya engkau pergi bersama daku.Upahpun akan kuberikan kepadamu juga."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 8, 'Sahut Rafael kepadanya: "Aku akan menunggu, tetapi jangan lama-lama!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 9, 'Maka Tobia masuk dan memberitahu ayahnya, Tobit. Katanya: "Sudah pak, aku sudah mendapat seseorang dari antara saudara-saudara kita, orang Israel." Sahut Tobit kepadanya: "Panggilkanlah aku orang itu, nak, supaya aku tahu bangsa apa ia dan dari suku mana dan apa ia boleh dipercaya untuk pergi bersama denganmu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 10, 'Tobiapun keluarlah dan memanggil dia. Katanya: "Pemuda, ayahku memanggilmu." Rafael masuk dan oleh Tobit diberi salam dahulu. Ia menjawab dengan banyak-banyak salam pula. Lalu Tobit menyambung: "Apakah aku masih mendapat salam juga? Aku ini orang yang rusak matanya dan cahaya langit tidaklah kulihat. Melainkan duduklah aku dalam kegelapan seperti orang mati yang tidak memandang cahaya. Hidupku berada di tengah orang-orang mati. Suara manusia kudengar, tetapi mereka tidak kulihat!" Sahut Rafael kepadanya: "Tetapkan hati! Penyembuhan dari Allah sudah dekat. Tetapkan hati!" Lalu Tobit berkata kepadanya: "Anakku Tobia mau pergi ke negeri Media. Adakah engkau dapat pergi bersama dengannya dan mengantar dia? Dan lagi, saudara, engkau akan kuberi upahmu juga!" Sahut Rafael: "Aku mau pergi bersama dengannya. Semua jalan kukenal baik-baik. Sudah sering kali aku pergi ke negeri Media dan menjelajahi dataran-dataran dan pegunungannya. Segala jalannya kuketahui."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 11, 'Tobit menyambung pula: "Saudara dari keluarga mana dan dari suku mana? Nyatakanlah kepadaku, saudara!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 12, 'Sahut Rafael: "Apa perlunya suku itu?" Tobitpun lalu berkata kepadanya: "Aku hanya mau tahu kebenaran saja, siapa engkau dan siapa namamu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 13, 'Sahut Rafael: "Aku ini Azarya bin Ananias yang besar, seorang saudaramu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 14, 'Maka Tobit berkata: "Selamat datang saudara, dan banyak salam! Jangan kecil hati, saudara, karena aku ingin tahu kebenaran tentang keluargamu. Kebetulan engkau kerabat kami juga. Engkau sungguh dari keluarga mulia dan baik. Ananias dan Natan, kedua anak Semeya yang besar kukenal. Bersama dengan aku mereka dahulu pergi ke Yerusalem dan bersembah sujud di sana. Mereka tidak menyimpang dari jalan yang baik. Saudara-saudaramu sungguh-sungguh orang yang baik. Engkau berasal dari akar yang baik. Selamat datang!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 15, 'Tobit menyambung lagi: "Aku hendak memberikan upah kepadamu sedirham sehari dan penghidupan seperti penghidupan anakku sendiri.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 16, 'Hendaklah pergi bersama dengan anakku, maka aku akan menambah lagi upahmu itu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 17, 'Sahut Rafael: "Aku mau pergi bersama dengan anakmu. Jangan kuatir! Kami berangkat dengan sehat walafiat dan dengan sehat walafiat kami nanti kembali pula! Sebab jalannya aman." Sahut Tobit: "Tuhan memberkati engkau, saudara." Kemudian dipanggilnya anaknya dan berkatalah ia kepadanya: "Bersiap-siaplah, nak, untuk perjalanan itu dan pergilah bersama dengan saudaramu ini. Semoga Allah yang ada di sorga melindungi kamu berdua di sana dan mengantar kamu kembali kepadaku dengan sehat walafiat. Semoga malaikat Tuhan menyertai kamu di jalan dengan perlindungannya." Maka keluarlah Tobia untuk berangkat. Ia memeluk ayah serta ibunya. Berkatalah Tobit kepadanya: "Selamat jalan!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 18, 'Tetapi ibunya menangis dan berkata kepada Tobit: "Mengapa anakku kausuruh pergi? Bukankah ia penopang kita yang sudah lanjut usia, oleh karena tetap dapat melayani kita?', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 19, 'Uang sebenarnya tidak lebih dari uang saja. Masakan uang itu menjadi pengganti anak kita!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 20, 'Cukuplah bagi kita hidup sebagaimana dianugerahkan Tuhan kepada kita."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 21, 'Sahut Tobit: "Jangan berkhayal, adinda! Anak kita berangkat dengan sehat walafiat dan dengan sehat walafiat ia nanti kembali pula. Dengan mata kepala sendiri adinda akan melihat dia pada hari ia kembali kepada adinda dengan sehat walafiat!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 22, 'Jangan berkhayal, jangan takut-takut, adinda, oleh karena mereka. Sebab malaikat baik menyertai anak kita dan perjalanannya akan berlangsung dengan baik. Nanti ia kembali dengan sehat walafiat."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 5, 23, 'Maka isterinya berhenti menangis.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 1, 'Adapun anak muda itu berangkat dengan disertai malaikat itu. Anjingpun ikut serta dengan mereka. Mereka beruda berjalan terus. Ketika menjadi malam pada hari pertama bermalamlah mereka di dekat sungai Tigris.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 2, 'Pemuda itu turun untuk membasuh kakinya di sungai Tigris. Tetapi dari dalam airnya melonjaklah seekor ikan besar mau menelan kaki pemuda itu. Maka menjeritlah ia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 3, 'Tetapi kata malaikat itu kepadanya: "Tangkaplah dan peganglah ikan itu!" Ikan itupun lalu digagahi oleh pemuda itu dan dihelanya ke darat.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 4, 'Kemudian malaikat itu menyuruh: "Siatlah ikan itu, ambillah kantung empedu, jantung dan hatinya simpanlah. Isi perutnya hendaknya kau buang. Sebab empedu, jantung dan hatinya adalah obat mujarab."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 5, 'Maka disiatlah ikan itu oleh pemuda itu dan dipungutlah kantung empedu, jantung dan hati. Ikan itu dipanggangnya, lalu dimakannya dan sebagian diasinkannya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 6, 'Lalu berjalanlah mereka terus bersama sampai di dekat negeri Media.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 7, 'Maka bertanyalah pemuda itu pada malaikat itu: "Saudara Azarya, obat apa yang ada di dalam jantung dan hati ikan itu dan di dalam empedunya?"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 8, 'Sahut malaekat itu: "Jantung dan hati itu boleh diasapkan di depan laki-laki atau perempuan yang kerasukan setan atau roh jahat. Lalu segenap gangguan lenyap dari padanya dan tidak tinggal lagi padanya untuk selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 9, 'Empedu itu hendaknya diurapkan pada orang yang matanya kena bintik-bintik putih, niscaya bintik-bintik itupun hanya tinggal ditiupi saja lalu sembuh pulalah orang itu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 10, 'Mereka memasuki negeri Media dan sudah sampai di dekat kota Ekbatana.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 11, 'Lalu berkatalah Rafeal kepada pemuda Tobia: "Hai saudara Tobia!" Sahutnya: "Ada apa?" Rafeal menyambung pula: "Malam ini kita harus bermalam pada Raguel. Dia itu seorang kerabatmu dan mempunyai seorang anak perempuan yang bernama Sara.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 12, 'Kecual Sara ia tidak mempunyai anak laki-laki atau perempuan. Maka dari itu saudaralah kerabatnya yang paling dekat. Lebih dari siapapun saudara berhak untuk memperoleh anaknya sebagai istri dan juga berhak mewarisi apa saja yang ada pada ayahnya. Gadis itu berbudi, berani dan sangat cantik. Ayahnyapun baik hati pula."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 13, 'Katanya lagi: "Engkau sungguh berhak mengambil dia. Saudara, dengarkanlah aku. Pada malam ini juga aku hendak berbicara dengan ayahnya tentang gadis itu, supaya kuperoleh bagianmu sebagai mempelai. Setelah kembali dari Ragai kita akan merayakan nikahnya. Aku yakin bahwa Raguel tidak dapat menolak atau menunangkannya kepada orang lain. Sebab kalau demikian ia patut dihukum mati menurut ketetapan kitab Musa setelah diketahuinya bahwa engkaulah yang lebih berhak dari orang manapun untuk memperoleh anaknya sebagai isteri. Jadi, saudara, dengarkanlah aku. Malam ini juga kita akan berbicara tentang gadis itu dan kita pinang bagimu. Setelah nanti kembali dari Ragai akan kita ambil dan kita antarkan dia ke rumahmu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 14, 'Tobiapun lalu menjawab kepada Rafael: "Saudara Azarya, telah kudengar bahwa gadis itu sudah diberikan kepada tujuh laki-laki. Tetapi mereka mati semua di kamar tidur. Pada malam mereka datang padanya mareka mati seketika juga. Kudengar orang berkata bahwa mereka dibunuh oleh seorang setan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 15, 'Dari sebab itu aku sekarang takut-takut, sebab setan itu tidak berbuat jahat kepada gadis itu sendiri, tetapi apabila seseorang mau menghampiri dia maka dibunuh seketika oleh setan itu. Aku ini akan tunggal ayahku dan aku tidak mau mati dan begitu membawa hidup ayah dan ibuku ke liang kubur karena kesedihan atas diriku. Anak lain tidak ada pada mereka untuk menguburkannya."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 16, 'Maka berkatalah malaikat itu kepadanya: "Tidakah engkau ingat akan perintah-perintah ayahmu; bahwa ia memerintahkan kepadamu untuk mengambil istri dari keluarga ayahmu? Maka dari itu, saudara, dengarkanlah aku! Jangan ambil pusing tentang setan itu; ambil saja gadis itu! Memang aku tahu bahwa malam ini juga gadis itu diberikan kepada saudara sebagai isteri.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 17, 'Kalau nanti masuk ke dalam kamar tidur ambillah sedikit dari hati dan jantung ikan itu dan taruhlah di atas bara pedupaan. Harumnya akan semerbak dan segera setelah dihirup oleh setan itu maka ia akan lari dan tak pernah muncul lagi pada gadis itu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 18, 'Waktu engkau mau bersatu dengannya hendaklah kamu berdua berdiri dahulu untuk berdoa. Mohonlah kepada Tuhan semesta langit, moga-moga Ia berbelas kasihan kepada kamu dan melindungi kamu. Jangan takut, gadis itu diuntukkan bagimu sejak sediakala dan engkaulah yang akan menyelamatkannya. Ia pasti akan berangkat bersama denganmu dan kukira engkau mendapat anak dari padanya, yang seolah-olah akan menjadi saudara-saudaramu. Jangan ambil pusing!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 6, 19, 'Ketika Tobia mendengar perkataan Rafael itu dan bahwa Sara adalah saudarinya dari keluarga dan keturunan ayahnya, maka gadis itu sangat dicintainya dan hatinya segera berpaut padanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 1, 'Ketika mereka tiba di kota Ekbatana berkatalah Tobia kepada temannya: "Saudara Azarya, antarkanlah aku langsung ke rumah Raguel saudara kami." Iapun mengantarkannya ke rumah Raguel. Raguel didapati mereka duduk pada pintu pelataran rumahnya. Mereka memberikan salam dahulu kepadanya dan dibalas oleh Raguel. Katanya: "Banyak-banyak salam, saudara-saudara. Selamat datang!" Mereka dipersilakan masuk ke rumah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 2, 'Kemudian kata Raguel kepada Edna, isterinya: "Alangkah miripnya pemuda itu dengan saudaraku Tobit!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 3, 'Ednapun lalu bertanya kepada mereka: "Dari mana kalian, hai saudara-saudara?" Sahut mereka: "Dari bani Naftali, dari kaum buangan di kota Niniwe."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 4, 'Maka berkatalah Edna kepada mereka: "Kenalkah kamu Tobit, saudara kami?" Jawab mereka: "Kami kenal."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 5, 'Edna bertanya pula kepada mereka: "Sehat walafiatkah ia?" Sahut mereka: "Ia masih hidup dan sehat walafiat." Lalu berkatalah Tobia: "Ia adalah ayahku."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 6, 'Maka melonjaklah Raguel. Ia memeluk Tobia sambil menangis lalu berkata: "Tuhan memberkati engkau, nak! Engkau adalah anak orang yang mulia dan baik! Alangkah celakanya orang yang benar dan penderma itu menjadi buta!" Iapun mendekap Tobia, saudaranya, sambil menangis.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 7, 'Pun pula isterinya Edna dan anak mereka Sara menangis.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 8, 'Kemudian Raguel menyembelih seekor domba betina dari kawanannya dan disambutnyalah mereka dengan ramah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 9, 'Setelah mereka mencuci dan membasuh diri dan sudah duduk makan maka berkatalah Tobia kepada Rafael: "Saudara Azarya, katakanlah kepada Raguel, supaya saudariku Sara diberikannya kepadaku."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 10, 'Mendengar perkataan itu berkatalah Raguel kepada pemuda itu: "Makan dan minumlah dan bersenang-senanglah malam ini. Memang, saudara, tiada seorangpun lebih berhak mengambil Sara, anakku, sebagi isterinya dari padamu. Karena itupun aku tidak berwenang lagi memberikannya kepada seseorang kecuali kepadamu. Sebab engkaulah yang paling akrab. Tetapi, anakku, aku mesti memberitahukan kebenaran!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 11, 'Sudah kuberikan Sara kepada tujuh laki-laki dari antara saudara kita, tetapi pada malam ia mereka hampiri matilah mereka semua. Maka, anakku, baiklah sekarang makan dan minum saja. Tuhan akan mengambil tindakan bagimu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 12, 'Tetapi sahut Tobia: "Aku tidak akan makan atau minum apa-apa, sampai engkau mengambil keputusan tentang diriki." Menjawablah Raguel: "Baiklah! Ia diberikan kepadamu sesuai dengan ketetapan Kitab Musa. Dari Sorga sudah diputuskan, bahwa ia harus diberikan kepadamu. Maka hendaklah menerima saudarimu ini. Mulai sekarang ini engkau menjadi saudaranya dan iapun menjadi saudarimu pula. Semenjak hari ini ia diberikan kepadamu selama-lamanya. Dan, anakku, semoga kamu pada malam ini juga dianugerahi oleh Tuhan semesta langit. Semoga Ia menurunkan kasih setia dan damai sejahtera atas diri kamu."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 13, 'Lalu Raguel memanggil Sara anaknya dan iapun datang kepadanya pula. Tangan Sara dipegang oleh Raguel dan demikian Sara diserahkannya kepad Tobia. Dalam pada itu berkatalah Raguel: "Sungguh, sesuai dengan Hukum Taurat ia kupercayakan kepadamu dan seturut ketetapan yang tersurat dalam Kitab Musa kuberikan kepadamu menjadi isterimu. Ambillah dia dan antarkanlah kepada ayahmu dengan sehat walafiat. Moga-moga Yang berkuasa di Sorga menganugerahkan damai sejahtera kepada kamu berdua."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 14, 'Lalu dipanggilnya ibu Sara untuk mengambil sepucuk gulungan. Ditulisnya perjanjian perkawinan dan dengan demikian Sara diserahkannya menjadi isteri Tobia, sesuai dengan ketetapan Taurat Musa. Sesudah itu mulailah mereka makan dan minum.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 15, 'Raguel memanggil Edna, isterinya, lalu berkata kepadanya: "Dinda, siapkanlah sebuah kamar yang lain lalu antarkanlah Sara masuk."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 16, 'Maka pergilah Edna menyediakan sebuah kamar sebagaimana dikatakan kepadanya, lalu mengantar Sara masuk ke dalam. Ia menangis oleh karena anaknya, lalu diucapnya air matanya dan berkatalah ia kepada Sara:', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 7, 17, '"Tetapkan hatimu, nak! Tuhan semesta langit akan menganugerahkan kepadamu sukacita ganti dukacitamu. Tetapkan hati, nak!" Lalu keluarlah ia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 1, 'Selesai makan dan minum mereka mau pergi tidur semua. Pemuda itu diantar ke luar untuk masuk ke kamar tersebut.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 2, 'Maka ingatlah Tobia kepada perkataan Rafael. Diambilnya hati serta jantung ikan itu dari dalam buntilnya yang dibawanya, lalu ditaruhnya di atas bara pedupaan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 3, 'Harum ikan itu mengganggu setan itu, yang segera lari ke daratan tinggi Mesir. Adapun Rafael pergi mengikat kakinya dan segera dikebatnya juga.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 4, 'Maka keluarlah semua orang dari kamar itu dan pinunya dikunci. Kemudian Tobia bangkit dari tempat tidur dan berkata kepada Sara: "Bangunlah, adinda, mari kita berdoa dan mohon kepada Tuhan kita, semoga dianugerahkanNya belas kasihan serta perlindungan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 5, 'Maka bangunlah Sara dan mereka berdua dan mohon, supaya mereka mendapat perlindungan. Mereka angkat doa sebagai berikut: Terpujilah Engkau, ya Allah nenek moyang kami, dan terpujilah namaMu sepanjang sekalian abad. Hendaknya sekalian langit memuji Engkau dan juga segenap ciptaanMu untuk selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 6, 'Engkaulah yang telah menjadikan Adam dan baginya telah Kaubuat Hawa isterinya sebagai pembantu serta penopang; dari mereka berdua lahirlah umat manusia seluruhnya. Engkaulah bersabda pula: Tidak baik, kalau manusia itu seorang diri saja, mari Kita menjadikan penolong baginya, yang sepadan dengan dia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 7, 'Bukan karena nafsu birahi sekarang kuambil saudariku ini, melainkan dengan hati yang benar. Sudilah kiranya mengasihani aku ini dan dia dan membuat kamu menjadi tua bersama."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 8, 'Serentak berkatalah mereka: "Amin! Amin!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 9, 'Kemudian mereka tidur semalam-malaman.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 10, 'Tetapi Raguel bangun dan dipanggilnya beberapa bujangnya yang pergi menggali kubur. Sebab Raguel berpikir: "Tidak boleh tidak Tobia mati. Nanti kami menjadi tertawaan dan orang ternista!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 11, 'Selesai menggali kubur itu Raguel masuk rumah dan dipanggilnya isterinya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 12, 'Katanya: "Suruhlah seorang sahaya masuk untuk melihat apa ia masih hidup. Kalau sudah mati kita kuburkan tanpa diketahui seorangpun."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 13, 'Sahaya itupun lalu disuruh, lampu dipasang dan pintu dibuka. Masuklah sahaya itu dan didapatinya mereka tertidur dengan nyenyaknya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 14, 'Maka sahaya itu keluar dan diberitahukannya kepada Raguel serta isterinya bahwa Tobia masih hidup dan tidak terjadi apa-apa.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 15, 'Maka mereka memuji Yang Berkuasa di sorga, katanya: "Terpujilah Engkau, ya Allah, dengan segala pujian yang murni, hendaklah Engkau dipuji untuk selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 16, 'Terpujilah Engkau, karena aku telah Kaugembirakan; apa yang kusangka tidak terjadi. Sebaliknya kami telah Kauperlakukan menurut belas kasihMu yang besar.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 17, 'Terpujilah Engkau, karena kedua anak tunggal itu telah Kaukasihani. Berilah mereka, ya Tuhan, belas kasihan dan perlindungan, dan biarlah mereka meneruskan hidup mereka dengan senang dan belas kasihan!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 18, 'Kemudian disuruhnya bujang-bujang itu menimbus kubur itu sebelum fajar menyingsing.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 19, 'Raguel menyuruh isterinya membuat banyak roti. Ia sendiri pergi ke kawanan dan diambilnya dua lembu jantan dan empat domba jantan yang disuruhnya disediakan. Maka mulai orang dengan persiapan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 20, 'Kemudia Raguel memanggil Tobia dan berkata kepadanya: "Selama empat hari ini sekali-kali tidak boleh engkau berangkat dari sini, melainkan engkau harus tinggal disini untuk makan dan minum. Engkau mesti menggembirakan hati anakku yang telah sedih pedih.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 8, 21, 'Kemudian barulah dapat engkau mengambil dari milikku di sini dan pulang dengan selamat kepada ayahmu. Separuh lainnya dari milikku menjadi kepunyaanmu juga setelah aku serta isteriku meninggal. Tetapkanlah hatimu, nak! Akulah bapamu dan Edna ibumu. Kami menjadi kerabat dengan engkau seperti kami kerabat dengan saudarimu, mulai sekarang sampai selama-lamanya. Tetapkanlah hati, nak!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 1, 'Kemudian Tobia memanggil Rafael dan berkata kepadanya:', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 2, '"Saudara Azarya, hendaklah engkau mengambil sertamu empat orang bujang dan dua ekor unta. Baiklah engkau berangkat ke kota Ragai dan pergi ke Gabael. Hendaklah engkau menyerahkan kepadanya surat bukti ini lalu memungut uang itu. Dan lagi hendaklah engkau membawa dia sertamu ke pernikahan nanti.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 3, 'Engkau tahu bahwa ayahku membilang-bilang hari. Apabila aku berayal-ayalan, niscaya ayahku sangat sedih hati.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 4, 'Dan engkaupun tahu baik-baik apa yang telah dijanjikan oleh Raguel dengan sumpah dan sumpah itu tidak dapat kulanggar."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 5, 'Maka berangkatlah Rafael dengan disertai empat bujang dan dua ekor unta itu ke kota Ragai di negeri Media. Ia bermalam pada Gabael. Kepadanya diserahkannya surat bukti tadi dan diberitahukannya tentang Tobia bin Tobit, yakni bahwasanya ia telah mengambil isteri, dan ia mengundang Gabael juga ke pernikahan itu. Maka Gabael bangkit dan dibilangnya kantung-kantung yang masih bermeterai itu. Lalu dimuatkannya semua.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 9, 6, 'Pagi-pagi benar berangkatlah mereka berdua dan kemudian tiba pada pesta pernikahan itu. Mereka masuk ke rumah Raguel dan mendapati Tobia sedang makan. Maka Tobia melonjak berdiri, lalu diberi salam oleh Gabael. Gabael memberkati Tobia sambil menangis, katanya: "Anak mulia dan baik dari bapak yang mulia dan baik, benar dan penderma! Moga-moga Tuhan semesta langit memberkati engkau serta isterimu, ayah dan ibu isterimu. Terpujilah Allah, karena aku telah dapat melihat gambaran Tobit, saudara sepupuku!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 1, 'Dalam pada itu Tobit hari demi hari menghitung waktu yang diperlukan untuk pergi pulang. Setelah waktu itu genap dan anaknya belum tiba juga', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 2, 'maka pikirnya: "Boleh jadi ia tertahan di sana? Atau barangkali Gabael sudah meninggal, sehingga tidak ada seorangpun menyerahkan uang itu kepadanya?"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 3, 'Dan ia mulai merasa sedih.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 4, 'Hana, isterinya, berkata kepada Tobit: "Memang anakku sudah jatuh binasa dan tidak ada lagi di tengah-tengah orang-orang yang hidup!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 5, 'Ia mulai menangisi serta meratapi anaknya, katanya: "Celakalah aku ini, hai anakku, oleh karena kubiarkan engkau pergi, engkau yang menjadi cahaya mataku!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 6, 'Maka berkatalah Tobit kepadanya: "Diamlah, jangan berkhayal, adinda. Ia sehat walafiat! Memang mereka terhalang di sana. Orang yang berangkat serta Tobia dapat dipercaya. Ia adalah seorang dari antara saudara-saudara kita. Jangan sedih hati oleh karena anak kita, adinda. Nanti ia muncul!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 7, 'Tetapi Hana menyahut kepadanya: "Diam! Jangan memperdayakan aku! Anakku binasa sudah!" Setiap hari berulang-ulang Hana ke luar untuk menengok jalan yang telah ditempuh anaknya waktu pergi. Ia tidak percaya lagi pada siapapun. Setelah matahari terbenam barulah ia pulang, tetapi semalam-malaman ia meratap dan menangis dan tidak dapat tidur.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 8, 'Setelah genaplah empat belas hari pesta pernikahan itu yang dengan sumpah dijanjikan Raguel untuk dirayakan bagi anaknya, maka datanglah Tobia kepadanya, katanya: "Izinkanlah aku pulang, sebab aku tahu bahwa ayah ibuku sudah tidak berharap lagi akan melihat aku. Dan sekarang aku mohon bapak, supaya bapak membiarkan aku pulang kepada ayahku. Sudah kuberitahukan kepadamu, bagaimana ayahku kutinggalkan."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 9, 'Tetapi sahut Raguel kepada Tobia: "Tinggal saja, nak, tinggal padaku di sini. Aku akan mengutus pesuruh kepada Tobit, ayahmu, untuk memberitahukan tentang keadaanmu." Tetapi Tobia menyahut: "Jangan, pak, aku mohon, supaya engkau membiarkan aku pulang dari sini kepada ayahku."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 10, 'Maka bangkitlah Raguel dan diserahkannya kepada Tobia Sara, isterinya, dan separuh dari miliknya, yaitu budak sahaya, lembu jantan dan domba, keledai dan unta, pakaian, uang dan perabot.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 11, 'Demikianlah mereka diizinkannya pergi dengan sehat walafiat. Ia memberikan salam kepada mereka, katanya: "Salam, nak, selamat jalan! Moga-moga Tuhan semesta langit menganugerahi engkau serta Sara, isterimu. Dan moga-moga aku masih melihat anak-anak kamu, sebelum aku meninggal."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 12, 'Kepada anaknya Sarapun ia berkata juga: "Pergilah kepada mertuamu. Sebab mulai sekarang ini merekalah orang tuamu, seolah-olah melahirkan engkau. Pergi dengan selamat, nak; biarlah aku mendengar kabar baik tentang dirimu selama aku hidup!" Lalu ia dipeluknya dan dibiarkannya mereka pergi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 13, 'Adapun Edna berkata kepada Tobia: "Anak dan saudaraku yang tercinta, moga-moga Tuhan mengantar engkau pulang dan mudah-mudahan aku masih melihat selama hidupku anak-anakmu dan anak-anak Sara, anakku, sebelum aku meninggal. Di hadapan Tuhan anakku kupercayakan kepadamu sebagai petaruh. Jangan menyedihkan hatinya sepanjang umur hidupmu. Pergilah dengan selamat, anakku! Mulai sekarang ini akulah ibumu dan Sara menjadi saudarimu. Moga-moga kita sekalian hidup bahagia sepanjang umur hidup kita, seperti halnya sekarang ini." Lalu diberinya salam kepada mereka dan dibiarkannya mereka pergi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 10, 14, 'Tobiapun lalu berangkat dari Raguel dengan sehat walafiat. Dengan sukacita dipujinya Tuhan semesta langit dan bumi, Raja segala-galanya, oleh karena Tuhan telah membuat perjalanannya berhasil. Iapun memberkati Raguel dan Edna isterinya, dan berkata', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 1, 'Ketika mereka mendekati daerah Kaserin yang letaknya berhadapan dengan Niniwe berkatalah Rafael:', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 2, '"Engkau tahu dengan keadaan bagaimanakah kita meninggalkan ayahmu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 3, 'Karena itu baiklah kita berdua mendahului isterimu untuk menyiapkan rumah itu, sedangkan yang lain-lain meneruskan perjalanannya."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 4, 'Maka bertolaklah mereka berdua. Rafaelpun sudah berkata kepada Tobia: "Bawalah empedu itu juga." Adapun anjing itu mengikuti Rafael dan Tobia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 5, 'Dalam pada itu duduklah Hana mengamati jalan yang harus ditempuh oleh anaknya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 6, 'Iapun mendapati firasat bahwa anaknya tengah datang. Berkatalah Hana kepada ayah Tobia: "Sungguh anakmu telah datang dan juga orang yang menyertainya."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 7, 'Sebelum Tobia mendekati ayahnya berkatalah Rafael kepadanya: "Aku yakin bahwa mata ayahmu akan dibuka."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 8, 'Sapulah empedu ikan itu kepada matanya. Obat itu akan memakan dahulu, lalu mengelupaskan bintik-bintik putih itu dari matanya. Maka ayahmu akan melihat lagi dan memandang cahaya."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 9, 'Adapun Hana bergegas-gegas mendekap anaknya, lalu berkatalah ia kepadanya: "Setelah engkau kulihat, anakku, maka mulai sekarang aku dapat mati." Maka ia menangis.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 10, 'Tobitpun berdiri dan meskipun kakinya tersandung namun ia keluar dari pintu pelataran rumah.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 11, 'Tobia menghampirinya dengan empedu ikan itu di tangan lalu ditiupinya mata Tobit. ditopangnya ayahnya dan kemudian berkatalah ia kepadanya: "Tetapkan hati, pak!" Selanjutnya obat itu dikenakannya padanya dan dibiarkannya sebentar.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 12, 'Lalu dengan kedua tangannya dikelupaskannya sesuatu dari ujung-ujung matanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 13, 'Maka Tobit mendekap Tobia sambil menangis. Katanya: "Aku melihat engkau, anakku, cahaya mataku!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 14, 'Ia menyambung pula: "Terpujilah Allah, terpujilah nama-Nya yang besar, terpujilah para malaikat-Nya yang kudus. Hendaklah nama Tuhan yang besar ada di atas kita dan terpujilah hendaknya segala malaikat untuk selama-lamanya. Sungguh aku telah disiksa oleh Tuhan, tetapi kulihat anakku Tobia!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 15, 'Kemudian masuklah Tobia ke rumah dengan sukacita sambil memuji Allah dengan segenap hatinya. Diceritakannya kepada ayahnya bahwa perjalanannya berhasil baik; bahwa ia telah membawa uang itu dan sudah mengambil Sara anak perempuan Raguel menjadi isterinya dan bahwa isterinya masih dalam perjalanan dan sudah dekat pada pintu gerbang kota Niniwe.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 16, 'Maka keluarlah Tobit menjemput anak menantunya pada pintu gerbang kota Niniwe dengan sukacita seraya memuji Allah. Melihat Tobit berjalan dan maju dengan kekuatannya seperti dahulu tanpa diantar oleh siapapun maka tercengang-cenganglah penduduk kota Niniwe. Tobitpun lalu memaklumkan di hadapan mereka bahwa ia telah dikasihani oleh Allah yang telah mencelikkan matanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 17, 'Akhirnya Tobit mendekati Sara, isteri anaknya Tobia, lalu diberkatinya dengan berkata: "Selamat datang, anakku. Terpujilah Allahmu yang mengantar engkau kepada kami, hai anakku! Tuhan memberkati ayahmu, memberkati anakku Tobia dan memberkati engkau sendiri, hai anakku. Masuklah ke rumahmu dengan selamat, dengan berkat dan gembira! Masuklah, hai anakku!"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 18, 'Pada hari itu juga terjadilah kegembiraan untuk semua orang Yahudi yang diam di kota Niniwe.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 11, 19, 'Kemenakan Tobit, yaitu Ahikar dan Nadab, ikut bergembira pula dengan Tobit.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 1, 'Setelah perayaan nikah itu selesai maka Tobit memanggil anaknya Tobia. Berkatalah ia kepadanya: "Nak, ingatlah memberikan upahnya kepada orang yang telah menyertai engkau. Dan ingatlah menambah upahnya juga."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 2, 'Sahut Tobia: "Berapa banyaknya upah yang harus kuberikan, pak? Aku tidak menderita rugi sedikitpun, kalau kuberikan kepadanya separuh dari harta benda yang telah kubawa.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 3, 'Dengan sehat walafiat aku telah diantar kembali olehnya, isteriku telah disembuhkan olehnya; iapun telah membawa uang itu bersama dengan aku dan ayah telah disembuhkannya pula. Berapa banyaknya upah yang mesti kuberikan karena itu?"', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 4, 'Berkatalah Tobit kepadanya: "Memang nak, sudah seadilnya ia diambilkan separuh dari segala sesuatunya yang telah dibawanya waktu datang."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 5, 'Maka ia diapnggil dn Tobit berkata kepadanya: "Ambilah sebagai upahmu separuh dari segala sesuatunya yang kaubawa waktu datang, lalu engkau boleh pergi dengan selamat."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 6, 'Tetapi Rafael meamnggil kedua orang itu sendiri-sendiri lalu berkata kepada mereka: "Pujilah Allah dan muliakanla Dia di depan mata semua orang yang hidup karena segala anugerah yang telah diberikanNya kepad kamu. Pujilah namaNya dan bernyanyi-nyanyilah kepadaNya. Wartakanlah kepada segala manusia perbuatan-perbuatan Allah sebagaimana layaknya. Jangan berayal memuliakan Dia.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 7, 'Memang baiklah rahasia raja disembunyikan, tetapi pantaslah perbuatan Allah disingkapkan dan dimuliakan. Lakukanlah yang baik, niscaya malapetaka tidak akan menimpa kamu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 8, 'Lebih baiklah doa benar dan sedekah jujur daripada kekayaan yang lalim.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 9, 'Memang sedekah melepaskan dari maut dan menghapus setiap dosa. Orang yang melakukan sedekah akan menjadi puas dengan umurnya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 10, 'Sebaliknya, orang yang berbuat dosa dan lalim menjadi seteru hidupnya sendiri.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 11, 'Segenap kebenaran hendak kuwartakan kepada kamu dan tidak kusembunyikan apa-apa terhadap kamu. Sudah kutandaskan kepadamu: Baiklah rahasia raja disembunyikan, tetapi pantaslah perbuatan Allah disingkapkan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 12, 'Makanya, ketika engkau dan Sara berdoa maka ingatan akan doamu itu kusampaikan ke hadapan kemuliaan Tuhan. Dan demikianpun waktu engkau menguburkan orang-orang mati.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 13, 'Ketika engkau tidak ayal-ayalan dan bangkit serta meninggalkan makananmu untuk pergi mengapani mayat itu, maka aku diutus untuk mencobai engkau.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 14, 'Lagipula aku diutus oleh Allah untuk menyembuhkan baik engkau sendiri maupun Sara, menantumu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 15, 'Aku ini Rafael, satu dari ketujuh malaikat yang melayani di hadapan Tuhan yang mulia."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 16, 'Maka terperanjatlah kedua orang itu lalu sujud menyembah dan ketakutan.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 17, 'Tetapi berkatalah malaikat itu kepada mereka: "Jangan takut; damai sejahtera dengan kamu. Pujilah Allah selama-lamanya!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 18, 'Waktu aku ada dengan kamu, maka bukan karena kerelaanku sendirilah terjadi demikian, melainkan karena kehendak Allah. Maka pujilah Dia seumur hidup, bernyanyi-nyanyilah kepada-Nya!', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 19, 'Telah kamu perhatikan bahwa aku tidak makan apa-apa. Hanya suatu penglihatan yang kamu lihat.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 20, 'Oleh sebab itu, pujilah Tuhan di atas bumi dan muliakanlah Allah! Camkanlah! Aku naik kepada Dia yang telah mengutus aku. Tuliskanlah semuanya yang telah terjadi pada kamu." Maka iapun naik juga.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 21, 'Ketika bangkit mereka tidak dapat melihatnya lagi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 12, 22, 'Kemudian mereka memuji Allah dan bernyanyi-nyanyi kepada-Nya serta memuliakan-Nya karena segala perbuatan-Nya yang besar itu. Sebab malaikat Allah telah menampakkan diri kepada mereka.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 1, 'Tobit mengarang doa ini untuk menyatakan sukacitanya:', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 2, '"Terpujilah Allah yang hidup selama-lamanya, dan kerajaanNya tetap untuk sekalian abad. Memang Ia menyiksa tapi juga mengasihani, Ia menurunkan ke dalam dunia orang mati, tetapi menaikkan dari padanya juga; tiada seorangpun luput dari tanganNya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 3, 'Muliakanlah Dia, hai orang Israel, di hadapan sekalian bangsa, sebab kita dicerai-beraikanNya di antara mereka.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 4, 'Wartakanlah kebesaranNya di sana, agungkanlah Dia di hadapan segala yang hidup. Sebab Dialah Tuhan kita dan Allah, Ia dalah Bapa kita untuk selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 5, 'Oleh karena kejahatan kita maka kita disiksaNya, tetapi kita dikasihaniNya lagi dan dikumpulkanNya dari antara sekalian bangsa, di mana kamu terserak-serak.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 6, 'Jika dengan segenap hati kamu berbalik kepadaNya, dan dengan segenap jiwa berlaku benar dihadapanNya, niscaya Iapun berbalik kepada kamu, dan tidak disembunyikanNya wajahNya terhadap kamu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 7, 'Maka pandanglah apa yang akan dikerjakanNya bagi kamu, muliakanlah Dia dengan segenap mulut. Pujilah Tuhan yang adil dan agungkanlah Raja kekal.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 8, 'Aku memuliakan Dia di tanah pembuanganku, dan kunyatakan kekuasaan serta kebesaranNya kepada kaum berdosa. Bertobalah, hai orang-orang yang berdosa, dan lakukanlah apa yang benar di hadapanNya. Siapa tahu kalau-kalau Ia berkenan kepadamu dan menjalankan belas kasihan kepada kamu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 9, 'Aku hendak mengagungkan Allahku dan Raja Sorgawi dan hatiku hendak bersorak karena kebesaranNya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 10, 'Dan hendaklah sekalian orang di Yerusalem menyebut serta memuliakanNya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 11, 'Muliakanlah Tuhan selayaknya dan pujilah Raja kekal, supaya bagimu Kemah-Nya dibangun kembali dengan gembira.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 12, 'Maka Allah menggembirakan kaum buangan di dalam dirimu, dan yang payah di dalam dirimu akan dikasihi-Nya turun-temurun sepanjang sekalian abad.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 13, 'Dari jauh banyak bangsa akan datang ke hadapan nama Tuhan Allah dengan membawa persembahan di tangan, yaitu upeti untuk Raja sorgawi; turun-temurun sorak-sorainya dilambungkan kepadamu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 14, 'Para pembencimu terkutuklah hendaknya, tetapi mereka yang mengasihi engkau akan diberkati selama-lamanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 15, 'Bersukacitalah dan bersorak-sorailah karena anak-anak orang yang benar, sebab mereka akan dikumpulkan dan akan memuji Tuhan orang benar. Berbahagialah orang-orang yang mengasihi engkau, mereka yang bersukacita karena damai sejahteramu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 16, 'Berbahagialah orang yang berdukacita karena siksaanmu, sebab mereka nanti bergembira karena engkau apabila mereka mengagumi segenap kemuliaanmu; maka bersukacitalah mereka selama-lamanya. Hai jiwaku, pujilah Allah, Raja agung.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 17, 'Sebab Yerusalem akan dibangun dengan nilakandi dan zamrud, tembok-temboknya dengan permata, menara-menaranya serta benteng-bentengnya dari mas murni; lapangan-lapangan Yerusalem akan diturap dengan arzak, manikam kumala dan permata dari Ofir.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 13, 18, 'Maka semua jalannya akan berseru: Haleluya. Bernyanyilah mereka semua dengan berkata: Terpujilah Allah yang meninggikan engkau untuk selama-lamanya."', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 2, 'Adapun Tobit meninggal dengan tentram waktu berumur seratus dua belas tahun. Ia dikuburkan di Niniwe sebagaimana mestinya. Waktu matanya menjadi rusak ia berumur enam puluh dua tahun dan setelah dapat melihat kembali ia hidup sejahtera dan melakukan kebajikan. Iapun terus memuji Allah dan memuliakan kebesaranNya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 3, 'Ketika tiba ajalnya dipanggilnya anaknya Tobia dan disuruhnya: "Nak, ambillah semua anakmu', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 4, 'dan pergilah ke negeri Media. Sebab aku yakin akan firman Allah mengenai kota Niniwe, sebagaimana yang telah diucapkan nabi Nahum. Semua akan terjadi, semua akan mendatangi bangsa Asyur dan kota Niniwe. Segala sesuatunya yang telah diucapkan oleh para nabi Israel yang diutus oleh Allah akan terjadi semua. Tiada sedikitpun dari ucapan itu yang tidak akan samapi; semua akan terjadi pada waktunya. Tetapi di negeri Media orang akan lebih aman dari pada di negeri Asyur dan Babel. Aku tahu dan yakin benar bahwa semua yang telah difirmankan Allah akan terlaksana dan terjadi juga. Tiada satupun dari firmanNya yang akan gagal. Adapun saudara-saudara kita yang masih tinggal di tanah Israel akan dicerai-beraikan dan diangkut tertawan dari tanah yang baik itu. Seluruh tanah Israel serta Samaria dan Yerusalem akan menjadi gurun belaka dan Bait Allah akan tinggal roboh dan hangus hingga waktu tertentu.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 5, 'Kemudian mereka akan dikasihani oleh Allah dan dikembalikan ke tanah Israel. Maka Bait Allah akan mereka bangun, meski pun tidak seperti yang dahulu, hingga tiba saatnya zaman dunia mencapai kegenapannya. Lalu mereka semua akan pulang dari pembuangannya dan Yerusalem akan dibangunkannya dengan mulianya. Bait Allahpun akan dibangun di dalamnya, sebagaimana yang telah dikatakan para nabi tentangnya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 6, 'Semua bangsa di seluruh bumi akan bertobat dan benar-benar menakuti Tuhan Allah. Semua akan meninggalkan berhala mereka yang membuat mereka kembara dalam kesesatan. Dengan tulus hati mereka akan memuji Allah yang kekal.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 7, 'Semua orang Israel yang selamat pada masa itu dan yang ingat kepada Allah dengan tulus ikhlas akan berkumpul dan datang ke Yerusalem. Merekapun lalu akan mendiami tanah Abraham untuk selama-lamanya dan dengan aman sentosa. Negeri itu akan dianugerahkan kepada mereka. Allah akan mereka kasihi dengan tulus ikhlas dan mereka bergembira. Tetapi mereka yang berbuat dosa dan lalim akan lenyap dari muka bumi.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 8, 'Oleh sebab itu, hai anak-anakku, aku memerintahkan kepadamu: hendaklah mengabdi kepada Allah dengan tulus ikhlas serta melakukan apa yang berkenan kepada-Nya. Wajibkanlah segala anakmu, supaya berbuat adil lagi melakukan kebajikan; supaya ingat kepada Allah dan selalu memuji nama-Nya dengan tulus ikhlas dan sekuat tenaga.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 9, 'Oleh sebab itu, nak, pergilah dari kota Niniwe dan jangan tinggal di sini. Pada hari ibumu kaukuburkan di sampingku jangan bermalam lagi di wilayah kota ini. Sebab kulihat bahwa ada banyak kelaliman di negeri ini dan banyak tipu daya dilakukan di sini. Dan mereka tidak malu-malu sama sekali.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 10, 'Nak, ingatlah kepada apa yang telah diperbuat Nadab kepada bapa pengasuhnya, yaitu Ahikar. Bukankah Ahikar hidup-hidup diturunkan ke bagian bawah bumi? Tetapi Allah telah membalas kelaliman Nadab ke atas kepalanya sendiri. Ahikar keluar menuju cahaya, sedangkan Nadab turun ke kegelapan kekal, oleh karena ia telah berusaha membunuh Ahikar. Karena melakukan kebajikan maka Ahikar luput dari jerat maut yang dipasang baginya oleh Nadab. Sedangkan Nadab jatuh ke dalam jerat maut yang juga membinasakannya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 11, 'Makanya, anak-anakku, camkanlah apa yang dihasilkan oleh sedekah dan apa yang dihasilkan oleh kelaliman. Memang kelaliman membunuh. Tetapi aku kehabisan tenaga!" Maka Tobit berbaring di tempat tidurnya lalu meninggal. Ia dikuburkan dengan layak.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 12, 'Setelah ibu Tobia meninggal maka dikuburkannya di samping ayahnya. Kemudian Tobia serta isterinya pergi ke negeri Media dan menetap di kota Ekbatana pada Raguel, mertuanya.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 13, 'Masa tua Raguel serta isterinya dipelihara oleh Tobia sebagaimana mestinya lalu dikuburkannya mereka di kota Ekbatana di negeri Media. Tobiapun mewarisi baik harta milik Raguel maupun harta milik ayahnya sendiri.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 14, 'Tobia sendiri meninggal sebagai orang terhormat dalam umur seratus tujuh belas tahun di kota Ekbatana di negeri Media.', 'id', 'Deutero'),
  ('67', 'tob', 'Tobit', 14, 15, 'Tetapi sebelum meninggal masih didengarnya tentang kebinasaan kota Niniwe dan melihat penduduknya ditawan dan dibuang ke negeri Media, yakni orang-orang yang diangkut tertawan oleh Siaksares, raja Media. Maka Tobia memuji Allah karena segala sesuatunya yang telah dilakukan-Nya kepada orang Niniwe dan Asyur. Sebelum meninggal Tobia masih bergembira oleh karena nasib kota Niniwe dan memuji Tuhan Allah untuk selama-lamanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 1, 'Dalam tahun kedua belas pemerintahan Nebukadnezar yang menjadi raja orang-orang Asyur di Niniwe, kota yang besar. Pada zaman itu Arfaksad menjadi raja orang-orang Media di Ekbatana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 2, 'Di keliling kota Ekbatana raja Arfaksad membangun sebuah tembok dari batu persegi yang besar, selebar tiga hasta dan sepanjang enam hasta. Tingginya tembok itu dibuatnya tujuh puluh hasta dan lebarnya lima puluh hasta.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 3, 'Di atas semua pintu gerbang kota itu didirikannya menara setinggi seratus hasta dan pada alasnya selebar enam puluh hasta.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 4, 'Tingginya pintu gerbang sendiri adalah tujuh puluh hasta dan lebarnya empat puluh hasta, supaya bala tentaranya serta barisan-barisan pasukan jalan dapat ke luar.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 5, 'Maka pada zaman itu raja Nebukadnezar bertempur dengan raja Arfaksad di dataran yang besar yang terletak di daerah Ragau.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 6, 'Semua penduduk pegunungan dan semua penduduk tepi sungai-sungai Efrat, Tigris dan Hidaspes dan juga penduduk dataran raja orang-orang Elumais, yaitu Ariokh, bergabung dengannya. Banyak bangsa menggabungkan diri dengan ikatan-ikatan perang orang Heleud.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 7, 'Adapun Nebukadnezar, raja orang-orang Asyur, mengirimkan utusan kepada semua penduduk negeri Persia dan segala penduduk daerah di sebelah barat, yakni kepada penduduk Kilikia, Damsyik, Libanon dan Antilibanon serta kepada semua orang yang mendiami pantai laut,', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 8, 'kepada bangsa penghuni daerah Karmel, Gilead, Galilea Hulu dan dataran besar Esdrelon;', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 9, 'kepada semua orang di daerah Samaria serta anak-anak kotanya; kepada penduduk daerah di seberang sungai Yordan sampai ke Yerusalem, Batane, Helus dan Kadesy hingga sungai Mesir dan kota Tafne, Raamses serta seluruh daerah Gosyen', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 10, 'sampai ke sebelah sana kota Tanis dan Memfis, pendeknya kepada segenap penduduk negeri Mesir hingga ke perbatasan Etiopia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 11, 'Tetapi semua penduduk segala negeri itu menghina titah Nebukadnezar, raja orang-orang Asyur. Mereka tidak mau maju perang sertanya dan tidak takut kepadanya. Sebaliknya ia dipandang mereka sebagai orang sembarangan saja. Utusan-utusan Raja Nebukadnezar dikembalikannya dengan tangan hampa dan ternista.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 12, 'Maka sangat marahlah raja Nebukadnezar kepada semua negeri itu. Demi takhta serta kerajaannya raja bersumpah bahwa hendak menghukum serta menumpas dengan pedangnya segala daerah Kilikia, Damsyik dan Siria, dan demikianpun negeri Moab, bani Amon, seluruh Yudea serta semua orang Mesir sampai daerah kedua laut.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 13, 'Dengan seluruh angkatan perangnya raja Nebukadnezar mengikat perang melawan raja Arfaksad dalam tahun ketujuh belas. Raja Arfaksad digagahinya dalam pertempuran dan segenap bala tentaranya, yaitu seluruh pasukan berkuda serta kereta perangnya dipukulnya mundur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 14, 'Raja Nebukadnezar menaklukkan semua kota lalu maju sampai ke kota Ekbatana. Menara-menara kota itu direbutnya, jalan-jalannya dirampasinya dan kemuliaannya dirobahnya menjadi nista.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 15, 'Raja Arfaksad sendiripun ditangkapnya di pegunungan Ragau, lalu ditikamnya dengan lembing dan dibasminya hingga hari ini.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 1, 16, 'Kemudian raja Nebukadnezar sendiri serta seluruh pasukannya, suatu jumlah prajurit yang besar sekali, kembali ke Niniwe. Selama seratus dua puluh hari raja Nebukadnezar serta bala tentaranya bersukaria dan berpestapora di sana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 1, 'Dalam tahun kedelapan belas pada tanggal dua puluh dua bulan pertama tersiarlah kabar di istana Nebukadnezar, raja orang-orang Asyur, bahwa raja hendak menghukum seluruh bumi, sebagaimana telah dikatakannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 2, 'Raja mengumpulkan semua pejabat serta pembesarnya, lalu mengadakan musyawarah rahasia dengan mereka. Raja sendiri memutuskan malapetaka bumi semesta.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 3, 'Para pejabat serta pembesarnyapun menetapkan pula bahwa semua orang yang tidak menuruti titah raja mesti dibasmi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 4, 'Selesai musyawarah itu maka Nebukadnezar, raja orang-orang Asyur, memanggil panglima besar tentaranya, yaitu Holofernes, orang kedua sesudah raja.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 5, 'Berkatalah raja kepadanya: "Beginilah titah raja agung yang dipertuan di seluruh bumi: Camkanlah! Engkau harus pergi dari hadapanku dan membawa serta orang-orang yang percaya pada kekuatannya sendiri, yaitu pasukan jalan sampai seratus dua puluh ribu orang dan sejumlah besar kuda serta penunggang, sampai dua belas ribu orang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 6, 'Engkau harus maju perang melawan seluruh wilayah barat, karena mereka telah memberontak terhadap titahku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 7, 'Hendaklah kauperintahkan kepada mereka untuk menyediakan air dan tanah. Memang dalam amarahku aku hendak pergi melawan mereka serta membanjiri seluruh muka bumi dengan kaki bala tentaraku. Mereka akan kuserahkan kepada tentaraku untuk dirampasi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 8, 'Jurang-jurang mereka akan dipenuhi dengan orang-orang yang berluka dan segala anak sungai akan penuh meluap-luap karena mayat mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 9, 'Sebagai tawanan mereka akan kuangkut ke ujung-ujung seluruh bumi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 10, 'Tetapi engkau harus pergi dahulu untuk menduduki seluruh wilayah itu bagiku. Setelah mereka menyerah kepadamu, maka mereka harus kaupelihara bagi diriku sendiri, hingga hari mereka akan kuhukum.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 11, 'Tetapi orang yang tetap memberontak janganlah disayangi matamu. Orang semacam itu harus kauserahkan untuk dibunuh dan dirampasi di seluruh wilayah kekuasaanmu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 12, 'Sebab demi aku hidup dan demi kekuasaan kerajaanku, aku telah mengatakannya dan dengan tanganku sendiri akan kulaksanakan pula.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 13, 'Adapun engkau sendiri, janganlah melanggar satupun dari titah tuanmu, melainkan tepatilah seluruhnya seperti telah kutetapkan seluruhnya bagimu. Jangan berayal lagi melakukannya!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 14, 'Maka pergilah Holofernes dari hadapan tuannya lalu dikerahkannya segala perwira, para panglima dan pemimpin bala tentara Asyur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 15, 'Iapun membilang orang pilihan untuk ikatan perang, sebagaimana telah disuruh tuannya, yaitu seratus dua puluh ribu orang dan lagi dua belas ribu pemanah berkuda.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 16, 'Mereka diaturnya sebagaimana pasukan tempur diatur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 17, 'Lalu diambilnya unta, keledai dan bagal yang besar sekali jumlahnya, untuk mengangkut barang tentara itu. Iapun mengambil domba, sapi dan kambing yang tak terbilang banyaknya guna perbekalan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 18, 'Selanjutnya diambilnya pelabur yang berlimpah untuk tiap-tiap orang dan sangat banyak emas perak dari istana raja.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 19, 'Kemudian Holofernes dan tentaranya itu maju perang dengan berpawai di hadapan raja Nebukadnezar. Mereka pergi untuk membanjiri seluruh wilayah barat dengan kereta-kereta perang, pasukan berkuda dan pasukan jalan pilihannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 20, 'Bersama dengan mereka berangkat pula sejumlah besar orang lain lagi yang seperti belalang dan pasir bumi banyaknya, sehingga jumlahnya tidak terbilang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 21, 'Dari kota Niniwe mereka berangkat dan berjalan tiga hari lamanya melalui dataran Bektilet. Setelah melalui Bektilet berkemahlah mereka di dekat pegunungan yang membentang di sebelah utara Kilikia-Hulu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 22, 'Kemudian Holofernes memberangkatkan seluruh bala tentaranya, yaitu pasukan jalan, pasukan berkuda dan kereta-kereta perangnya, dan dari sana memasuki daerah bergunung-gunung.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 23, 'Daerah Fud dan Lud diretasnya dan semua bani Rasis dan Ismael yang tinggal di tepi padang gurun di sebelah selatan daerah Heleon dirampasinya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 24, 'Selanjutnya menyeberanglah ia sungai Efrat, melintasi daerah Mesopotamia dan menyerang kota-kota berbenteng yang terletak di dekat sungai Abrona hingga pantai laut.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 25, 'Daerah Kilikia direbutnya dan dibunuhnya semua yang melawannya, lalu ia sampai di daerah Yafet di bagian selatan di dekat Arabia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 26, 'Semua bani Midian dikepung olehnya, kemah-kemah mereka dibakar dan kandang-kandangnya dirampasi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 27, 'Pada musim panen gandum turunlah ia ke dataran Damsyik; segala ladang mereka dibakarnya, kawanan ternak besar kecil dilenyapkannya, kota-kotanya dirampasinya, semua tegal mereka disapu bersih olehnya dan semua pemuda mereka ditewaskannya dengan mata pedang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 2, 28, 'Maka ketakutan serta kegentaran menghinggapi para penduduk pantai laut, para penghuni Sidon dan Tirus, para penduduk Sur dan Okina serta para penduduk Yamnia; para penduduk Asdod dan Askelonpun takut kepadanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 1, 'Maka dari itu mereka mengirim utusan-utusan dengan usul perdamaian ini:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 2, '"Kami ini, hamba-hamba Sri Maharaja Nebukadnezar, sujud menyembah di hadapan tuan. Perlakukanlah kami sebagaimana tuan berkenan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 3, 'Memang segala dusun dan kediaman kami, semua tegal gandum, kawanan dan ternak besar kecil serta segala perkemahan kami tersedia bagi tuan. Sudilah kiranya tuan menggunakan semuanya sebagaimana berkenan pada tuan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 4, 'Juga segala kota kami serta para penduduknya adalah hamba tuan. Sudilah kiranya tuan datang dan bertindak terhadapnya sebagaimana dipandang baik oleh tuan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 5, 'Utusan-utusan itupun lalu menghadap Holofernes dan usul tadi mereka sampaikan kepadanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 6, 'Maka Holofernes bersama dengan tentaranya turun ke pantai. Di dalam kota-kota berbenteng ditempatkannya pendudukan dan dari antara penduduknya diambilnya orang-orang pilihan sebagai bala bantuan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 7, 'Dengan karangan-karangan bunga, tari-tarian berbaris dan gendang Holofernes disambut oleh orang-orang itu dan juga oleh semua orang di sekitar mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 8, 'Namun demikian tempat-tempat suci mereka dihancurkan Holofernes dan tugu-tugu berhala ditebangnya. Sebab sudah ditugaskan kepada Holofernes untuk membinasakan semua allah di bumi, sehingga segala bangsa bumi menyembah Nebukadnezar semata-mata dan segala bahasa serta suku mereka menyebutnya sebagai allah.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 9, 'Iapun datang pula di daerah yang berhadapan dengan Esdrelon di dekat Dotaia yang letaknya di depan pegunungan besar Yudea.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 3, 10, 'Berkemahlah ia antara Gaibai dan Skitopolis. Di sana ia tinggal sebulan penuh untuk mengumpulkan barang-barang keperluan tentaranya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 1, 'Adapun orang Israel yang diam di daerah Yudea mendengar tentang kesemuanya yang dilakukan Holofernes, panglima besar Nebukadnezar, raja Asyur, kepada semua bangsa. Mereka mendengar juga bagaimana tempat-tempat suci dirampasi olehnya dan diserahkan untuk dibasmi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 2, 'Maka mereka sangat ketakutan kepadanya dan gelisahlah mereka oleh karena Yerusalem dan Bait Allah, Tuhan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 3, 'Sebab belum lama berselang mereka kembali dari pembuangan dan baru saja seluruh umat Yudea berhimpun lagi. Lagipula baru saja perkakas suci, mezbah dan Bait Allah ditahirkan dari pencemaran.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 4, 'Dari sebab itu mereka mengirimkan kabar ke seluruh daerah Samaria, ke kota Kona, Bet-Horon, Belmain dan Yerikho dan juga ke kota Hoba, Aisora dan Lembah Salem.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 5, 'Puncak gunung-gunung yang tinggi diduduki dan semua kampung yang ada di situ ditemboki dan ditaruhlah di dalamnya perbekalan untuk menyiapkan perang. Sebab tegal-tegal baru saja dituai panenannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 6, 'Imam besar Yoyakim yang pada waktu itu menjabat di Yerusalem menulis juga surat kepada penduduk Betulia dan Betomestaim, yang letaknya berhadapan dengan Esdrelon di muka dataran besar di dekat Dotaim.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 7, 'Mereka diperintahkannya, supaya menduduki sela-sela pegunungan, sebab jalan masuk ke Yerusalem melalui di situ. Adalah mudah menghalangi orang mendaki, sebab jalan-jalan masuk itu sempit dan paling-paling untuk dua orang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 8, 'Maka orang-orang Israel berbuat sebagaimana diperintahkan kepada mereka oleh imam besar Yoyakim dan Majelis Tertua seluruh kaum Israel yang berkedudukan di Yerusalem.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 9, 'Semua laki-laki Israel berseru kepada Allah dengan asyik sekali dan juga merendahkan diri dengan sangat asyiknya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 10, 'Mereka sendiri, isteri serta kanak-kanak mereka, juga ternak, segala perantau, orang upahan dan budak belian mereka mengenakan kain kabung pada pinggangnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 11, 'Semua laki-laki, perempuan dan anak Israel yang diam di Yerusalem, meniarap di depan Bait Allah, menaburi kepalanya dengan abu dan membentangkan kain kabungnya di hadapan Tuhan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 12, 'Juga mezbah diselimuti dengan kain kabung. Dalam pada itu mereka sehati berseru dengan asyiknya kepada Allah Israel, supaya Ia jangan menyerahkan kanak-kanak mereka untuk dirampas, isteri mereka untuk dijarah, kota milik-Nya sendiri untuk dibinasakan dan Bait Suci untuk dicemarkan dan dinistakan, sehingga bangsa-bangsa lain bersenang hati.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 13, 'Seruan mereka didengarkan oleh Tuhan yang dengan kasihan memandang kesesakan mereka. Beberapa hari lamanya umat di seluruh Yudea berpuasa dan juga di Yerusalem di hadapan Bait Suci Tuhan Yang Mahakuasa.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 14, 'Imam besar Yoyakim dan semua imam yang menyelenggarakan kebaktian di hadapan Tuhan dan semua orang yang berbakti kepada Tuhan dengan disabuki kain kabung, mempersembahkan korban bakaran tetap serta doa dan sumbangan sukarela dari rakyat.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 4, 15, 'Abu tertabur di atas serban mereka. Dengan sekuat tenaga berserulah mereka kepada Tuhan, semoga Tuhan mengunjungi seluruh kaum Israel dengan kebaikan hati-Nya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 1, 'Dalam pada itu dikabarkan kepada Holofernes, panglima besar bala tentara Asyur, bahwa orang Israel bersiap-siap untuk bertempur dan bahwa mereka menutup jalan-jalan di pegunungan, menemboki puncak gunung-gunung yang tinggi dan memasang perangkap-perangkap di dataran.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 2, 'Maka menggeramlah ia dengan hebatnya. Dipanggilnya semua pemuka Moab, para panglima Amon dan para satrap dari daerah pantai.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 3, 'Lalu berkatalah ia kepada mereka: "Hai orang-orang Kanaan, beritahukanlah kepadaku bangsa apa itu yang duduk di pegunungan dan manakah kota-kota yang didiami mereka; berapa jumlah pasukan mereka dan dalam hal manakah letaknya kuasa serta kekuatan mereka? Siapa raja mereka yang mengepalai tentaranya?', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 4, 'Mengapa dari antara semua penduduk wilayah barat hanya mereka sajalah yang enggan menyambut aku?"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 5, 'Maka Akhior, penguasa semua bani Amon, menyahut sebagai berikut: "Sudilah tuanku mendengarkan perkataan yang hendak diucapkan hamba tuan, maka hamba akan memberitahukan kepada tuan kebenaran tentang bangsa yang mendiami daerah pegunungan di dekat tuanku ini. Tiada dusta akan keluar dari mulut hamba tuan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 6, 'Adapun bangsa itu adalah keturunan orang-orang Kasdim.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 7, 'Dahulu mereka diam di Mesopotamia, karena mereka tidak mau menganut allah nenek moyang mereka yang tinggal di negeri Kasdim.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 8, 'Agama nenek moyangnya telah ditinggalkan mereka untuk menyembah Yang Berkuasa di sorga, yaitu Allah yang mereka kenal. Dari sebab itu mereka diusir dari hadapan allah-allah orang Kasdim, lalu mengungsi ke Mesopotamia dan lama diam di sana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 9, 'Tetapi berfirmanlah Allahnya kepada mereka untuk pergi dari tempat kediaman mereka dan berangkat ke tanah Kanaan. Mereka menetap di sana dan berlimpahkan emas, perak dan amat banyak ternak.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 10, 'Kemudian turunlah mereka ke negeri Mesir, karena kelaparan yang menimpa muka bumi tanah Kanaan. Mereka diam di negeri Mesir selama mereka mendapat nafkah. Di sanapun mereka menjadi banyak sekali jumlahnya, sehingga keturunan mereka tidak terbilang banyaknya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 11, 'Lalu raja Mesir bangkit melawan mereka. Dengan tipu daya dibebaninya mereka dengan kerja paksa, yaitu membuat batu bata. Mereka direndahkan dan diperbudak.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 12, 'Maka berserulah mereka kepada Allahnya. Lalu Allah memukul seluruh negeri Mesir dengan bala-bala yang tak tersembuhkan. Karenanya orang-orang Mesir mengusir mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 13, 'Allah mengeringkan Laut Merah di depan mereka', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 14, 'dan menuntun mereka di jalan menuju gunung Sinai dan daerah Kadesy-Barnea. Lalu semua penduduk padang gurun diusir oleh mereka', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 15, 'dan mereka sendiri diam di negeri orang-orang Amori. Dengan kekuatannya mereka membasmi orang Hesybon. Kemudian mereka menyeberang sungai Yordan lalu seluruh daerah pegunungan mereka miliki.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 16, 'Diusirnyalah orang-orang Kanaan, Feris, Yebus, penduduk Sikhem dan semua orang Girgasi. Lama mereka diam di sana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 17, 'Selama mereka tidak berdosa kepada Allah mereka, keadaan mereka baik saja karena Allah yang menyertai mereka membenci kefasikan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 18, 'Tetapi ketika mereka menyimpang dari jalan hidup yang sudah ditentukan Allah bagi mereka, maka mereka dibasmi dengan banyak peperangan yang berlangsung lama sekali. Mereka diangkut tertawan ke negeri yang bukan negeri mereka sendiri. Bait Allah mereka menjadi puing belaka dan segala kota mereka dikuasai oleh lawan-lawan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 19, 'Oleh karena berbalik kepada Allah maka sekarang mereka sudah kembali dari perantauan di mana mereka telah diceraiberaikan. Mereka kembali memiliki kota Yerusalem. Di sana ada tempat suci mereka. Merekapun menetap pula di pegunungan karena sunyi sepi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 20, 'Makanya, junjungan tuanku, jikalau pada kaum itu terdapat suatu kesalahan sehingga mereka telah berdosa kepada Allahnya dan kita dapat memastikan bahwasanya sungguh ada batu sandungan itu pada mereka, maka baiklah kita maju untuk memerangi mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 21, 'Sebaliknya, jikalau tidak terdapat suatu pelanggaran pada bangsa itu, maka hendaklah tuanku berjauh saja, sebab mungkin Tuhan dan Allah mereka menjadi perisai bagi mereka, sehingga kita nanti menjadi ternista di hadapan seluruh bumi."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 22, 'Setelah Akhior selesai berbicara maka seluruh rakyat yang berdiri di keliling kemah itu menggerutu. Para pembesar Holofernes dan segenap penduduk daerah pantai serta penduduk negeri Moab mengusulkan, supaya Akhior dibunuh saja.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 23, 'Katanya: "Tak perlu kita takut kepada orang Israel, sebab mereka itu sungguh suatu bangsa yang tidak berdaya dan tidak kuasa untuk menghadapi ikatan perang yang kuat.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 5, 24, 'Baiklah kita maju saja, niscaya mereka menjadi umpan belaka untuk seluruh tentara tuanku, hai junjungan Holofernes."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 1, 'Ketika gempar dari orang-orang yang di keliling dewan penasehat itu sudah padam, berkatalah Holofernes, panglima besar Asyur, di hadapan segenap rakyat kaum asing itu kepada Akhior serta bani Amon sebagai berikut:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 2, '"Siapakah gerangan engkau, hai Akhior, dan kamu orang-orang upahan dari Amon, maka engkau berlagak nabi di tengah-tengah kita, seperti sekarang ini, dengan berkata bahwa kita tidak boleh maju untuk memerangi umat Israel itu, seolah-olah Allah akan menjadi perisai bagi mereka? Siapakah allah adanya kecuali Nebukadnezar? Baginda akan mengirimkan kekuatannya, lalu membasmi orang Israel dari muka bumi. Dan Allah mereka tidak akan dapat melepaskan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 3, 'Sebaliknya, kita, hamba-hamba Nebukadnezar, akan serempak memukul mereka. Niscaya mereka tidak akan dapat bertahan terhadap kekuatan kuda-kuda kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 4, 'Mereka akan kita bakar bersama-sama. Gunung-gunung mereka akan menjadi mabuk karena darah mereka dan semua datarannya akan penuh dengan mayat mereka. Telapak kaki mereka tidak akan dapat bertahan di hadapan kita. Sebaliknya, mereka akan dibinasakan sama sekali. Demikianlah titah raja Nebukadnezar yang dipertuan seluruh bumi. Sebab baginda sudah bertitah dan titahnya itupun tidak akan sia-sia adanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 5, 'Adapun engkau sendiri, hai Akhior orang upahan dari Amon, engkau yang telah mengucapkan perkataan tadi pada hari sialmu ini, mulai sekarang engkau tidak akan melihat wajahku lagi hingga aku membalas dendam kepada keturunan kaum pelari dari Mesir itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 6, 'Lalu lambungmu akan ditembusi dengan senjata tentaraku dan dengan senjata para pelayanku. Jatuhlah engkau nanti di tengah-tengah orang-orang mereka yang kena luka, apabila aku kembali kelak.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 7, 'Hamba-hambaku akan membawa engkau ke pegunungan lalu engkau akan mereka tinggalkan di salah satu kota di lereng gunung.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 8, 'Engkau tidak akan binasa, hingga dibasmi bersama dengan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 9, 'Jika dalam hati engkau masih berharap juga bahwa mereka tidak jadi ditangkap, maka tak perlu mukamu menjadi murung. Aku sudah berkata dan tiada satupun dari perkataanku itu yang akan gagal."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 10, 'Kemudian Holofernes memerintahkan kepada hamba-hambanya yang sedang bertugas di kemahnya, supaya Akhior ditangkapnya, lalu dibawanya ke kota Betulia serta diserahkannya kepada orang Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 11, 'Maka Akhior ditangkap hamba-hamba itu, lalu diantar ke luar dari perkemahan ke dataran dan dari situ ke pegunungan. Mereka sampai ke sumber-sumber yang terletak di bawah Betulia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 12, 'Melihat mereka orang-orang kota yang terletak di atas puncak gunung itu mengambil senjata dan keluar dari kota di atas puncak gunung itu. Segala pengumban melempari lasykar Holofernes itu dengan batu untuk menghalangi mereka naik ke atas.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 13, 'Dari sebab itu lasykar Holofernes bersembunyi di bagian bawah gunung itu. Diikatnya Akhior, lalu ditinggalkannya terletak pada kaki gunung itu. Kemudian pulanglah mereka kepada tuannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 14, 'Orang Israel turun dari kotanya lalu menghampiri Akhior. Ia dilepaskannya dan diantarnya ke kota Betulia. Lalu diiringkannya ke hadapan para pemimpin kota mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 15, 'Pada masa itu para pemimpin itu ialah Uzia bin Mikha dari suku Simeon dan Habris bin Gotoniel dan Harmis bin Melkhiel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 16, 'Mereka itu mengumpulkan para tua-tua kota. Juga para pemuda dan perempuan membanjir ke himpunan rakyat itu. Akhior ditempatkan di tengah-tengah seluruh rakyat, lalu Uzia menanyakan kepadanya apa yang sudah terjadi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 17, 'Akhior menyahut dengan menceritakan kepada mereka semua apa yang telah dibicarakan dalam sidang dewan penasehat Holofernes dan segala sesuatunya yang telah dikatakannya sendiri di hadapan para perwira orang Asyur. Pun pula diceritakannya apa yang telah dibualkan Holofernes terhadap kaum Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 18, 'Maka seluruh rakyat Israel merebahkan diri dan sujud menyembah di hadapan Allah seraya berseru, katanya:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 19, '"Tuhan, Yang Berkuasa di sorga, pandanglah kecongkakan mereka dan kasihanilah bangsa kami yang direndahkan dan lihatlah pada hari ini dengan rela muka orang-orang yang telah dikuduskan kepada-Mu."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 20, 'Merekapun lalu menghibur Akhior dan ia sangat dipuji mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 6, 21, 'Uzia mengambil dia dari tengah himpunan rakyat itu ke rumahnya. Diadakanlah suatu perjamuan makan untuk para tua-tua. Semalam-malaman mereka minta tolong kepada Allah Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 1, 'Keesokan harinya Holofernes memerintahkan kepada seluruh bala tentaranya dan kepada kaum yang menyertainya sebagai bala bantuan, supaya berangkat menuju Betulia, lalu menduduki jalan-jalan yang naik ke pegunungan dan bertempur dengan orang Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 2, 'Pada hari itu juga berangkatlah sekalian orang bala tentaranya. Adapun kekuatan bala tentaranya itu adalah seratus dua puluh ribu orang pasukan jalan dan dua belas ribu orang pasukan berkuda, belum lagi terhitung semua barang dan orang yang menyertai mereka, suatu jumlah yang besar sekali.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 3, 'Bersaranglah mereka di lembah di dekat Betulia pada sumber itu. Mereka melebar dari dekat Dotaim sampai Belbaim dan memanjang dari Betulia sampai Kuamon yang letaknya berhadapan dengan Esdrelon.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 4, 'Melihat jumlah orang itu orang Israel sangat terperanjat, lalu berkatalah mereka satu sama lain: "Kini mereka akan menjilat seluruh permukaan negeri ini dan baik gunung-gunung yang tinggi maupun jurang-jurang dan bukit-bukit tidak akan dapat menanggung beban mereka."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 5, 'Lalu masing-masing mengambil perlengkapan perangnya dan dipasanglah api unggun di atas menara-menara kotanya dan malam itu mereka berjaga.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 6, 'Pada hari kedua Holofernes membentangkan pasukan berkudanya di hadapan orang Israel yang ada di Betulia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 7, 'Jalan-jalan yang naik ke kota diperiksanya, sumber-sumber diselidikinya, lalu didudukinya. Ditempatkannyalah regu-regu prajurit di sana, sedangkan ia sendiri kembali kepada rakyatnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 8, 'Maka datanglah para pemuka bani Esau dan semua penguasa bangsa Moab dan para panglima dari daerah pantai menghadap Holofernes dan berkata kepadanya:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 9, '"Sudilah junjungan mendengar perkataan ini, agar jangan terjadi bencana menimpa bala tentara tuanku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 10, 'Sebab bangsa Israel ini tidak percaya pada tombak-tombaknya, melainkan pada tingginya gunung-gunung di mana mereka diam, karena tidak mudahlah mendaki puncak gunung-gunung mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 11, 'Dari sebab itu junjungan jangan bertempur dengan mereka sebagaimana terjadi dalam pertempuran teratur. Niscaya dari bala tentara tuanku tiada seorangpun akan gugur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 12, 'Hendaklah tuanku tinggal saja di perkemahan dan memelihara setiap lasykar dari bala tentara tuanku. Biarlah hamba-hamba tuanku ini menguasai sumber yang berpancar pada kaki gunung itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 13, 'Sebab dari situlah semua penduduk Betulia menimba airnya. Maka haus akan memaksa mereka untuk menyerahkan kotanya. Kami serta lasykar kami hendak mendaki puncak-puncak gunung yang terdekat dan berkemah di sana sebagai penjagaan, jangan sampai ada satu orangpun dapat keluar dari kota itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 14, 'Maka mereka akan merana karena lapar, mereka sendiri serta isteri dan anak-anak mereka. Sebelum didatangi pedang mereka sudah menggeletak di jalan-jalan tempat kediaman mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 15, 'Dengan demikian tuanku akan dengan hebatnya membalas dendam kepada mereka, oleh karena mereka telah memberontak dan tidak mau menyambut tuanku dengan damai."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 16, 'Holofernes dan segala pejabatnya berkenan pada usul mereka itu. Maka diperintahkannya untuk berbuat sebagaimana telah dikatakan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 17, 'Lalu sepasukan bani Amon berangkat dan bersama dengan mereka juga lima ribu orang Asyur. Berkemahlah mereka di lembah dan didudukinya perairan serta sumber-sumber orang Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 18, 'Bani Esau dan bani Amon lainnya mendaki pegunungan dan berkemah di situ berhadapan dengan kota Dotaim. Dari kalangan mereka dikirimkanlah sejumlah orang ke selatan dan ke timur ke tempat yang berhadapan dengan Egrebel di dekat Husa yang terletak di tepi anak sungai Mokhmur. Pasukan orang-orang Asyur lainnya berkemah di dataran dan seluruh permukaan negeri mereka tutupi. Kemah-kemah serta barang-barang mereka berkelompok-kelompok padat terserak-serak di sana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 19, 'Orang Israel berseru kepada Tuhan, Allah mereka, sebab mereka tawar hati, karena segala musuhnya mengepung mereka dan tiada kemungkinan sedikitpun untuk lepas dari tengah mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 20, 'Tiga puluh empat hari lamanya seluruh tentara Asyur, yakni pasukan jalan, kereta-kereta perang dan pasukan berkuda tinggal di keliling mereka. Maka semua tempayan penduduk Betulia kehabisan air', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 21, 'dan sumur-sumur airpun menjadi kosong pula. Satu haripun mereka tidak dapat lagi minum sepuas-puasnya, sebab mereka diberi minum menurut takaran saja.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 22, 'Maka kanak-kanak mereka merentang jiwa, perempuan dan pemuda merana karena kehausan dan rebahlah mereka di jalan-jalan kota dan di ambang pintu gerbang. Tiada lagi tenaga pada mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 23, 'Maka berkumpullah seluruh rakyat, baik pemuda maupun perempuan serta anak-anak, menghadap Uzia dan para pemimpin kota. Dengan suara nyaring berserulah mereka dan berkata di hadapan kaum tua-tua:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 24, '"Moga-moga Allah menghakim antara kamu dan kami ini, bahwasanya kamu telah mendatangkan malapetaka besar atas diri kami karena tidak mau berunding tentang perdamaian dengan orang Asyur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 25, 'Kini tiada penolong lagi bagi kita, melainkan Allah telah menyerahkan kita ke dalam tangan mereka, sehingga kita menggeletak di hadapan mereka karena kehausan, sampai kita binasa sama sekali.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 26, 'Hendaklah kamu sekarang memanggil mereka dan menyerahkan seluruh kota ini kepada lasykar Holofernes serta seluruh bala tentaranya untuk dirampasi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 27, 'Lebih baiklah kita menjadi rampasan mereka. Memang kita akan menjadi budak, tetapi kita akan hidup terus dan tidak usah menyaksikan dengan mata kepala sendiri kematian kanak-kanak kita dan bagaimana isteri dan anak-anak kita kehilangan nyawanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 28, 'Kami bersumpah kepada kamu demi langit dan bumi dan demi Allah kita, Tuhan nenek moyang kita, yang menghukum kita sekedar segala dosa kita dan dosa nenek moyang kita, supaya Tuhan jangan berbuat pada hari ini menurut perkataan tadi."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 29, 'Maka terjadilah ratap tangis besar di tengah jemaah itu dan mereka serentak berseru kepada Tuhan Allah dengan suara nyaring.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 30, 'Lalu berkatalah Uzia kepada mereka: "Tetapkan hati, saudara-saudara! Hendaknya kita tahan lima hari lagi. Dalam waktu itu Tuhan Allah kita kiranya akan mengarahkan kasihan-Nya kepada kita. Niscaya kita tidak Ia tinggalkan untuk selama-lamanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 31, 'Jika hari-hari itu berlalu dengan tidak ada pertolongan datang, maka aku hendak berbuat sebagaimana telah saudara-saudara katakan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 7, 32, 'Kemudian himpunan rakyat dibubarkannya dan masing-masing pergi ke tempatnya serta naik ke atas tembok dan menara-menara kota, sedangkan perempuan dan anak disuruhnya pulang ke rumah. Di kota mereka sekalian dalam keadaan yang amat merana.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 1, 'Itupun didengar pula pada waktu itu oleh Yudit anak perempuan Merari bin Oks bin Yusuf bin Oziel bin Hilkia bin Ananias bin Gideon bin Rafain bin Ahitub bin Eliya bin Hilkia bin Eliab bin Natanael bin Salamiel bin Sarasadai bin Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 2, 'Adapun suaminya ialah Manasye dari sukunya sendiri dan keluarganya sendiri. Manasye sudah meninggal pada musim panen jelai.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 3, 'Tengah mengawasi para tukang pengikat berkas di tegal ia kena kelengar matahari. Ia harus berbaring di tempat tidurnya lalu menemui ajalnya di kotanya Betulia. Ia dikuburkan bersama nenek moyangnya di ladang yang terletak antara Dotaim dan Balamon.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 4, 'Adapun Yudit sudah tinggal di rumahnya sebagai janda tiga tahun empat bulan lamanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 5, 'Didirikannya sebuah gubuk di atas sotoh rumahnya, dikenakannya kain kabung pada pinggangnya dan dipakainya pakaian sebagaimana pantas bagi dia sebagai seorang janda.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 6, 'Sejak menjadi janda ia berpuasa setiap hari kecuali pada malam Sabat, hari Sabat, malam bulan baru, bulan baru, hari-hari raya dan semua hari bergembira kaum Israel.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 7, 'Ia cantik parasnya dan sangat elok kelihatannya. Suaminya Manasye telah meninggalkan baginya emas dan perak, budak-budak dan sahaya-sahaya, ternak dan ladang. Ia tinggal di tengah miliknya itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 8, 'Tiada satu orangpun dapat mengatakan sesuatu yang buruk tentang dia, sebab ia sangat takut akan Allah.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 9, 'Yuditpun mendengar tentang celaan rakyat terhadap para pemimpin kota, karena rakyat tawar hati akibat kekurangan air. Iapun mendengar pula tentang segala sesuatunya yang telah dikatakan Uzia kepada rakyat, yaitu bagaimana Uzia bersumpah kepada mereka akan menyerahkan kota itu kepada orang-orang Asyur sehabis tempo lima hari.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 10, 'Maka Yudit mengutus dayangnya yang mengurus segala miliknya untuk memanggil Habris dan Harmis, orang tua-tua kotanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 11, 'Setelah mereka datang kepadanya maka Yudit berkata kepada mereka: "Dengarkanlah aku ini, hai pemimpin-pemimpin penduduk Betulia. Memang tidak tepatlah apa yang telah kamu katakan pada hari ini di hadapan rakyat. Kamu telah angkat sumpah demi Allah dan kamu telah mengatakan bahwa kamu akan menyerahkan kota ini kepada musuh-musuhnya, apabila Tuhan dalam hari-hari ini tidak memberikan pertolongan kepada kamu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 12, 'Siapa gerangan kamu ini, maka kamu sampai mencobai Allah pada hari ini serta menaruh diri kamu di atas Allah di tengah-tengah anak-anak manusia?', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 13, 'Masakan kamu hendak menguji Tuhan Yang Mahakuasa! Kamu tak pernah mengerti apa-apa.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 14, 'Sebab lubuk hati manusia saja tak dapat kamu selami dan pikiran-pikiran sanubarinya tak dapat kamu mengertinya. Mana boleh kamu mau menyelidiki Allah yang membuat segala-galanya, mengenal budi-Nya serta memahami pikiran-Nya! Sekali-kali tidak, saudara-saudara! Janganlah memurkakan Tuhan, Allah kita!', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 15, 'Sebab sekiranya Tuhan tidak mau menolong dalam tempo lima hari ini, namun Ia mampu juga melindungi kita pada masa yang dikehendaki-Nya, atau membasmi kita di hadapan para musuh kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 16, 'Janganlah menuntut jaminan mengenai keputusan kehendak Allah. Sebab Allah tidak dapat diancam seperti manusia dan tidak dapat disuruh sebagaimana anak manusia disuruh!', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 17, 'Maka dari itu hendaknya kita menantikan penyelamatan dari pada-Nya sambil mohon pertolongan kepada-Nya bagi kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 18, 'Sebab tidak ada semasa umur hidup kita ini dan sekarangpun tidak ada pula suku maupun keluarga, bangsa atau kota satupun di tengah-tengah kita, yang menyembah allah buatan tangan, sebagaimana halnya di masa yang lampau.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 19, 'Dari sebab itulah maka nenek moyang kita diserahkan kepada pedang, dirampasi dan ditimpa malapetaka besar dari pihak para musuh kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 20, 'Tetapi kita ini tidak mengenal Allah lainnya kecuali Dia. Maka dari itu kita berharap, bahwa Allah tidak akan menghina kita ataupun salah seorang dari keturunan kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 21, 'Jika kita membiarkan diri kita direbut, niscaya seluruh Yudeapun akan direbut pula. Bait Suci kita akan dijarah dan dengan darah kita sendiri kita harus bertanggung jawab atas pencemarannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 22, 'Pembunuhan saudara-saudara kita, pembuangan seluruh isi negeri dan pemunahan milik pusaka kita akan ditanggungkan ke atas kepala kita di tengah-tengah bangsa-bangsa di mana kita akan menjadi budak. Kita akan menjadi batu sandungan dan orang terhina bagi mereka yang akan memiliki kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 23, 'Sebab perbudakan kita tidak membawa untung, melainkan Tuhan, Allah kita, akan membuatnya menjadi nista belaka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 24, 'Makanya, saudara-saudara, baiklah kita membuktikan kepada saudara-saudara kita, bahwa nyawa mereka boleh digantungkannya kepada kita dan bahwa yang tersucipun, yakni Bait Allah dan mezbah, dapat disandarkan pada kita ini.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 25, 'Oleh karena semuanya itu maka hendaklah kita bersyukur kepada Tuhan, Allah kita, yang mencobai kita seperti juga nenek moyang kita telah dicobai oleh-Nya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 26, 'Ingatlah akan apa yang telah diperbuat-Nya kepada Abraham dan bagaimana Ishak telah dicobai-Nya, dan ingatlah pula akan apa yang telah terjadi dengan Yakub di Mesopotamia Siria, ketika Yakub menggembalakan domba-domba Laban, pamannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 27, 'Memang sebagaimana nenek moyang kita itu telah dibesut oleh Allah guna menguji hati mereka, demikianpun kita ini tidak dihukum oleh-Nya. Sebab orang-orang yang dekat kepada-Nya didera oleh Tuhan sebagai peringatan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 28, 'Lalu berkatalah Uzia kepada Yudit: "Semuanya yang kauucapkan itu kaukatakan dengan hati yang baik dan tidak ada seorangpun akan membantah perkataanmu itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 29, 'Sebab bukan baru sekarang ini saja kebijaksanaanmu kentara sekali, tetapi sudah sejak permulaan umur hidupmu seluruh rakyat mengenal pengertianmu, sebagaimana perasaan hatimupun baik pula adanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 30, 'Akan tetapi rakyat sangat kehausan dan kami dipaksa untuk berbuat sebagaimana yang telah kami katakan kepada rakyat dan terpaksa kami mengikat diri kami dengan sumpah yang tidak dapat dibatalkan lagi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 31, 'Oleh sebab itu berdoalah untuk kami, sebab engkau adalah seorang perempuan yang saleh, niscaya Tuhan akan menurunkan hujan untuk memenuhi sumur-sumur kita. Lalu kita tidak akan merana lagi."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 32, 'Sahut Yudit kepada mereka: "Dengarkanlah aku ini. Aku hendak melakukan sesuatu yang turun-temurun akan dikisahkan kepada anak-anak bangsa kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 33, 'Kamu hendaklah berdiri di pintu gerbang kota pada malam ini juga. Maka aku hendak keluar bersama dengan dayangku. Dalam hari-hari, yang sehabisnya kamu telah berjanji akan menyerahkan kota ini kepada musuh kita, Tuhan akan mengunjungi Israel dengan perantaraanku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 34, 'Tetapi kamu jangan menyelidiki apa yang hendak kuperbuat, sebab aku tidak akan mengatakan apa-apa kepadamu, hingga sudah terlaksana apa yang hendak kulakukan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 35, 'Maka berkatalah Uzia dan para pemimpin kepada Yudit: "Selamat jalan! Semoga Tuhan Allah melindungi engkau untuk menghukum para musuh kita."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 8, 36, 'Kemudian mereka keluar dari gubuk itu dan pergi ketempat penjagaan masing-masing', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 1, 'Akan tetapi Yudit sujud menyembah, menaburi kepalanya dengan abu dan menunjukkan kain kabung yang dipakainya. Tepat pada saat itu dipersembahkan dalam Bait Allah di Yerusalem korban bakaran nyaring, katanya:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 2, '"Ya Tuhan, Allah bapaku Simeon yang di tangannya sudah Kautaruh sebilah pedang untuk menghukum orang-orang asing yang telah melepaskan ikat pinggang seorang gadis untuk menodainya, menelanjangi pahanya untuk mempermalukannya serta mencemarkan kandungannya untuk menistakannya. Sebab Engkau telah berfirman: Yang sedemikian itu tidak boleh. Namun oleh orang-orang asing itu dilakukan juga.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 3, 'Karena itu para pemimpin mereka Kauserahkan untuk dibunuh dan ranjangnya yang malu karena tipu daya mereka berlumuran dengan darah karena teperdaya. Hamba-hamba bersama dengan majikannya dan penguasa bersama dengan takhtanya telah Kauhantam.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 4, 'Isteri-isteri mereka Kauserahkan untuk dirampas dan anak-anak perempuan mereka Kauserahkan untuk diangkut tertawan dan rampasan mereka menjadi bagian anak-anak kekasih-Mu, yang berkobar-kobar keasyikannya dan yang menganggap keji penodaan orang sedarah serta mohon pertolongan kepada-Mu. Ya Allah, Allahku, dengarkanlah aku ini, seorang janda.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 5, 'Memang yang dahulu dan yang sekarang Kaulakukan seperti juga apa yang nanti akan terjadi. Engkaupun merencanakan yang sekarang maupun yang akan datang; dan apa yang sudah terjadi Kaurencanakan pula.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 6, 'Apa yang Kaukehendaki tampil ke muka seraya berkata: Lihatlah, kami ada di sini! Memang segala tindakan-Mu disediakan dan keputusan-Mu dirancangkan sudah.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 7, 'Sesungguhnya, orang-orang Asyur yang congkak karena bala tentaranya dan tinggi hati karena kuda serta penunggangnya lagi pongah karena pangkal lengan pasukan jalannya, menaruh percaya pada utar-utar dan pendahan, busur dan pengumban, sedangkan tidak mengetahui bahwa Engkaulah Tuhan yang menghancurkan alat-alat perang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 8, 'Tuhan, demikianlah nama-Mu. Dengan kekuasaan-Mu Kaurebahkan kekuatan mereka dan dengan kemurkaan-Mu Kaucampakkan tenaga mereka. Sebab mereka berniat akan mencemarkan Bait Suci-Mu, akan menajiskan kemah peristirahatan nama-Mu yang mulia dan akan mematahkan tanduk mezbah-Mu dengan besi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 9, 'Pandanglah kecongkakan mereka dan kirimkanlah kemurkaan-Mu ke atas kepala mereka. Berikanlah kepada tanganku, tangan seorang janda, tenaga untuk melaksanakan rencanaku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 10, 'Hantamkanlah dengan akal bibirku baik budak maupun tuannya, baik tuan maupun pelayannya. Hendaklah dengan perantaraan seorang perempuan Kaupatahkan ketinggian hati mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 11, 'Sebab kekuasaan-Mu tidak terletak di dalam jumlah besar dan kekuatan-Mu tidak pula pada orang-orang perkasa. Sebaliknya, Engkau adalah Allah orang yang hina-dina, Penolong orang kecil, Pembantu orang lemah, Pelindung orang yang kehilangan akal dan Penyelamat orang yang tanpa harapan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 12, 'Ya, ya! Allah bapaku, Allah pusaka Israel, Penguasa langit dan bumi, Pencipta air, Raja segala makhluk, dengarkanlah doaku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 13, 'Berilah, supaya perkataanku dan akalku itu mendatangkan luka-luka dan bilur-bilur kepada mereka yang merencanakan yang pahit-pahit terhadap perjanjian-Mu, terhadap Rumah-Mu yang Suci, puncak bukit Sion dan rumah milik anak-anak-Mu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 9, 14, 'Buatlah seluruh umat-Mu dan setiap suku menjadi insaf, sehingga mereka mengetahui bahwa Engkau adalah Allah, Tuhan segala kekuatan dan kekuasaan, dan bahwa tiada lainlah yang menjadi perisai bagi bangsa Israel kecuali Engkau!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 1, 'Maka berhentilah Yudit berseru kepada Allah Israel dan mengakhiri seluruh ucapan tadi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 2, 'Bangkitlah ia dari bersujud dan dipanggilnya dayangnya. Kemudian ia turun ke rumah tempat biasanya ia tinggal pada hari-hari Sabat dan hari-hari raya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 3, 'Dibukanya kain kabung yang sedang dipakainya, ditanggalkannya pakaian janda lalu mandi. Ia mengurapi dirinya dengan minyak wangi-wangian yang paling baik, dipatutkannya rambut kepalanya, ditaruhnya kulah-kulah di atasnya dan dikenakannya pakaian gembira yang dipakainya sewaktu suaminya Manasye masih hidup.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 4, 'Diambilnya kasut dan bersolek; dipasangnya kana, cincin, anting-anting dan segala perhiasannya. Maka ia tampak cantik sekali, sehingga membujuk mata semua orang laki-laki yang melihat dia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 5, 'Lalu dayangnya diberinya sekirbat anggur dan sebuli-buli minyak dan diisinya sebuah kantung dengan tepung jelai, beberapa lempeng buah-buah kering dan beberapa buah roti yang halal. Segenap bekal itu dibungkusnya lalu diserahkannya kepada dayangnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 6, 'Kemudian mereka keluar menuju pintu gerbang kota Betulia dan didapatinya di situ Uzia dan orang tua-tua kota, yakni Habris dan Harmis.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 7, 'Melihat Yudit yang parasnya sudah berubah dan yang pakaiannyapun sudah berganti sangat tercengang-cenganglah mereka atas kecantikannya. Lalu berkatalah mereka kepada Yudit:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 8, '"Moga-moga Allah nenek moyang kita menganugerahimu dan membuat rencanamu berhasil akan kebanggaan Israel dan keluhuran', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 9, 'lalu berkatalah ia kepada mereka: "Perintahkanlah untuk membuka pintu gerbang kota bagiku, sehingga aku dapat keluar untuk melaksanakan apa yang telah kamu katakan kepadaku." Merekapun lalu memerintahkan kepada para pemuda untuk membuka pintu gerbang bagi Yudit, sebagaimana telah dimintanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 10, 'Merekapun berbuat demikian pula. Maka Yudit bersama dengan pelayannya keluar. Orang-orang kota itu mengikuti dia dengan pandangannya, hingga ia turun dari gunung dan sampai di lembah di mana ia tidak kelihatan lagi oleh mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 11, 'Yudit serta pelayannya melanjutkan perjalanannya di lembah sampai terjumpai oleh pos penjagaan depan dari orang-orang Asyur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 12, 'Mereka menahan Yudit lalu bertanya: "Pihak manakah engkau? Dari mana engkau datang dan ke mana engkau mau pergi?" Sahutnya: "Aku ini seorang perempuan Ibrani. Aku melarikan diri dari mereka, karena tidak lama lagi mereka akan diserahkan menjadi mangsa kamu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 13, 'Aku ingin menghadap Holofernes, panglima besar bala tentaramu, untuk memberitahukan kebenaran kepadanya dan menunjukkan jalan yang harus ditempuh untuk menguasai seluruh pegunungan tanpa kehilangan satu orang atau satu jiwa yang hiduppun antara anak buahnya!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 14, 'Mendengar perkataannya itu dan melihat roman mukanya -- memang ia sangat menakjubkan bagi mereka karena kecantikannya -- orang-orang Asyur itu berkata kepada Yudit:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 15, '"Engkau sungguh telah menyelamatkan hidupmu dengan tergesa-gesa turun menghadap tuan kami. Silakan sekarang juga pergi ke kemahnya. Beberapa orang dari antara kami akan mengantarmu sampai mereka menyerahkan engkau ke tangan panglima kami.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 16, 'Bilamana engkau berdiri di hadapannya, jangan merasa takut. Beritahukanlah kepadanya sesuai dengan perkataanmu tadi, niscaya ia akan memperlakukan engkau dengan baik."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 17, 'Lalu dipilihnya seratus orang dari antara mereka, yang Holofernes.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 18, 'Maka dari seluruh perkemahan datanglah orang berkerumun, kemah. Sementara berdiri di luar kemah Holofernes hingga hal itu', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 19, 'Tercengang-cenganglah mereka atas kecantikan Yudit dan mereka menakjubi orang-orang Israel karena dia. Berkatalah mereka satu sama lain: "Siapa gerangan akan menghina bangsa yang memiliki perempuan secantik itu di tengah-tengahnya? Dari sebab itu tidaklah baik meninggalkan seorang laki-laki saja dari antara mereka. Yang masih hidup kelak kiranya mengakali seluruh bumi!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 20, 'Kemudian keluarlah beberapa jejenang dan semua pejabat', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 21, 'Adapun Holofernes sedang berbaring di pembaringannya di bawah sebuah kelambu yang terbuat dari kain ungu muda dan berpakankan emas, perak, jamrut dan permata-permata yang indah.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 22, 'Para pejabat memberitahu Holofernes tentang Yudit. Maka Holofernes pergi ke bagian depan kemahnya, sementara lampu-lampu perak dibawa di depannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 10, 23, 'Ketika Yudit tiba di hadapan Holofernes serta para pejabatnya, maka mereka sekalian takjub atas kecantikan parasnya. oleh hamba-hambanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 1, 'Kemudian kata Holofernes kepada Yudit: "Tetapkan hati, hai perempuan. Janganlah takut, sebab aku tidak berbuat jahat terhadap seorang juapun yang suka mengabdi kepada Nebukadnezar, raja bumi semesta.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 2, 'Sekiranya bangsamu yang mendiami pegunungan itu tidak menistakan aku, niscaya akupun tidak mengangkat tombak terhadap mereka. Tetapi kesemuanya itu didatangkan mereka sendiri atas dirinya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 3, 'Dan sekarang, katakanlah saja kepadaku apa sebabnya maka engkau melarikan diri dari pada mereka serta datang kepada kami? Memang engkau datang demi keselamatanmu. Tetapkan hati! Malam ini engkau akan tetap hidup dan juga selanjutnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 4, 'Sebab tiada seorang juapun akan berbuat jahat kepadamu, melainkan engkau akan diperlakukan baik-baik, sebagaimana selalu terjadi dengan hamba-hamba tuanku, raja Nebukadnezar."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 5, 'Sahut Yudit kepada Holofernes: "Sambutlah perkataan hamba ini dan perkenankanlah sahaya ini berbicara di hadapan tuanku, maka hamba tidak akan memberitahukan dusta kepada tuanku pada malam ini.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 6, 'Sekiranya tuanku menuruti perkataan sahaya, niscaya Allah akan melakukan sesuatu bagi tuanku dan tiada satupun dari rencana tuanku yang akan gagal.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 7, 'Sebab demi Nebukadnezar, raja bumi semesta, dan demi kekuasaan seri baginda yang mengutus tuanku untuk mengurus segala yang hidup. Bukan hanya manusia saja yang mengabdi kepada baginda karena tuanku, tetapi juga binatang buas maupun ternak dan burung-burung di udarapun akan hidup di bawah Nebukadnezar serta seisi rumahnya karena tuanku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 8, 'Sebab kami telah mendengar tentang kebijaksanaan tuanku serta tentang kepandaian budi tuanku. Sudah tersebarlah di seluruh bumi bahwa di seluruh kerajaan melulu tuanku adalah cakap dan berpengalaman besar serta patut dikagumi dalam hal siasat perang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 9, 'Akan segala sesuatunya yang telah diucapkan Akhior dalam sidang dewan penasehat perang tuanku, kami juga telah mendengar tentang perkataannya itu. Sebab penduduk Betulia menghidupi dia dan ia telah melaporkan semua yang telah dikatakannya di hadapan tuanku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 10, 'Dari sebab itu, ya junjungan dan tuanku, jangan tuanku mengabaikan perkataannya. Sebaliknya, baiklah tuanku perhatikan, sebab benar semuanya. Memang bangsa kami tidak dihukum dan pedangpun tidak berdaya terhadap mereka, apabila mereka tidak berdosa kepada Allah mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 11, 'Tetapi sekarang maut akan menimpa mereka, supaya tuanku jangan dipukul mundur dan gagal. Sebab mereka telah dihinggapi dosa yang dengannya Allah dimurkakan, apabila yang tak senonoh itu mereka lakukan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 12, 'Karena sejak makanannya habis dan airnyapun berkurang telah diambilnya keputusan untuk menjatuhkan tangannya kepada ternak mereka dan telah ditentukannya menghabiskan semuanya yang dilarang hukum Allah untuk dimakan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 13, 'Bahkan buah bungaran gandum dan bagian sepersepuluh anggur dan minyak yang mereka simpan untuk dipersembahkan kepada para imam yang di Yerusalem menyelenggarakan kebaktian di hadapan Allah kami sudah mau mereka habiskan. Sedangkan menyentuhnya dengan tangan saja tidak diperkenankan kepada seorang juapun dari kalangan rakyat.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 14, 'Merekapun telah mengutus pula orang ke Yerusalem -- sebab orang-orang yang tinggal di sana berbuat demikian juga -- untuk menerima izin bagi mereka dari Majelis Tertua.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 15, 'Maka dari itu akan terjadilah sebagai berikut: Segera setelah diberitahukan kepada mereka dan sesuai dengannya mereka perbuat, maka pada hari itu juga mereka akan diserahkan kepada tuanku untuk dibasmi.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 16, 'Itulah sebabnya maka hamba ini melarikan diri dari mereka, setelah sahaya ini mengetahui semuanya itu. Hamba telah diutus Allah ke mari untuk bersama dengan tuanku berbuat sesuatu yang akan memperanjatkan seluruh bumi, apabila hal itu mereka dengar.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 17, 'Sebab sahaya ini adalah saleh dan siang malam berbakti kepada Yang Berkuasa di sorga. Kini hamba bermaksud tinggal di sini, ya tuanku. Tiap-tiap malam sahaya ini hendak pergi ke jurang dan bersembahyang kepada Allah, niscaya Ia akan mengatakan kepada hamba, bilamana mereka berbuat dosa-dosa itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 18, 'Kemudian hamba hendak datang memberitahu tuanku. Maka hendaklah tuanku keluar dengan seluruh bala tentara tuanku, niscaya tidak ada seorang juapun dari antara mereka itu akan memberikan perlawanan kepada tuanku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 19, 'Selanjutnya hamba akan membawa tuanku melalui Yudea sampai di muka Yerusalem dan kursi tuanku akan hamba tempatkan di tengah-tengah kota itu. Tuanku akan menggiring mereka seperti domba-domba yang tidak ada gembalanya. Dan tiada anjing seekorpun akan menggonggong tuanku. Sebab semuanya itu sudah dikatakan kepada hamba menurut firasat hamba dan hambapun disuruh juga untuk memberitahukannya kepada tuanku."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 20, 'Holofernes serta para pejabatnya berkenan kepada perkataan lalu berkata:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 21, '"Dari ujung yang satu ke ujung yang lain bumi ini tiada perempuan serupa itu, yang secantik parasnya dan searif kata-katanya."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 22, 'Kemudian kata Holofernes kepada Yudit: "Allah sungguh berbuat baik dengan mengutus engkau ke mari mendahului bangsamu. Di tangan kamilah kekuasaan, tetapi semua orang yang menistakan rajaku teruntuk bagi kebinasaan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 11, 23, 'Rupamu sungguh manis dan segala katamu baiklah adanya. Apabila engkau berbuat sebagaimana kaukatakan, maka Allahmu akan menjadi Allahku dan engkau akan mendapat kedudukan dalam istana raja Nebukadnezar lalu engkau menjadi termasyhur di seluruh bumi."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 1, 'Lalu Holofernes mempersilakan mengantar Yudit ke tempat perkakas peraknya disimpan. Disuruhnya sajikan kepadanya dari hidangan-hidangannya sendiri dan beri minum dari air anggurnya sendiri.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 2, 'Tetapi berkatalah Yudit kepadanya: "Hamba tidak boleh makan dari padanya, nanti hamba menjadi batu sandungan. Apa yang hamba bawakan memadai hamba."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 3, 'Lalu kata Holofernes kepadanya: "Kalau nanti persediaan yang ada padamu itu sudah habis, dari mana gerangan dapat kami berikan yang sama kepadamu? Sebab pada kami tiada seorangpun dari bangsamu."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 4, 'Sahut Yudit kepadanya: "Demi tuan hidup, ya tuanku, sahaya ini tidak akan menghabiskan persediaan yang ada pada hamba ini, sebelum dengan perantaraan hamba ini Tuhan lakukan apa yang telah direncanakan-Nya."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 5, 'Kemudian Yudit diantar oleh para pejabat Holofernes masuk ke dalam kemah dan tidurlah ia hingga tengah malam. Pada waktu jaga pagi ia bangun.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 6, 'Lalu disuruhnya katakan kepada Holofernes: "Sudilah tuanku memerintahkan, supaya sahaya ini dibiarkan keluar untuk bersembahyang."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 7, 'Holofernespun lalu memerintahkan kepada pengawal pribadinya, perkemahan dan tiap-tiap malam keluarlah ia ke jurang Betulia dan mandi di sumber dekat pada pos penjagaan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 8, 'Setelah naik kembali berdoalah ia kepada Tuhan, Allah Israel, semoga Ia meratakan jalan-Nya guna kemuliaan orang-orang umat-Nya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 9, 'Setelah bersuci Yudit kembali dan tinggal di kemahnya hingga di petang hari dibawakan rezekinya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 10, 'Maka terjadilah pada hari keempat Holofernes mengadakan perjamuan minum-minum untuk para hambanya semata-mata. Dari antara para pegawai lainnya tidak seorang juapun diundang olehnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 11, 'Berkatalah Holofernes kepada sida-sida Bagoas, pengurus keperluan pribadinya: "Pergilah dan ajaklah perempuan Ibrani yang ada padamu itu untuk datang kepada kami dan makan minum bersama dengan kami.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 12, 'Sebab sungguh memalukan bagi kami apabila kami membiarkan perempuan serupa itu pergi tanpa beramah-tamah dengannya. Kalau kami tidak berhasil membujuk dia, niscaya kami akan ditertawakan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 13, 'Bagoaspun lalu pergi dari hadapan Holofernes. Datanglah ia menghadap tuanku untuk mendapat kehormatan dari padanya dan minum-minum air anggur dan beriang-riang bersama dengan kami lalu pada hari ini juga menjadi seperti anak perempuan Asyur yang tinggal di istana Nebukadnezar."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 14, 'Sahut Yudit: "Siapa gerangan aku ini sampai menentang tuanku? Bahkan bergegas-gegas hendak kuperbuat apa saja yang dipandang baik olehnya. Hal sedemikian itu akan menjadi sukacita bagiku hingga saat ajalku."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 15, 'Maka bangkitlah ia lalu berdandan dengan kainnya serta segala perhiasan perempuan. Dalam pada itu dayangnya pergi diperolehnya dari Bagoas guna keperluan sehari untuk berbaring atasnya sambil makan -- di tanah di hadapan Holofernes.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 16, 'Kemudian Yudit masuk ke dalam dan mengambil tempat. Adapun berahinya. Ia ingin sekali bersatu dengannya. Memang sejak hari', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 17, 'Berkatalah ia kepada Yudit: "Minumlah dan bersuka-sukalah bersama-sama dengan kami."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 18, 'Sahut Yudit: "Hamba mau minum, tuanku, sebab hari hidup hamba ini lebih menyenangkan dari semua hari lain seumur hidup hamba."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 19, 'Lalu Yudit mengambil apa yang disediakan sahayanya dan makan minum di hadapan Holofernes.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 12, 20, 'Holofernes bergembira atas Yudit dan minum amat banyak air anggur. Bahkan sebanyak itu belum pernah diminumnya pada satu hari sepanjang seluruh umur hidupnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 1, 'Ketika hari sudah jauh malam para hamba bergegas-gegas pergi dari situ. Kemah itu ditutup dari luar oleh Bagoas, yang juga menyingkirkan para hadirin dari hadapan tuannya. Pergilah mereka semua ke tempat tidurnya, sebab mereka sekalian sudah lelah oleh karena jamuan minum itu lama berlangsung.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 2, 'Adapun Yudit ditinggalkan seorang diri di kemah itu sementara Holofernes rebah tengkurap di pembaringannya. Sebab termandamlah ia karena anggur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 3, 'Yudit telah menyuruh sahayanya berdiri di luar di depan ruang tidur dan menunggu seperti hari-hari lainnya hingga ia keluar. Sebab -- demikian katanya -- ia mau keluar untuk bersembahyang. Kepada Bagoaspun telah dikatakannya yang sama juga.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 4, 'Kini semua orang sudah pergi dari situ. Baik dari yang tinggi maupun dari yang rendah kedudukannya tidak ada seorangpun pembaringan Holofernes seraya dalam hati berkata: "Ya Tuhan, Engkau Allah Yang Mahakuasa, sudilah kiranya dengan rela memandang pekerjaan tanganku pada saat ini yang akan menjadi keluhuran Yerusalem.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 5, 'Sebab kini sudah tiba waktunya untuk memperhatikan milik-Mu sendiri dan melaksanakan rencanaku untuk menghancurkan segala musuh yang telah bangkit melawan kami."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 6, 'Kemudian dihampirinya cagak pembaringan di dekat pada kepala Holofernes dan dari situ diambilnya pedang Holofernes sendiri.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 7, 'Didekatinyalah pembaringan itu, dipegangnya rambut kepala Holofernes lalu berkatalah ia: "Ya Tuhan, Allah Israel, kuatkanlah aku pada saat ini."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 8, 'Maka diparangnya tengkuk Holofernes sampai dua kali dengan segenap kekuatannya dan begitu dipenggalnya kepalanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 9, 'Digulingkannya tubuhnya dari ranjang dan diambilnya kelambu dari tiang-tiangnya. Sejurus kemudian keluarlah ia dan kepala Holofernes diberikannya kepada dayangnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 10, 'Dayang itu segera memasukkan kepala itu ke dalam kantungnya. Kemudian mereka berdua keluar, sebagaimana biasanya, untuk bersembahyang. Perkemahan dilintasinya, dikitarinya jurang itu lalu didakinya gunung Betulia dan tiba di muka pintu gerbang kota.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 11, 'Dari kejauhan berteriak-teriaklah Yudit kepada para penjaga di atas pintu gerbang kota, katanya: "Bukakanlah, bukakanlah pintu gerbang ini! Allah menyertai kita! Ya, Allah kita masih juga melakukan sesuatu yang hebat di Israel dan kuasalah Ia terhadap para musuh, sebagaimana kini telah dilakukan-Nya juga!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 12, 'Mendengar suaranya orang-orang di kota segera bergegas-gegas turun ke pintu gerbang dan memanggil orang tua-tua kota.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 13, 'Semua orang, besar kecil, berkerumun. Sebab mereka tidak gerbang kota dibuka dan kedua itu dipersilakan masuk. Kemudian pelayannya dikerubungi orang.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 14, 'Lalu Yudit berkata kepada mereka dengan suara nyaring: "Pujilah Allah! Pujilah Dia! Pujilah Allah yang tidak menjauhkan belas kasihan-Nya dari kaum Israel, melainkan pada malam ini menghancurkan para musuh kita dengan perantaraanku!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 15, 'Kemudian diambilnya kepala Holofernes dari kantungnya lalu diperlihatkannya seraya berkata kepada mereka: "Lihatlah kepala Holofernes, panglima besar bala tentara Asyur, dan lihatlah kelambu yang di bawahnya ia tidur termandam! Dengan perantaraan seorang perempuan ia telah ditewaskan oleh Tuhan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 16, 'Hiduplah Tuhan yang menjaga aku di jalan yang telah kutempuh. Panglima Asyur telah teperdaya oleh parasku akan kebinasaannya, tetapi ia tidak dapat berbuat dosa denganku untuk menodai dan mempermalukan!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 17, 'Seluruh rakyat tercengang sekali dan dengan membungkuk bersembahsujudlah mereka kepada Allah. Maka serempak mereka berkata: "Terpujilah Engkau, Allah kami, yang pada hari ini juga merendahkan para musuh umat-Mu!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 18, 'Uziapun berkata kepada Yudit: "Allah Yang Mahatinggi memberkatilah engkau, hai anakku, lebih dari pada semua perempuan di atas bumi; dan terpujilah Tuhan Allah, yang menciptakan langit dan bumi! Ia telah membimbing engkau untuk menghancurkan kepala panglima para musuh kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 19, 'Sungguh kenangan akan kepercayaanmu tak pernah akan lenyap dari hati manusia, yang selama-lamanya akan mengenangkan kekuatan Allah.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 13, 20, 'Moga-moga Allah membuat ini menjadi keluhuran abadi bagimu dan melimpahi engkau dengan yang baik. Sebab engkau tidak menyayangkan hidupmu sendiri ketika bangsa kita direndahkan. Sebaliknya, engkau telah mencegah keruntuhan kita dengan berlaku benar di hadapan Allah kita!" Maka seluruh rakyat menyahut: "Amin! Amin!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 1, 'Lalu Yudit berkata kepada mereka: "Dengarkanlah sekarang aku ini, saudara-saudara! Ambillah kepala ini dan gantunglah di bagian atas tembokmu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 2, 'Segera setelah fajar menyingsing dan matahari terbit atas bumi ambillah masing-masing segala senjatanya. Tiap-tiap orang laki-laki yang mampu harus keluar dari kota -- kamu juga harus mengangkat seorang pemimpin bagi mereka -- seolah-olah mau turun ke dataran menuju pos penjagaan depan dari orang Asyur. Tetapi jangan sungguh-sungguh turun.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 3, 'Mereka itupun lalu akan mengambil perlengkapannya, pergi ke perkemahan dan membangunkan para panglima bala tentara Asyur. Mereka akan berkerumun di dekat kemah Holofernes, tetapi tidak akan mendapati dia. Mereka akan dihinggapi ketakutan dan lari dari hadapan kamu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 4, 'Kamu serta segala penduduk wilayah Israel hendaklah mengejar mereka serta menewaskannya di manapun juga.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 5, 'Tetapi sebelum kamu berbuat demikian panggillah aku Akhior, orang Amon itu, agar ia melihat dan mengenal orang yang telah menghina kaum Israel dan mengirimkan Akhior kepada kita seperti ke dalam maut."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 6, 'Maka Akhior dipanggil dari rumah Uzia. Ketika tiba dan melihat kepala Holofernes di tangan seseorang di tengah himpunan rakyat itu maka rebahlah Akhior tengkurap dan jatuh pingsan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 7, 'Setelah diangkat mereka ia merebahkan diri pada kaki Yudit dan bersujud di hadapannya seraya berkata: "Diberkatilah engkau di dalam setiap kemah Yehuda, dan di tengah-tengah segala bangsa. Barangsiapa mendengar tentang namamu akan kaget.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 8, 'Dan sekarang hendaklah engkau memberitahukan kepadaku, apa yang telah kauperbuat selama hari-hari akhir ini." Yuditpun lalu menceritakan kepadanya di tengah-tengah rakyat segala sesuatunya yang telah dilakukannya sejak hari ia keluar hingga saat ia kini berbicara dengan mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 9, 'Ketika Yudit berhenti berbicara maka bersorak-sorailah rakyat dengan suara lantang dan bergemalah pekik kegembiraan di kotanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 10, 'Melihat semuanya yang telah dilakukan Allah Israel maka Akhior percaya dengan teguhnya akan Allah, lalu bersunat dan diterima ke dalam umat Israel hingga hari ini.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 11, 'Ketika fajar menyingsing kepala Holofernes digantungkan pada tembok dan setiap orang laki-laki Israel mengambil senjata. Berpasukan-pasukan keluarlah mereka ke lereng-lereng gunung.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 12, 'Segera setelah orang Asyur melihat orang-orang itu dikirimkannyalah seorang kepada para perwira yang segera pergi kepada para panglima, kepada para kepala seribu orang dan para penguasanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 13, 'Datanglah mereka kepada kemah Holofernes dan berbicara dengan pengurusnya, katanya: "Bangunkanlah tuan kita, sebab budak-budak itu berani turun untuk bertempur dengan kita, kiranya untuk dibasmi sama sekali."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 14, 'Maka Bagoas masuk dan bertepuk tangan di muka tirai kemah itu. Sebab dikiranya Holofernes sedang tidur bersama dengan Yudit.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 15, 'Tetapi oleh karena tidak ada yang menjawab maka diselakkannya tirai itu lalu masuk ke dalam ruang tidur. Didapatinya Holofernes menggeletak di lantai serta kepalanya terpenggal.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 16, 'Maka menjeritlah ia dengan suara keras diiringi tangis, keluhan dan teriakan yang hebat. Lalu disobeknya pakaiannya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 17, 'Kemudian ia masuk ke dalam kemah yang didiami Yudit tapi tidak didapatinya. Ia melonjak ke luar ke tengah-tengah rakyat seraya berteriak:', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 18, '"Budak-budak itu telah berkhianat. Satu perempuan Ibrani telah mendatangkan malu atas keluarga raja Nebukadnezar. Lihatlah, Holofernes telah rebah dan kepalanya tiada lagi."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 14, 19, 'Mendengar ucapan itu para panglima Asyur mengoyakkan pakaiannya dan hati mereka sangat terperanjat. Jeritan serta teriakan mereka memengking dengan sangatnya di seluruh perkemahan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 1, 'Ketika orang-orang yang masih berada di kemah mereka mendengar hal itu merekapun kebingungan atas kejadian itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 2, 'Mereka dihinggapi ketakutan dan kegentaran dan tidak ada satu orangpun masih tinggal bersama dengan kawannya. Mereka sekalian bercerai-berai dan lari menempuh semua jalan di dataran dan di daerah pegunungan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 3, 'Mundur pulalah mereka yang berkemah di pegunungan di keliling kota Betulia. Kini orang Israel -- tiap-tiap prajurit mereka -- menyerbukan diri kepada orang-orang Asyur.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 4, 'Uziapun mengirimkan juga orang ke Betomastaim, Bebai, Hobai, Kola dan ke seluruh wilayah Israel dengan kabar tentang apa yang telah terjadi dan dengan pesan, bahwa semua harus menyerbukan diri kepada musuh untuk menumpas mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 5, 'Mendengar hal itu semua orang Israel menyergap orang-orang Asyur dan dipukulnya mundur sampai ke Hoba. Demikianpun orang-orang dari Yerusalem dan dari seluruh daerah pegunungan menggabungkan diri, sebab mereka telah diberitahu tentang apa yang terjadi di perkemahan musuhnya. Pun pula orang dari daerah Gilead dan Galilea menggagahi musuh dengan pukulan yang hebat, hingga mereka sampai di kota Damsyik serta wilayahnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 6, 'Penduduk Betulia lain-lainnya menyergap perkemahan Asyur lalu merampasinya. Mereka memperoleh kekayaan besar.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 7, 'Adapun orang Israel yang kembali dari pertempuran merebut sisanya. Penduduk kampung-kampung dan dusun-dusun di daerah pegununganpun merampas pula rampasan yang besar, sebab bertumpah ruah sekalilah barangnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 8, 'Adapun imam besar Yoyakim dan Majelis Tertua Israel yang berkedudukan di Yerusalem datang untuk menyaksikan anugerah yang telah dilakukan Tuhan kepada Israel. Mereka datang juga untuk', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 9, 'Setibanya mereka memberkati Yudit dan berkata kepadanya: "Engkaulah keluhuran Yerusalem, kebanggaan besar bagi Israel dan kemegahan besar bagi bangsa kita.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 10, 'Dengan tanganmu kaulakukan semuanya itu dan begitu kaudatangkan anugerah kepada Israel dan Allah berkenan kepadanya. Diberkatilah engkau oleh Tuhan Yang Mahakuasa sepanjang masa selama-lamanya." Maka seluruh rakyat menyahut: "Amin! Amin!"', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 11, 'Seluruh rakyat merampoki perkemahan Asyur tiga puluh hari segala perabot perak, segala pembaringannya, semua batil serta bagalnya. Lalu kereta-keretanya dipasang dan dimuati juga dengan barang yang bertumpuk-tumpuk itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 12, 'Berkerumunlah semua perempuan Israel untuk melihat Yudit dan memberkatinya. Sebagian di antaranya mengadakan tari-tarian ranting-ranting di tangannya yang dibagi-bagikannya kepada semua perempuan yang ada sertanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 13, 'Ia sendiri dan juga teman-temannya mengenakan karangan daun zaitun lalu ia berjalan di depan seluruh rakyat sebagai pemimpin semua perempuan yang sedang menari berbaris. Semua orang laki-laki Israelpun mengikutinya dengan bersenjatakan lengkap dan dengan karangan-karangan dan lagu pujian.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 15, 14, 'Maka Yudit membawakan lagu syukur yang berikut di hadapan seluruh Israel; seluruh rakyatpun ikut menyanyikan lagu itu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 1, 'Kata Yudit: "Angkatlah nyanyian untuk Allah dengan iringan gendang, bernyanyilah bagi Tuhan dengan bunyi canang, gabungkanlah bagi-Nya mazmur dan kidung, tinggikanlah dan sebutkanlah nama-Nya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 2, 'Sebab Allah penghancur alat-alat perang Dialah Tuhan; di tengah umat-Nya telah dipasang-Nya perkemahan-Nya untuk melepaskan aku dari para pengejarku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 3, 'Datanglah Asyur dari pegunungan di sebelah utara, dengan puluhan ribu tentaranya ia telah datang; jumlahnya menyumbat sungai, dan bukit-bukit dibanjiri dengan kuda-kudanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 4, 'Berkatalah ia bahwa mau membakar wilayahku dan menumpas para pemudaku dengan pedang, membanting semua bayiku ke tanah dan membuat anak-anakku menjadi rampasan serta merampas anak-anak daraku.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 5, 'Tetapi mereka dicampakkan oleh Tuhan Yang Mahakuasa dengan perantaraan seorang perempuan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 6, 'Sebab pahlawan mereka tidaklah jatuh karena kaum muda dan mereka tidak dihantam oleh anak-anak para perkasa; mereka tidak disergap oleh buta jangkung, dengan keelokan parasnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 7, 'Pakaian jandanya ditanggalkannya dengan maksud meninggikan mereka yang tertindas dari Israel; mukanya diolesnya dengan urapan', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 8, 'dan rambutnya diikatnya dengan kulah-kulah; kain lenan dikenakannya untuk membujuk dia.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 9, 'Kasutnya memikat matanya hatinya terantaikan oleh kecantikannya lalu pedang menembusi tengkuknya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 10, 'Orang Persia gentar karena keberanian Yudit, dan atas tekadnya orang Media terperanjat.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 11, 'Bersorak-sorailah kaum hina-dinaku, sedangkan para musuh ketakutan, bersorak-sorailah orang lemah, tetapi para musuh terperanjat; kaum hina-dina melambungkan suaranya, tetapi kagetlah para musuh.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 12, 'Mereka ditikam anak-anak perempuan muda dan ditusuk bagaikan budak yang lari; karena ikat perang Tuhanku mereka jatuh binasa.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 13, 'Bagi Allahku kuangkat nyanyian baru. Ya Tuhan, besarlah Engkau dan mulia mengagumkan dalam kekuatan dan tak terkalahkan.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 14, 'Kepada-Mu mengabdilah segala ciptaan, sebab Engkau berfirman, maka semuanya terjadi; Kaukirimkan roh-Mu yang lalu membangun, dan tiada sesuatupun yang melawan suara-Mu.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 15, 'Sebab gunung-gemunung serta sekalian air rebah dari atas alasnya, dan batu meluluh di hadapan-Mu bagaikan lilin. Tetapi semua orang yang takut kepada-Mu sangat Kaukasihani mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 16, 'Memang setiap korban wangi-wangian terlalu kecil, dan lebih kecil lagi segala lemak yang dibakar bagi-Mu. Tetapi barangsiapa takut akan Tuhan besarlah ia selama-lamanya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 17, 'Celakalah sekalian bangsa yang melawan bangsaku; pada hari penghukuman dihukumlah mereka oleh Tuhan Yang Mahakuasa. Didatangkan-Nya api dan ulat ke dalam daging mereka dan selama-lamanya mereka menangis kesakitan."', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 18, 'Setibanya di Yerusalem mereka sujud menyembah kepada Allah. Setelah rakyat ditahirkan maka dipersembahkannya korban bakaran serta persembahan baktinya dan lagi sumbangan sukarela.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 19, 'Yuditpun menyampaikan pula segala perabot dari kemah Holofernes yang telah diberikan kepadanya oleh rakyat. Juga kelambu yang diambilnya sendiri dari ruang tidur itu dipersembahkannya kepada Allah sebagai sumbangan haram.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 20, 'Adapun rakyat bersukaria di Yerusalem di hadapan Bait Suci tiga bulan lamanya dan Yuditpun tetap tinggal serta mereka.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 21, 'Sesudahnya mereka pulang ke milik pusakanya masing-masing. tetap harum di seluruh negeri seumur hidupnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 22, 'Memang banyak orang meminang dia, tetapi ia tidak disentuh oleh seorang laki-laki lagi sepanjang masa hidupnya, semenjak Manasye, suaminya, meninggal dan dipersatukan dengan kaumnya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 23, 'Yudit menjadi sangat tua dan menguban di dalam rumah suaminya sampai seratus lima tahun. Ia memberikan kebebasan kepada dayangnya. Ia meninggal di kota Betulia dan dikubur dalam dua kubur Manasye, suaminya.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 24, 'Tujuh hari lamanya keluarga Israel berkabung. Sebelum saudara suaminya Manasye dan kepada sanak saudaranya sendiri.', 'id', 'Deutero'),
  ('68', 'ydt', 'Yudit', 16, 25, 'Selanjutnya tiada seorangpun mengganggu Israel di masa hidup Yudit maupun lama sesudah ia meninggal.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 1, 'Kasihilah kebenaran, hai para penguasa dunia, hendaklah pikiranmu tertuju kepada Tuhan dengan tulus ikhlas, dan carilah Dia dengan tulus hati!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 2, 'Ia membiarkan diri-Nya ditemukan oleh yang tidak mencobai-Nya, dan menampakkan diri kepada semua yang tidak menaruh syak wasangka terhadap-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 3, 'Pikiran bengkang-bengkung menjauhkan dari pada Allah, dan kekuasaan-Nya yang diuji mengenyahkan orang bodoh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 4, 'Sebab kebijaksanaan tidak masuk ke dalam hati keruh, dan tidak pula tinggal dalam tubuh yang dikuasai oleh dosa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 5, 'Roh pendidik yang suci menghindarkan tipu daya, dan pikiran pandir dijauhinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 6, 'Sebab kebijaksanaan adalah roh yang sayang akan manusia, tetapi orang penghujat tidak dibiarkannya terluput dari hukuman karena ucapan bibirnya. Memang Allah menyaksikan hati sanubarinya, benar-benar mengawasi isi hatinya dan mendengarkan ucapan lidahnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 7, 'Sebab roh Tuhan memenuhi dunia semesta, dan Ia yang merangkum segala-galanya mengetahui apapun yang disuarakan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 8, 'Maka tidaklah tersembunyi siapa saja yang fasik bicaranya, dan tidak dilewatkan keadilan penghukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 9, 'Rencana orang fasik akan diselidiki kelak, dan laporan tentang perkataannya sampai ke hadapan Tuhan, supaya pelanggaran-pelanggarannya dihukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 10, 'Sebab telinga-Nya dengan cemburu mendengar segala sesuatu, malah bunyi gerutupun tak tersembunyi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 11, 'Jadi, waspadalah terhadap gerutu yang sia-sia, dan awasilah lidahmu agar jangan memfitnah. Karena omongan tersembunyipun pasti ada akibatnya, dan mulut yang berdusta mematikan orang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 12, 'Jangan mencari-cari maut dengan hidup sesat, dan kebinasaan jangan kamu tarik dengan perbuatan tanganmu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 13, 'Memang maut tidak dibuat oleh Allah, dan Iapun tak bergembira karena yang hidup musnah lenyap.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 14, 'Sebaliknya Ia menciptakan segala-galanya supaya ada, dan supaya makhluk-makhluk jagat menyelamatkan. Di antaranyapun tidak ada racun yang membinasakan, dan dunia orang mati tidak merajai bumi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 15, 'Maka kesucian mesti baka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 1, 16, 'Tetapi dengan perbuatan dan kata para fasik telah memanggil maut dan didambakannya sambil memandangnya sebagai sahabat. Mereka mengadakan perjanjian dengannya, oleh karena mereka patut menjadi bagiannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 1, 'Karena angan-angannya tidak tepat maka berkatalah mereka satu sama lain: "Pendek dan menyedihkan hidup kita ini, dan pada akhir hidup manusia tidak ada obat mujarab; seseorang yang kembali dari dunia orang mati tidak dikenal.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 2, 'Serba kebetulan kita dijadikan, dan kelak kita ini seolah-olah tak pernah ada. Asap sajalah nafas di dalam hidung kita, dan pikiran hanya merupakan bunga api dari denyut jantung kita.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 3, 'Setelah padam maka tubuh akan menjadi abu, dan rohnya akan disebar-sebarkan bagaikan udara yang halus.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 4, 'Maka lambat laun nama kitapun terlupa pula, dan pekerjaan kita tidak seorangpun ingat kepadanya. Laksana jejak awan hidup kita berlalu, bagaikan kabut menghilang, dan dienyahkan oleh sinar matahari terkena oleh panas teriknya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 5, 'Umur hidup kita merupakan bayang-bayang yang berlalu, dan akhir hidup kita tak dapat ditunda, karena sudah dimeteraikan dan tak seorangpun dapat merubahnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 6, 'Jadi, marilah kita menikmati hal-hal baik yang masih ada, dan bergegas menggunakan alam seperti di masa muda!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 7, 'Marilah kita manfaatkan air anggur yang mahal serta wangi-wangian sepuas-puasnya, dan bunga musim semi janganlah kita lewatkan!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 8, 'Marilah kita mengenakan karangan kuncup mawar sebelum jadi layu!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 9, 'Di antara kita jangan seorangpun mengelakkan diri dari kesukaan kita! Hendaklah di mana-mana kita tinggalkan tanda-tanda keriangan kita, sebab itulah bagian dan nasib kita!"', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 10, '"Mari kita menindas orang miskin yang benar, jangan kita mengasihani janda, dan jangan peduli akan uban orang yang lanjut usia.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 11, 'Kekuatan kita hendaknya menjadi kaidah keadilan, sebab yang lemah ternyata tidak berguna.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 12, 'Marilah kita menghadang orang yang baik, sebab bagi kita ia menjadi gangguan serta menentang pekerjaan kita. Pelanggaran-pelanggaran hukum dituduhkannya kepada kita, dan kepada kita dipersalahkannya dosa-dosa terhadap pendidikan kita.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 13, 'Ia membanggakan mempunyai pengetahuan tentang Allah, dan menyebut dirinya anak Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 14, 'Bagi kita ia merupakan celaan atas anggapan kita, hanya melihat dia saja sudah berat rasanya bagi kita.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 15, 'Sebab hidupnya sungguh berlainan dari kehidupan orang lain, dan lain dari lainlah langkah lakunya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 16, 'Kita dianggap olehnya sebagai orang yang tidak sejati, dan langkah laku kita dijauhinya seolah-olah najis adanya. Akhir hidup orang benar dipujinya bahagia, dan ia bermegah-megah bahwa bapanya ialah Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 17, 'Coba kita lihat apakah perkataannya benar dan ujilah apa yang terjadi waktu ia berpulang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 18, 'Jika orang yang benar itu sungguh anak Allah, niscaya Ia akan menolong dia serta melepaskannya dari tangan para lawannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 19, 'Mari, kita mencobainya dengan aniaya dan siksa, agar kita mengenal kelembutannya serta menguji kesabaran hatinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 20, 'Hendaklah kita menjatuhkan hukuman mati keji terhadapnya, sebab menurut katanya ia pasti mendapat pertolongan."', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 21, 'Demikianlah mereka berangan-angan, tapi mereka sesat, karena telah dibutakan oleh kejahatan mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 22, 'Maka mereka tidak tahu akan rahasia-rahasia Allah, tidak yakin akan ganjaran kesucian, dan tidak menghargakan kemuliaan bagi jiwa yang murni.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 23, 'Sebab Allah telah menciptakan manusia untuk kebakaan, dan dijadikan-Nya gambar hakekat-Nya sendiri.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 2, 24, 'Tetapi karena dengki setan maka maut masuk ke dunia, dan yang menjadi milik setan mencari maut itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 1, 'Tetapi jiwa orang benar ada di tangan Allah, dan siksaan tiada menimpa mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 2, 'Menurut pandangan orang bodoh mereka mati nampaknya, dan pulang mereka dianggap malapetaka,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 3, 'dan kepergiannya dari kita dipandang sebagai kehancuran, namun mereka berada dalam ketenteraman.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 4, 'Kalaupun mereka disiksa menurut pandangan manusia, namun harapan mereka penuh kebakaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 5, 'Setelah disiksa sebentar mereka menerima anugerah yang besar, sebab Allah hanya menguji mereka, lalu mendapati mereka layak bagi diri-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 6, 'Laksana emas dalam dapur api diperiksalah mereka oleh-Nya, lalu diterima bagaikan korban bakaran.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 7, 'Maka pada waktu pembalasan mereka akan bercahaya, dan laksana bunga api berlari-larian di ladang jerami.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 8, 'Mereka akan mengadili para bangsa dan memerintah sekalian rakyat, dan Tuhan berkenan memerintah mereka selama-lamanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 9, 'Orang yang telah percaya pada Allah akan memahami kebenaran, dan yang setia dalam kasih akan tinggal pada-Nya. Sebab kasih setia dan belas kasihan menjadi bagian orang-orang pilihan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 10, 'Tetapi para fasik mendapat hukuman sesuai dengan angan-angannya, oleh karena mereka tidak menghiraukan yang benar dan telah murtad dari pada Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 11, 'Sungguh celakalah orang yang menghina kebijaksanaan dan ketertiban, hampalah harapan mereka dan sia-sialah jerih payahnya, dan segenap pekerjaannya percuma adanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 12, 'Para isteri mereka adalah bodoh, dan buruklah anak-anak mereka, keturunannya terkutuk.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 13, 'Tetapi berbahagialah perempuan mandul yang tak bercela dan tidak melanggar hukum di ranjang perkawinan; ia akan memetik buahnya pada hari pembalasan sekalian jiwa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 14, 'Demikianpun orang kebiri yang tangannya tidak berbuat jahat, dan yang tidak merencanakan yang buruk terhadap Tuhan. Untuk kesetiaannya ia akan diberi anugerah pilihan, dan bagian yang menyenangkan dalam Bait Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 15, 'Sebab terpujilah buah hasil jerih payah yang baik, dan akar pengertianpun tak dapat binasa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 16, 'Sebaliknya anak orang berzinah tidak menjadi dewasa, dan keturunan dari ranjang tak halal akan lenyap.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 17, 'Kalaupun mereka panjang umurnya, namun tidak dihargai sama sekali, dan hari tua mereka akhirnya tidak terhormat;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 18, 'jika mereka lekas mati, maka tidak ada harapan bagi mereka, dan pada hari penghakiman mereka tidak mendapat hiburan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 3, 19, 'Sebab bangsa orang yang lalim beratlah ajalnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 1, 'Dari pada begitu lebih baik tidak beranak tapi memiliki keutamaan, sebab kenangan akan keutamaan adalah baka, karena dikenal baik oleh Allah maupun oleh manusia.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 2, 'Jika ada keutamaan maka diteladan, jika sudah lenyap maka dirindukan orang. Selama-lamanya ia jaya sambil memakai karangan, karena telah menang dalam gelanggang pertandingan yang tak bercela.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 3, 'Jumlah besar anak para fasik tak menguntungkan, dan mereka tidak berakar dalam karena berasal dari carang tak asli, tidak pula mendapat alas yang kokoh kuat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 4, 'Kalaupun beberapa lamanya ranting-rantingnya subur, namun digoyah-goyahkan angin karena tidak tertanam kokoh kuat, lalu terbantun karena hebatnya angin.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 5, 'Cabang-cabang itu dipatahkan sebelum selesai tumbuhnya, buah mereka tidak berguna, terlalu mentah untuk dimakan dan sia-sia belaka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 6, 'Sebab anak-anak hasil seketiduran yang haram menjadi saksi keburukan bagi orang tuanya pada waktu pemeriksaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 7, 'Tetapi orang benar akan mendapat istirahat, meskipun mati sebelum waktunya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 8, 'Sebab usia lanjut adalah terhormat bukan karena waktunya panjang dan bukan karena tahunnya berjumlah banyak.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 9, 'Tetapi pengertian orang adalah uban, dan hidup yang tak bercela merupakan usia yang lanjut.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 10, 'Karena berkenan pada Allah maka orang benar dikasihi, ia dipindahkan sedang masih hidup di tengah-tengah orang berdosa;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 11, 'ia disentak, supaya kejahatan jangan mengubah budinya, dan tipu daya jangan membujuk jiwanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 12, 'Sebab pengaruh dari yang buruk menyuramkan yang baik, dan tumpukan hawa nafsu mengubah roh yang tak bercela.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 13, 'Karena sempurna dalam waktu yang pendek, maka orang benar memenuhi waktu yang panjang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 14, 'Tuhan berkenan kepada jiwanya, maka iapun diambil dari tengah-tengah kejahatan. Memang orang melihat tapi tak mengerti, dan tidak menaruh perhatian kepada yang berikut ini:', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 15, 'Kasih setia dan belas kasihan menjadi bagian orang pilihan Allah, bagi orang suci tersedia perlindungan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 16, 'Maka orang benar yang meninggal menghukum orang fasik yang hidup, dan masa muda yang lekas sempurna menghukum umur panjang orang yang lalim.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 17, 'Sungguhpun mereka melihat ajal orang yang bijak, tetapi tak mengerti apa yang direncanakan Tuhan baginya dan mengapa ia diamankan Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 18, 'Orang fasik melihat lalu menghina, tetapi mereka akan ditertawakan Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 19, 'Sesudahnya mereka menjadi mayat terhina, dan di tengah-tengah orang mati menjadi buah cemooh selama-lamanya. Terpelanting tak bersuara mereka dicampakkan Tuhan, dan digoyahkan-Nya dari dasar-dasarnya. Mereka akan dimusnahkan sama sekali, dan akan berada dalam sengsara. Maka kenangan kepada mereka akan lenyap.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 4, 20, 'Dengan cemas mereka akan tampil pada hari perhitungan dosa-dosa dan kejahatannya akan berhadapan dengan mereka sebagai penuduh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 1, 'Pada waktu itu orang benar berdiri dengan kepercayaan besar berhadapan muka dengan para penganiayanya dan semua orang yang telah menghina jerih payahnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 2, 'Melihat dia mereka akan gelisah karena ketakutan yang dahsyat, dan terperanjat karena keselamatannya yang tak terduga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 3, 'Mereka menyesal dan berkata satu sama lain sambil mengeluh karena kerisauan hatinya:', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 4, '"Dia itulah yang dahulu menjadi tertawaan kita, dan buah cercaan kita ini, orang-orang yang bodoh. Hidupnya kita pandang kegilaan belaka, dan ajalnya kita anggap tak terhormat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 5, 'Bagaimana gerangan ia sampai terbilang di antara anak-anak Allah, dan bagiannya terdapat di antara para kudus?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 6, 'Jadi kita inilah yang tersesat dari jalan kebenaran, dan cahaya kebenaran tidak menerangi kita, dan mataharipun tidak terbit bagi kita.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 7, 'Kita telah kekenyangan dengan menempuh lorong-lorong dosa yang membawa kebinasaan, dan kitapun telah menjelajahi padang gurun yang tak terjalani, sedangkan jalan Tuhan tidak kita kenal.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 8, 'Apa gerangan faedahnya kecongkakan bagi kita, dan apa gerangan yang dibawa oleh kekayaan yang dibualkan?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 9, 'Bagaikan bayang-bayang kesemuanya itu berlalu, laksana kabar yang melintas dengan cepatnya;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 10, 'seperti perahu yang mengarungi air yang bergelombang tidak terdapat bekas pelayarannya maupun jalan lunasnya di tengah-tengah ombak;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 11, 'atau bagaikan burung yang terbang melintasi udara tiada terdapat lagi tanda lintasannya -- sebab udara ringan disembat dengan kebasan sayap dan dibelah dengan kekuatan yang mendesing serta dipintas dengan kepak-kepakan sayap, tetapi sesudahnya tidak lagi terdapat tanda berlalunya burung --;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 12, 'atau juga seperti halnya anak panah yang dilepaskan menuju sasarannya: udara yang dibelah segera mengalir ke tempatnya dahulu, sehingga jalan anak panah tidak sampai diketahui.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 13, 'Demikian pula kita ini baru saja dilahirkan lalu lenyap lagi dan tidak ada tanda keutamaan satupun yang dapat kita perlihatkan, melainkan kita sudah dimakan habis dalam kejahatan kita."', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 14, 'Sebab harapan orang fasik adalah laksana sekam yang diterbangkan angin, seperti buih yang dihalaukan angin ribut; harapan itu seperti asap yang diceraiberaikan angin, dan berlalu seperti kenangan akan tamu yang datang sehari.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 15, 'Sebaliknya orang benar hidup selama-lamanya, dan ganjarannya ada pada Tuhan, dan mereka dipelihara oleh Yang Mahatinggi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 16, 'Maka dari itu mereka menerima kerajaan yang mulia dan mahkota yang indah dari tangan Tuhan. Sebab dengan tangan kanan-Nya Allah menaungi mereka, dan bagaikan perisai lengan-Nya melindungi mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 17, 'Allah akan mengenakan iri hati sebagai perlengkapan senjata, dan segenap makhluk dipersenjatai-Nya sebagai penangkis para musuh-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 18, 'Sebagai baju zirah dikenakan-Nya keadilan, dan Ia akan menggunakan pengadilan yang jujur sebagai ketopong.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 19, 'Kesucian yang tak teralahkan dipegang-Nya sebagai perisai,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 20, 'sedangkan kemurkaan kejam akan diasah-Nya menjadi pedang. Maka semesta alam bertempur serta-Nya melawan para pandir.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 21, 'Bagaikan anak panah yang kena berkilatlah mata petir dan terbang menuju sasarannya dari mega seperti dari busur yang terlengkung baik.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 22, 'Batu es yang berisi kemurkaan Tuhan dilemparkan dari pengumban, dan air laut berkecamuk melawan para fasik, dengan tak tertahan sungai-sungai membanjiri mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 5, 23, 'Angin yang kuat bangkit melawan mereka, dan bagaikan taufan mencerai-beraikan mereka. Maka kefasikan menjadikan bumi semesta padang gurun, dan takhta para penguasa ditumbangkan kejahatan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 1, 'Dengarkanlah, hai para raja, dan hendaklah mengerti, belajarlah, hai para penguasa di ujung-ujung bumi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 2, 'Condongkanlah telinga, hai kamu yang memerintah orang banyak dan bermegah karena banyaknya bangsa-bangsamu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 3, 'Sebab dari Tuhanlah kamu diberi kekuasaan dan pemerintahan datang dari Yang Mahatinggi, yang akan memeriksa segala pekerjaanmu serta menyelami rencanamu,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 4, 'oleh karena kamu yang hanya menjadi abdi dari kerajaan-Nya tidak memerintah dengan tepat, tidak pula menepati hukum, atau berlaku menurut kehendak Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 5, 'Dengan dahsyat dan cepat Ia akan mendatangi kamu, sebab pengadilan yang tak terelakkan menimpa para pembesar.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 6, 'Memang yang bawahan saja dapat dimaafkan karena belas kasihan, tetapi yang berkuasa akan disiksa dengan berat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 7, 'Sang Kuasa atas segala-galanya tidak akan mundur terhadap siapapun, dan kebesaran orang tidak dihiraukan-Nya. Sebab yang kecil dan yang besar dijadikan oleh-Nya, dan semua dipelihara oleh-Nya dengan cara yang sama.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 8, 'Tetapi terhadap yang berkuasa akan diadakan pemeriksaan keras.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 9, 'Jadi perkataanku ini tertuju kepada kamu, hai pembesar, agar kamu belajar kebijaksanaan dan jangan sampai terjatuh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 10, 'Sebab mereka yang secara suci memelihara yang suci akan disucikan pula, dan yang dalam hal itu terpelajar akan mendapat pembelaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 11, 'Jadi, hendaklah menginginkan serta merindukan perkataanku, maka kamu akan dididik.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 12, 'Kebijaksanaan bersinar dan tak dapat layu, mudah dipandang oleh yang kasih kepadanya, dan ditemukan oleh mereka yang mencarinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 13, 'Ia mendahului memperkenalkan diri kepada yang ingin kepadanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 14, 'Barangsiapa pagi-pagi bangun demi kebijaksanaan tak perlu bersusah payah, sebab ditemukannya duduk di dekat pintu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 15, 'Merenungkannya merupakan pengertian sempurna, dan siapa yang berjaga karena kebijaksanaan segera akan bebas dari kesusahan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 16, 'Sebab ia sendiri berkeliling mencari orang yang patut baginya, dan dengan rela memperlihatkan diri kepada mereka di jalan, pada tiap-tiap pikiran dijumpainya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 17, 'Sebab permulaan kebijaksanaan ialah keinginan sejati akan didikan, dan mencari didikan adalah kasih kepadanya;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 18, 'kasih kepadanya ialah memenuhi hukum-hukumnya. Dan memperhatikan hukum-hukumnya menjamin kebakaan,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 19, 'lalu kebakaan mendekatkan kepada Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 20, 'Maka menginginkan kebijaksanaan itu mengantar ke kerajaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 21, 'Makanya, kalau kamu suka akan takhta dan tongkat kerajaan, maka hargailah kebijaksanaan, hai para penguasa bangsa, agar kamu menjadi raja selama-lamanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 22, 'Apakah kebijaksanaan dan bagaimana kejadiannya hendak kuberitahu, dan rahasia satupun tidak akan kusembunyikan bagi kamu. Tetapi mulai dengan kejadiannya hendak kuselidiki serta kunyatakan pengetahuan tentangnya dan kebenaran tidak akan kulewatkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 23, 'Akupun tidak akan berteman dengan dengki yang membunuh, sebab dengki tidak bersekutu dengan kebijaksanaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 24, 'Besarnya jumlah orang bijak menjadi keselamatan dunia semesta, dan raja yang arif merupakan kesejahteraan rakyatnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 6, 25, 'Jadi baiklah kamu belajar dari perkataanku supaya beruntung.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 1, 'Akupun manusia yang fana sama seperti yang lain, keturunan orang yang pertama dibentuk dari tanah. Di dalam rahim ibu aku diwujudkan menjadi daging,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 2, 'dalam tempo sepuluh bulan aku membeku dalam darah, dari air mani seorang laki-laki dan kenikmatan yang menyertai seketiduran.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 3, 'Setelah dilahirkan akupun menghirup udara biasa, dan jatuh ke bumi yang merupakan nasib bersama. Suaraku pertama berupa tangis, sama seperti suara semua orang lain.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 4, 'Dengan kesayangan aku dibesarkan di dalam bedung.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 5, 'Sebab tidak ada seorang rajapun mempunyai permulaan hidup yang lain.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 6, 'Masuknya ke dalam hidup adalah satu dan sama bagi semua dan keluarnyapun demikian pula.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 7, 'Maka itu aku berdoa dan akupun diberi pengertian, aku bermohon lalu roh kebijaksanaan datang kepadaku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 8, 'Dialah yang lebih kuutamakan dari pada tongkat kerajaan dan takhta, dan dibandingkan dengannya kekayaan kuanggap bukan apa-apa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 9, 'Permata yang tak terhingga nilainya tidak kusamakan dengan dia, sebab segala emas di bumi hanya pasir saja di hadapannya dan perak dianggap lumpur belaka di sampingnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 10, 'Ia kukasihi lebih dari kesehatan dan keelokan rupa, dan aku lebih suka memiliki dia dari pada cahaya, sebab kilau dari padanya tidak kunjung hentinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 11, 'Namun demikian besertanya datang pula kepadaku segala harta milik, dan kekayaan tak tepermanai ada di tangannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 12, 'Terhadap semuanya itu aku bersuka hati, oleh karena kebijaksanaanlah yang memerintahnya; tetapi aku belum tahu bahwa dari dialah asalnya pula.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 13, 'Tanpa tipu daya aku belajar dan tanpa dengki aku membagi-bagi, dan kekayaan kebijaksanaan tidak kusembunyikan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 14, 'Sebab bagi manusia ia adalah harta benda yang tiada habisnya, dan orang yang menggunakannya menjadi sahabat Allah, oleh karena orang dipuji kepada-Nya karena karunia yang merupakan hasil pendidikan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 15, 'Semoga Allah memberi aku berbicara sesuai dengan kehendak-Nya, dan memikirkan apa yang berpatutan dengan segala pemberian-Nya. Sebab Ia sendirilah penuntun kebijaksanaan dan juga pemimpin para bijak.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 16, 'Memang baik kita sendiri maupun perkataan kita, lagipula pengertian dan segenap kepandaian ada di tangan Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 17, 'Sebab Ia sendiri telah memberi aku pengetahuan yang tidak menipu tentang segala-galanya yang ada, supaya kukenal susunan alam semesta dan daya anasirnya,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 18, 'awal dan akhir serta pertengahan masa, bilamana matahari berubah peredarannya dan musim silih berganti;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 19, 'supaya kukenal perputaran tahun dan tempat bintang-bintang,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 20, 'tabiat hewan dan naluri binatang buas, tenaga para roh dan pikiran manusia, jenis tumbuh-tumbuhan dan guna sekalian akar.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 21, 'Aku mengenal segala yang tersembunyi maupun yang nyata, oleh karena seniwati segala sesuatu yaitu kebijaksanaan mengajar aku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 22, 'Sebab di dalam dia ada roh yang arif dan kudus, tunggal, majemuk dan halus, mudah bergerak, jernih dan tidak bernoda, terang, tidak dapat dirusak, suka akan yang baik dan tajam,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 23, 'tidak tertahan, murah hati dan sayang akan manusia, tetap, tidak bergoyang dan tanpa kesusahan, mahakuasa dan memelihara semuanya serta menyelami sekalian roh, yang arif, murni dan halus sekalipun.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 24, 'Sebab kebijaksanaan lebih lincah dari segala gerakan, karena dengan kemurniannya ia menembusi dan melintasi segala-galanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 25, 'Kebijaksanaan adalah pernafasan kekuatan Allah, dan pancaran murni dari kemuliaan Yang Mahakuasa. Karena itu tidak ada sesuatupun yang bernoda masuk ke dalamnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 26, 'Karena kebijaksanaan merupakan pantulan cahaya kekal, dan cermin tak bernoda dari kegiatan Allah, dan gambar kebaikan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 27, 'Meskipun tunggal namun kebijaksanaan mampu akan segala-galanya, dan walaupun tinggal di dalam dirinya, namun membaharui semuanya. Dari angkatan yang satu ke angkatan yang lain ia beralih masuk ke dalam jiwa-jiwa yang suci, yang olehnya dijadikan sahabat Allah dan nabi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 28, 'Tiada sesuatupun yang dikasihi Allah kecuali orang yang berdiam bersama dengan kebijaksanaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 29, 'Sebab ia adalah lebih indah dari pada matahari, dan mengalahkan setiap tempat bintang-bintang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 7, 30, 'Berbanding dengan siang terang dialah yang unggul, sebab siang digantikan malam, sedangkan kejahatan tak sampai menggagahi kebijaksanaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 1, 'Dengan kuat ia meluas dari ujung yang satu ke ujung yang lain, dan halus memerintah segala sesuatu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 2, 'Aku jatuh cinta kepada kebijaksanaan dan kucari sejak masa mudaku, aku berusaha memperolehnya sebagai mempelaiku dan aku menjadi pencinta kemolekannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 3, 'Ia membanggakan asal usulnya yang luhur karena bergaul dengan Allah, dan dikasihi oleh Dia yang memerintah segala sesuatu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 4, 'Sebab kebijaksanaan adalah pengantar dalam pengetahuan Tuhan, dan memilih setiap pekerjaan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 5, 'Kalau kekayaan merupakan milik yang diinginkan dalam kehidupan, maka apa gerangan yang lebih kaya dari pada kebijaksanaan yang mengerjakan segala sesuatu?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 6, 'Kalau kepintaran yang bekerja, siapa gerangan di antara semua yang ada yang lebih berbakat seni dari pada kebijaksanaan?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 7, 'Dan kalau seseorang mengasihi kebenaran, maka kebajikan adalah hasil jerih payah kebijaksanaan. Sebab ia mengajarkan menahan diri dan berhati-hati, keadilan dan keberanian; dari pada semuanya itu tidak ada sesuatupun dalam kehidupan yang lebih berguna bagi manusia.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 8, 'Demikianpun kalau seseorang menginginkan banyak pengalaman, maka kebijaksanaan mengetahui yang dahulu dan mengirakan yang akan datang; ia pandai memahami penuturan yang kusut serta memecahkan teka-teki; tanda dan mujizat diketahuinya lebih dahulu, pun pula kesudahan zaman dan masa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 9, 'Maka itu aku memutuskan berjodoh dengannya sepanjang umur hidupku, sebab aku tahu bahwa diberinya aku nasehat yang baik dan menjadi penghibur dalam kesusahan dan kemasygulan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 10, 'Berkat kebijaksanaan aku akan mendapat kemuliaan pada rakyat, dan meskipun masih muda menjadi terhormat di antara orang-orang yang tua.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 11, 'Akan ternyata aku cepat dalam pengadilan, dan akan dikagumi oleh para pembesar.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 12, 'Kalau aku berdiam diri mereka akan menunggu, dan jika aku berbicara, niscaya mereka dengarkan; kalaupun aku memperpanjang bicaraku, mereka menaruh tangannya di mulut.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 13, 'Berkat kebijaksanaan aku akan memperoleh kebakaan dan meninggalkan kenangan abadi pada mereka yang menyusulku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 14, 'Pelbagai bangsa akan kuperintah dan pelbagai kaum menjadi takluk kepadaku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 15, 'Para penindas yang menakutkan akan takut kepadaku, pabila mendengar tentang diriku, di tengah-tengah rakyat ternyata aku baik dan gagah berani di pertempuran.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 16, 'Setelah masuk ke dalam rumahku aku mendapat ketenangan pada kebijaksanaan, sebab pergaulan dengannya tidak mengandung kepahitan, dan hidup bersama dengannya tidak mengenal kesedihan, melainkan hanya keriangan hati dan sukacita melulu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 17, 'Setelah semuanya itu telah kupikirkan dalam hati dan telah kurenungkan di dalam batin, yaitu: bahwa kebakaan terkandung dalam keakraban dengan kebijaksanaan', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 18, 'dan kesenangan yang luhur hidup dalam persahabatan dengannya, kekayaan yang tak kunjung habis terdapat di dalam jerih payah tangannya, dan pengertian ditemukan dalam menjaga pergaulan dengan dia serta nama yang harum dalam percakapan dengannya, maka aku berjalan keliling sambil mencari, bagaimanakah aku dapat membawa kebijaksanaan masuk pada diriku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 19, 'Memang aku seorang pemuda yang baik budi pekertinya, dan aku mendapat jiwa yang baik;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 20, 'atau sebaliknya: oleh karena aku ini baik, maka aku masuk ke dalam tubuh yang tak bercela.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 8, 21, 'Tetapi setelah aku tahu bahwa aku tidak akan memiliki kebijaksanaan, kalau tidak dianugerahkan Allah -- inipun hasil pengertian, yaitu mengetahui karunia siapakah kebijaksanaan itu --, maka aku menghadap Tuhan dan berdoa kepada-Nya dan dengan segenap hati aku berkata:', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 1, '"Allah nenek moyang dan Tuhan belas kasihan, dengan firman-Mu telah Kaujadikan segala sesuatu,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 2, 'dan dengan kebijaksanaan Kaubentuk manusia, agar ia menguasai segala makhluk yang telah Kauciptakan', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 3, 'dan memerintah dunia semesta dengan suci dan adil serta memegang kekuasaan dengan tulus hati.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 4, 'Berilah aku kebijaksanaan, teman setakhta-Mu, dan jangan aku Kautolak dari antara anak-anak-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 5, 'Sebab aku adalah hamba-Mu dan anak sahaya-Mu, manusia lemah yang pendek umurnya, miskin papa pengertiannya dalam hukum dan undang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 6, 'Sebab andaikata seseorang adalah sempurna di antara anak-anak manusia, tapi kebijaksanaan yang berasal dari pada-Mu tidak ada, niscaya ia tidak terbilang apa-apa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 7, 'Aku telah Kaupilih menjadi raja bagi umat-Mu ini dan jadi hakim bagi para anak-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 8, 'Engkau telah menyuruh untuk membangunkan Bait Allah di atas gunung-Mu yang suci, dan mezbah di kota tempat kediaman-Mu, suatu tiruan Kemah Suci yang sejak awal mula sudah Kausiapkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 9, 'Pada-Mu adalah kebijaksanaan yang mengenal segala pekerjaan-Mu, yang ada tatkala dunia semesta Kaujadikan, dan mengetahui apa yang diperkenankan oleh-Mu, dan lagi apa yang lurus menurut perintah-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 10, 'Maka sudilah kiranya mengirimkan dia dari sorga-Mu yang suci, dan mengutusnya dari takhta kemuliaan-Mu, agar ia ada padaku dan berusaha bersama denganku, dan aku mengetahui apa yang berkenan pada-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 11, 'Sebab kebijaksanaan mengetahui dan memahami segala-galanya, dan dengan bijak dapat memimpin aku dalam segala langkah lakuku serta menjaga aku dengan kemuliaannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 12, 'Maka segala pekerjaanku akan diterima, dan dengan adil aku akan memerintah umat-Mu, dan menjadi layak bagi takhta bapaku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 13, 'Manusia manakah dapat mengenal rencana Allah, atau siapakah dapat memikirkan apa yang dikehendaki Tuhan?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 14, 'Pikiran segala makhluk yang fana adalah hina, dan pertimbangan kami ini tidak tetap.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 15, 'Sebab jiwa dibebani badan yang fana, dan kemah dari tanah memberatkan budi yang banyak berpikir.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 16, 'Sukar kami menerka apa yang ada di bumi, dan dengan susah payah kami menemukan apa yang ada di tangan, tapi siapa gerangan telah menyelami apa yang ada di sorga?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 17, 'Siapa gerangan sampai mengenal kehendak-Mu, kalau Engkau sendiri tidak menganugerahkan kebijaksanaan, dan jika Roh Kudus-Mu dari atas tidak Kauutus?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 9, 18, 'Demikianlah diluruskan lorong orang yang ada di bumi, dan kepada manusia diajarkan apa yang berkenan pada-Mu, maka oleh kebijaksanaan mereka diselamatkan."', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 1, 'Kebijaksanaanlah yang melindungi bapa dunia semesta yang dibentuk sebagai manusia yang pertama, ketika hanya satu-satunya yang diciptakan. Kemudian kebijaksanaan menyelamatkan dia dari keruntuhannya,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 2, 'dan memberinya kekuatan untuk menguasai segala-galanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 3, 'Tetapi ketika seseorang yang lalim dalam amarahnya meninggalkan kebijaksanaan, maka ia jatuh binasa karena geramnya yang membunuh saudaranya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 4, 'Lagi-lagi kebijaksanaan menyelamatkan bumi ketika bumi oleh karena manusia dibanjiri air bah, dan orang benar dikemudikannya dengan kayu yang hina.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 5, 'Ketika para bangsa yang bersepakat dalam kejahatan dikacau-balaukan, maka kebijaksanaanlah yang mengenal orang yang benar dan menjagainya tak bercela bagi Allah, dan memeliharanya, supaya berteguh hati meskipun kasih sayang kepada anaknya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 6, 'Iapun menyelamatkan orang yang benar ketika para fasik jatuh binasa, sebab ia melarikan diri dari api yang turun atas Pancakota.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 7, 'Dari kejahatan penduduknya masih ada saksinya, yaitu gurun yang berasap terus dan tumbuh-tumbuhan yang berbuah dengan tidak berketentuan musimnya; lagi sebagai kenangan kepada jiwa yang tidak percaya maka tiang garam masih berdiri tegak.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 8, 'Sebab dengan melewatkan kebijaksanaan penduduk Pancakota tidak hanya mendapat rugi karena tidak mengenal yang baik, tetapi juga meninggalkan tanda yang mengingatkan kepada orang-orang yang hidup kebodohan mereka, sehingga tak tersembunyilah dalam hal manakah mereka bersalah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 9, 'Tetapi orang yang melayani kebijaksanaan telah diselamatkan olehnya dari kesusahan. Kebijaksanaanpun menuntun pula orang benar yang melarikan diri dari amarah kakaknya, lagi dipimpinnya melalui lorong-lorong yang lurus.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 10, 'Kebijaksanaan memperlihatkan kerajaan Allah kepadanya, dan memberi dia pengetahuan tentang hal-hal yang kudus; membuatnya sejahtera sebagai hasil jerih payahnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 11, 'Terhadap para pemerasnya yang serakah didampinginya, dan ia dijadikan kaya olehnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 12, 'Terhadap para musuhnya ia dilindungi oleh kebijaksanaan, dan diamankan terhadap para pengadangnya; ia diberinya hadiah kemenangan dalam pergulatan yang seru, supaya ia menjadi insaf, bahwa kesalehan lebih kuat dari pada apapun juga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 13, 'Kebijaksanaan tidak meninggalkan orang benar yang sudah dijual, melainkan menjagainya terhadap dosa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 14, 'Ia turun sertanya ke dalam penjara, dan dalam belenggupun tidak meninggalkannya, sampai tongkat kerajaan dibawakan kepada dia serta kekuasaan atas orang-orang yang menindasnya. Maka kebijaksanaan menyatakan para pendakwanya bohong, dan memberikan kemuliaan abadi kepada orang benar itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 15, 'Pun pula kebijaksanaanlah yang membebaskan bangsa suci dan keturunan yang tak bercela, dari bangsa penindas.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 16, 'Ia masuk ke dalam jiwa seseorang yang mengabdi kepada Tuhan, yang kemudian menghadapi raja-raja yang menakutkan dengan pelbagai mujizat dan tanda.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 17, 'Orang-orang suci diberinya upah pengganti jerih payahnya, dan dibimbingnya ke jalan yang ajaib; kebijaksanaan menjadi naungan di siang hari dan cahaya bintang di sepanjang malam.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 18, 'Dibuatnya mereka menyeberangi Laut Merah, dan dihantarnya melintasi air yang melimpah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 19, 'Tetapi para musuh ditenggelamkannya, lalu didamparkannya dari tubir yang dalam.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 20, 'Demikian orang-orang benar merampasi para fasik, lalu mereka bernyanyi bagi nama-Mu yang kudus, ya Tuhan, serta sehati memuji tangan pelindung-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 10, 21, 'Sebab kebijaksanaan membuka mulut orang bisu, dan membuat kanak-kanak menjadi petah lidah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 1, 'Dengan tangan seorang nabi yang suci ia memberikan hasil dari usaha mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 2, 'Maka orang-orang Israel menempuh gurun yang tak berpenduduk, dan memasang kemahnya di tempat-tempat yang tak ada jalan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 3, 'Mereka bertahan terhadap musuh dan menangkis para lawannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 4, 'Ketika menderita dahaga mereka berseru kepada-Mu, lalu diberi air dari batu karang yang keras, dan pemuas dahaga dari bukit batu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 5, 'Sebab apa yang menghukum musuh menjadi anugerah dalam kekurangannya bagi mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 6, 'Akan ganti sumber sungai yang mengalir terus, yang dikeruhkan darah keji', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 7, 'sebagai hukuman atas perintah pembunuhan kanak-kanak, mereka telah Kauberi dengan tidak tersangka-sangka air yang melimpah ruah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 8, 'Demikianlah dengan dahaga yang dialami mereka telah Kautunjukkan, bagaimana para lawan mereka telah Kauhukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 9, 'Ketika dicobai, meski hanya disiksa dengan belas kasihan sekalipun, maka diketahui mereka, bagaimana para fasik dianiaya, yang diadili dengan murka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 10, 'Orang-orang Israel telah Kaucobai dan Kauperingatkan selaku Bapa, sedangkan para musuh telah Kausiksa selaku raja kejam yang memutuskan hukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 11, 'Baik jauh maupun dekat sama-sama mereka disiksa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 12, 'Sebab kesedihan rangkap menimpa mereka, dan ada ratapan bila mereka ingat akan apa yang lampau.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 13, 'Mendengar bahwa apa yang menghukum mereka sendiri telah menjadi anugerah bagi Israel, maka para musuh merasakan Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 14, 'Orang yang dahulu dibuang sebagai anak dan yang telah ditolaknya dengan caci maki, harus mereka kagumi sesudah kejadian-kejadian itu, yaitu setelah mereka kehausan yang lain caranya dari orang-orang benar itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 15, 'Oleh karena pikiran-pikiran mereka yang bodoh dan jahat, yang menyesatkan orang-orang Mesir hingga memuja binatang melata yang tidak berakal serta hewan yang keji, maka telah Kaukirimkan kepada mereka banyak binatang yang tidak berakal sebagai hukuman.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 16, 'Maksudnya supaya mereka mengetahui bahwa seseorang akan dihukum dengan apa yang telah dipakainya untuk berdosa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 17, 'Memang tangan-Mu yang mahakuasa, yang telah menciptakan alam semesta dari debu tanpa bentuk, cukup berdaya untuk mendatangkan atas diri mereka beruang atau singa yang garang,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 18, 'atau binatang ciptaan baru yang galak dan belum dikenal, yang mengembuskan nafas berapi, atau menyemburkan asap yang berdesingan, atau yang matanya memancarkan bunga api yang dahsyat;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 19, 'macam-macam binatang yang tidak hanya dapat melukai mereka sampai tewas, tapi dapat juga membinasakannya hanya dengan pandangannya yang mengerikan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 20, 'Tetapi tanpa binatang semacam itupun mereka dapat jatuh binasa karena satu tiupan saja, sambil dikejar-kejar oleh keadilan serta ditiup-tiupkan oleh nafas kekuasaan-Mu. Akan tetapi segala-galanya telah Kauatur menurut ukuran, jumlah dan timbangan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 21, 'Memang bertindak yang sesuai dengan besarnya kekuasaan-Mu senantiasa ada dalam kemampuan-Mu, dan siapa gerangan dapat bertahan terhadap kekuatan lengan-Mu?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 22, 'Sebab seperti sebutir debu dalam neraca, demikian seluruh jagat raya di hadapan-Mu, atau bagaikan setetes embun pagi yang jatuh ke bumi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 23, 'Akan tetapi justru karena Engkau berkuasa akan segala sesuatu, maka semua orang Kaukasihani, dan dosa manusia tidak Kauperhatikan, supaya mereka bertobat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 24, 'Sebab Engkau mengasihi segala yang ada, dan Engkau tidak benci kepada barang apapun yang telah Kaubuat. Sebab andaikata sesuatu Kaubenci, niscaya tidak Kauciptakan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 25, 'Bagaimana sesuatu dapat bertahan, jika tidak Kaukehendaki, atau bagaimana dapat tetap terpelihara, kalau tidak Kaupanggil?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 11, 26, 'Engkau menyayangkan segala-galanya sebab itu milik-Mu adanya, ya Penguasa penyayang hidup!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 1, 'Roh-Mu yang baka ada di dalam segala sesuatu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 2, 'Dari sebab itu orang-orang yang jatuh Kauhukum berdikit-dikit, dan Kautegur dengan mengingatkan kepada mereka dalam hal manakah mereka sudah berdosa, supaya percaya kepada Dikau, ya Tuhan, setelah mereka menjauhi kejahatan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 3, 'Juga penduduk lama di negeri-Mu yang suci,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 4, 'telah Kaubenci, karena mereka mengerjakan yang lebih keji lagi, yaitu perbuatan sihir dan upacara yang fasik.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 5, 'Tanpa kenal kasihan mereka membunuh kanak-kanak dan makan jeroan dalam jamuan daging dan darah manusia dan tengah jamuan jangak masuk ke dalam kalangan orang-orang berilmu;', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 6, 'orang-orang tua sendiri membunuh makhluk-makhluk yang tidak berdaya. Mereka itu hendak Kautumpas dengan tangan nenek moyang kami,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 7, 'supaya tanah yang lebih berharga bagi-Mu dari segala-galanya mendapat penduduknya yang pantas, yakni anak-anak Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 8, 'Tetapi karena mereka manusia maka Kausayangkan pula dengan mengirimkan tawon-tawon besar sebagai pelopor tentara-Mu, supaya lambat laun mereka dibinasakannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 9, 'Bukanlah oleh karena Engkau tidak berdaya menyerahkan orang fasik ke dalam tangan orang benar di pertempuran, atau sekaligus membinasakan mereka dengan binatang-binatang galak atau dengan firman keras.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 10, 'Tetapi secara lambat laun Kauhukum untuk memberi kesempatan agar mereka bertobat, walaupun Engkau tahu, bahwa asal usul mereka adalah jahat dan kejahatan mereka sifat bawaan dan jalan pikiran mereka tak berubah selama-lamanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 11, 'Sebab mereka adalah keturunan yang terkutuk sejak awal mula. Bukan pula karena takut terhadap siapapun maka mereka Kaubiarkan terluput dari hukuman atas dosa mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 12, 'Sebab siapa nanti dapat berkata: "Apakah yang telah Kaulakukan?" atau siapa gerangan akan menentang keputusan-Mu? Siapa gerangan akan mendakwa Engkau karena telah Kaubinasakan bangsa-bangsa yang telah Kauciptakan sendiri, dan siapa akan tampil sebagai pengacara bagi kaum fasik dan membantah-Mu?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 13, 'Sebab kecuali Engkau, tidak ada Allah yang memelihara segala-galanya, sehingga Engkau harus membuktikan, bahwa Engkau menghukum dengan adil.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 14, 'Tiada raja ataupun penguasa yang dapat berhadapan dengan Dikau demi orang yang sudah Kauhukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 15, 'Tetapi karena Engkau adil adanya, maka secara adil Kauurus segala-galanya. Menjatuhkan hukuman atas orang yang tak patut dihukum Kauanggap tak layak bagi kekuasaan-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 16, 'Sebab asas keadilan-Mu ialah kekuatan-Mu, dan karena memerintah semuanya maka Engkau menyayangkan segala-galanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 17, 'Memang kekuatan hanya Kauperlihatkan pabila orang tak percaya akan kepenuhan kekuasaan-Mu, dan Kaupermalukan keberanian orang yang mengetahui kekuasaan-Mu itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 18, 'Tetapi Engkau, Penguasa yang kuat, mengadili dengan belas kasihan, dan dengan sangat hati-hati memperlakukan kami. Sebab kalau mau Engkau dapat juga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 19, 'Dengan berlaku demikian Engkau mengajar umat-Mu, bahwa orang benar harus sayang akan manusia. Anak-anak-Mu Kauberi harapan yang baik ini: Kauberikan kesempatan untuk bertobat apabila mereka berdosa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 20, 'Sebab kalau para musuh anak-anak-Mu, meskipun diperuntukkan bagi maut, Kaubalas dengan hati-hati dan kesabaran sedemikian itu, yaitu dengan memberikan waktu serta kesempatan untuk melepaskan kejahatan,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 21, 'betapa saksama kiranya Engkau mengadili anak-anak-Mu, yang nenek moyangnya telah Kauberi sumpah dan perjanjian yang berisi janji-janji yang baik!', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 22, 'Jadi sementara kami ini Kauperbaiki, maka para musuh kami sepuluh ribu kali lipat Kaudera, supaya kami sendiripun ingat pula akan kebaikan-Mu, apabila kami mengadili, lagi mengharapkan belas kasihan, apabila kami diadili.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 23, 'Maka itu para lalim yang terus melangsungkan hidupnya yang gila telah Kausiksa dengan kekejian mereka sendiri.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 24, 'Sebab mereka sangat tersesat di jalan-jalan yang menyeleweng dengan menerima apa yang paling keji di antara binatang yang hina sebagai allah, karena seperti kanak-kanak yang tidak berakal mereka teperdaya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 25, 'Maka itu seperti halnya bagi kanak-kanak yang tidak berakal demikianlah telah Kaukirimkan kepada mereka hukuman yang mencemoohkannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 26, 'Tetapi orang yang tidak mau diperingatkan dengan hukuman yang mencemoohkan akan mengalami keputusan yang patut bagi Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 12, 27, 'Karena semuanya yang menggusarkan hati mereka pada waktu mereka menderita dan yang dahulu mereka pandang sebagai allah, maka ketika disiksa dengannya mereka melihat Dia yang dahulu mereka tidak mau melihat-Nya, lalu mengakui Dia sebagai Allah sejati. Dari sebab itulah hukuman yang paling berat datang atas diri mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 1, 'Sungguh tolol karena kodratnya semua orang yang tidak mengenal Allah sama sekali; dan mereka tidak mampu mengenal Dia yang ada dari barang-barang yang kelihatan, dan walaupun berhadapan dengan pekerjaan-Nya mereka tidak mengenal Senimannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 2, 'Sebaliknya, mereka mengganggap sebagai allah yang menguasai jagat raya ialah api atau angin ataupun udara kencang, lagipula lingkaran bintang-bintang atau air yang bergelora ataupun penerang-penerang yang ada di langit.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 3, 'Jika dengan menikmati keindahannya mereka sampai menganggapnya allah, maka seharusnya mereka mengerti betapa lebih mulianya Penguasa kesemuanya itu. Sebab Bapa dari keindahan itulah yang menciptakannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 4, 'Jika mereka sampai dipesonakan oleh kuasa dan daya, maka seharusnya mereka menjadi insaf karenanya, betapa lebih kuasanya Pembentuk semuanya itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 5, 'Sebab orang dapat mengenal Khalik dengan membanding-bandingkan kebesaran dan keindahan ciptaan-ciptaan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 6, 'Namun demikian dalam hal ini mereka hanya sedikit saja salahnya, sebab mungkin mereka hanya tersesat, tetapi mereka mencari Allah dan berusaha menemukan-Nya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 7, 'Karena mereka sibuk dengan pekerjaan-Nya dan menyelidikinya, dan mereka terharu oleh yang mereka lihat, sebab memang indahlah hal-hal yang kelihatan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 8, 'Tetapi bagaimanapun juga mereka tidak dapat dimaafkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 9, 'Sebab jika mereka mampu mengetahui sebanyak itu, sehingga dapat menyelidiki jagat raya, mengapa gerangan mereka tidak terlebih dahulu menemukan Penguasa kesemuanya itu?', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 10, 'Tetapi celakalah orang yang menaruh harapannya pada benda mati, yang mendewakan buatan tangan manusia, yaitu emas dan perak, karya seni, dan gambaran macam-macam binatang, ataupun batu yang tidak berfaedah, buatan tangan zaman kuno.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 11, 'Misalkan seorang tukang kayu menggergaji pohon kayu yang mudah dikerjakan, kemudian membuang dengan cermat seluruh kulitnya, mengerjakannya sebagai mestinya, akhirnya membuatnya jadi perkakas yang berguna untuk keperluan hidup.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 12, 'Lalu bagian-bagian yang terbuang dari buatannya itu dipakainya untuk menyediakan makanan dan iapun menjadi kenyang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 13, 'Tetapi apa yang tak berguna dari bagian-bagian terbuang itu, yang tidak ada gunanya sama sekali, yaitu sepotong kayu bengkok yang banyak bonggolnya, diambilnya dan diukirnya pada waktu terluang, dan dengan tangkas dibentuknya di waktu istirahat serta dibuatnya jadi rupa manusia,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 14, 'atau diserupakannya dengan seekor binatang yang hina. Lalu disapunya dengan sedelinggam, dimerahinya kulitnya dengan cat dan dilumasnya setiap noda yang ada padanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 15, 'Lalu dibuatkannya baginya rumah-rumahan yang serasi, dan ditempatkannya pada dinding serta dilekatkannya dengan paku.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 16, 'Dijaganya pula agar jangan jatuh, sebab ia insaf bahwa patung itu tidak mampu menolong dirinya, karena hanya patung sajalah itu dan memerlukan pertolongan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 17, 'Tetapi kalau ia mendoakan harta miliknya, nikah serta anak-anaknya, ia tidak malu-malu bercakap-cakap dengan yang tidak bernyawa. Demi untuk kesehatan ia berseru kepada yang lemah,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 18, 'demi untuk kehidupan ia memuja yang mati, dan untuk bantuan ia mohon kepada yang tidak berdaya; untuk perjalanan ia mohon kepada yang tidak dapat menggunakan kaki,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 13, 19, 'demi keuntungan, pekerjaan dan hasil tangannya ia minta kekuatan kepada yang di dalam tangannya tidak ada kekuatan apapun.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 1, 'Ada lain orang yang hendak berlayar dan mau mengarungi gelombang yang menggelora; ia berseru kepada sepotong kayu yang lebih rapuh dari pada perahu yang membawanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 2, 'Sebab perahu itu telah direncanakan oleh nafsu akan keuntungan dan dibuat oleh seorang ahli dengan kejuruannya,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 3, 'tetapi yang mengemudikan ialah pemerintahan-Mu, ya Bapa, oleh karena Engkau telah membuka jalan di tengah laut dan lorong yang aman sentosa di tengah-tengah gelombang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 4, 'Dalam pada itu Engkaupun menunjukkan, bahwa Engkau dapat menyelamatkan dari apapun, sehingga malahan tanpa kepandaian orang boleh naik kapal.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 5, 'Memang Engkau tidak menghendaki bahwa buatan kebijaksanaan-Mu tidak berhasil; itulah sebabnya maka orang mempercayakan hidupnya kepada kayu yang amat hina dan dengan rakit melintasi gelombang yang berkecamuk sampai mereka selamat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 6, 'Sebab di zaman azali ketika para raksasa yang congkak tewas, maka harapan dunia berlindung di atas rakit; dan setelah Kaukemudikan dengan tangan-Mu, ditinggalkannya bakal keturunan bagi masa depan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 7, 'Sebab diberkatilah kayu yang dengannya kebenaran terlaksana,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 8, 'tetapi terkutuklah berhala buatan tangan beserta pembuatnya, oleh karena yang terakhir ini membuatnya, sedangkan yang pertama itu fana tetapi disebut allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 9, 'Sebab sama-sama dibenci oleh Allah baik orang fasik maupun hasil kefasikannya', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 10, 'dan bersama dengan pembuat buatannyapun akan dihukum.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 11, 'Maka itu segala berhala bangsa lain akan dijatuhi hukuman pula, oleh karena telah menjadi suatu kekejian di antara ciptaan Allah, suatu batu sandungan bagi diri manusia, dan suatu perangkap bagi kaki semua orang yang bodoh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 12, 'Sebab permulaan persundalan ialah penemuan berhala, dan pendapatannya merupakan pembusukan kehidupan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 13, 'Memang berhala tidak ada sejak awal mula dan tidak pula akan ada untuk selama-lamanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 14, 'Karena angan-angan manusia maka berhala tampil di dunia, dan oleh karena itu kesudahan segera direncanakan baginya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 15, 'Ada seorang bapa yang dimakan kesedihan yang belum waktunya, lalu membuat patung anaknya yang terenggut nyawanya sebelum saatnya. Maka seorang manusia yang dulu fana kini dihormatinya sebagai allah, dan kepada bawahan-bawahannyapun diperintahkan untuk mengadakan kebaktian dan upacara.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 16, 'Kemudian adat kebiasaan fasik yang lama kelamaan bertambah kuat itu dipenuhi sebagai undang-undang,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 17, 'dan atas perintah penguasa-penguasa patung-patung pahatan disembah. Oleh karena penguasa-penguasa itu tidak dapat dihormati orang dengan berhadapan muka karena jauh sekali tempat tinggalnya, maka wajah yang jauh itu dibayangkan mereka, lalu dibuatnya gambar yang nyata dari raja yang dihormati itu untuk merayu yang tak hadir itu seolah-olah hadir juga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 18, 'Selanjutnya gila hormat seniman mendorong bahkan orang yang tidak mengenal dia untuk memperkembangkan pemujaan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 19, 'Sebab seniman ingin cepat-cepat mendapat hati raja dan karena itulah dengan bakat seninya memperbesar kesamaannya sampai yang seindah-indahnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 20, 'Tetapi rakyat terpikat oleh kemolekan buatan itu kini menganggap patut dipuja yang tadinya dihormat sebagai manusia saja.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 21, 'Dan ini menjadi perangkap bagi kehidupan, bahwasanya orang yang tertekan karena malapetaka ataupun karena kekuasaan penguasa memberikan nama yang tak bersekutu kepada batu dan kayu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 22, 'Selanjutnya belum lagi cukup bagi mereka bahwa tersesat pengetahuannya tentang Allah, tetapi sementara hidup dalam pergulatan hebat dari kejahilannya itu mereka malahan sampai menyebut perdamaian akan malapetaka-malapetaka sebesar itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 23, 'Sebab apakah mereka melakukan tahbisan-tahbisan yang disertai pembunuhan kanak-kanak, ataupun upacara-upacara gaib yang serba rahasia, atau jamuan-jamuan yang kegila-gilaan dengan adat kebiasaan yang ganjil,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 24, 'sudah barang tentu mereka tidak memelihara lagi kesucian kehidupan dan perkawinan, melainkan saling membunuh dengan curang atau menyusahkan dengan zinah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 25, 'Di mana-mana bersimaharajalela darah dan pembunuhan, pencurian dan tipu daya, kebusukan, pencederaan, huru-hara dan sumpah dusta,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 26, 'penggangguan orang-orang yang baik, lupa akan jasa orang lain, pencemaran jiwa, percabulan melawan kodrat alam, kebobrokan perkawinan, zinah dan menjangak.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 27, 'Sebab pemujaan allah-allah yang hampa adalah awal, sebab dan akhir segala kejahatan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 28, 'Para pemujanya bermata gelap dalam kesuka-sukaannya, atau meramalkan kebohongan belaka, hidup secara fasik atau mengangkat sumpah dusta.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 29, 'Karena mereka percaya kepada berhala yang tidak bernyawa, maka mereka tidak menyangka, bahwa akan dihukum karena sumpah dusta.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 30, 'Akan tetapi karena kedua hal ini mereka akan ditimpa hukuman yang adil, yaitu: bahwa salahlah pikiran mereka tentang Allah karena mereka melekat kepada berhala, dan bahwa mereka dalam kebohongan bersumpah dusta dengan menghina kesucian akibat kepintarannya yang busuk.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 14, 31, 'Sebab bukannya kekuasaan berhala yang diberi sumpah, melainkan hukuman atas orang yang melakukan dosa, itulah yang selalu menimpa pelanggaran kaum fasik.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 1, 'Tetapi Engkau, Allah kami, adalah baik hati lagi setia, sabar hati dan dengan kasih sayang memerintah segala-galanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 2, 'Sebab kalau kadang-kadang kami berdosa, kami adalah milik-Mu oleh karena kami ini mengenal daya kekuatan-Mu. Tetapi kami tidak mau berdosa karena kami insaf, bahwa kami ini kepunyaan-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 3, 'Sebab mengenal Engkau adalah kesucian sempurna, dan menjadi insaf akan kekuatan-Mu merupakan akar kebakaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 4, 'Memang kami ini tidak disesatkan oleh hasil kesenian insani yang buruk, dan tidak pula oleh buatan sia-sia para pelukis, yaitu gambar yang dilumasi dengan beraneka warna,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 5, 'yang pemandangannya merangsang hawa nafsu pada orang bodoh, sehingga ia rindu kepada rupa mati dari gambar yang tidak bernyawa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 6, 'Semua yang membuat atau merindukan atau memuja berhala adalah pencinta kejahatan dan patut bagi harapan yang demikian itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 7, 'Demikianpun seorang tukang periuk meramas tanah lembab dengan susah payahnya, lalu dibentuknya menjadi apa saja untuk keperluan kita. Tetapi dari tanah liat yang sama dibentuknya baik bejana untuk keperluan yang tahir maupun untuk keperluan yang keji. Sedangkan untuk apakah akan digunakan tiap-tiap bejana, itu ditentukan oleh tukang periuk belanga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 8, 'Tetapi dari tanah liat yang sama dan dengan susah payah yang buruk dibentuknya suatu allah yang hampa udara belaka. Allah itu dibentuk oleh seorang yang juga terjadi sendiri dari tanah beberapa waktu sebelumnya, dan sejurus lagi akan kembali ke tanah liat, yang merupakan bahan asalnya, yaitu pabila hutang ialah jiwanya di tagih.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 9, 'Tetapi ia tidak peduli bahwa segera akan meninggal dan hanya mempunyai umur yang pendek. Sebaliknya ia bertanding dengan pandai emas dan pandai perak serta meniru juru penuang perunggu, dan menganggap suatu kehormatan membuat barang tiruan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 10, 'Abulah hatinya dan lebih hina dari tanahlah harapannya, dan hidupnyapun kurang berharga dari tanah liat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 11, 'Sebab ia tidak mengenal Dia yang telah membentuknya dan menghembuskan semangat ke dalam tubuhnya serta meniupkan nafas kehidupan ke dalamnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 12, 'Orang semacam itu menganggap hidup kita suatu permainan dan hayat sebagai pasar yang membawa keuntungan. Katanya: "Orang harus menarik untung dari apapun juga, bahkan dari kejahatan sekalipun."', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 13, 'Sebab tukang berhala tahu lebih baik dari pada semua orang lainnya bahwa ia berbuat dosa, apabila dari bahan tanah dibuatnya bejana yang rapuh maupun berhala.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 14, 'Tetapi sangat bodoh dan lebih papa dari pada jiwa kanak-kanak semua orang itu, yaitu para musuh umat-Mu yang telah memperbudaknya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 15, 'Karena mereka malah menganggap berhala bangsa-bangsa lainpun sebagai allah, meskipun berhala-berhala itu tidak dapat menggunakan matanya untuk melihat, tidak pula hidung untuk menghirup udara, ataupun telinga untuk mendengar, atau jari-jari tangan untuk meraba, sedang kakinyapun tidak mampu berjalan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 16, 'Sebab mereka dibuat oleh seorang manusia, dan dibentuk oleh seorang yang rohnya sendiri adalah barang pinjaman. Sebab tidak ada seorangpun yang mampu membentuk allah yang sederajat dengan dirinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 17, 'Karena ia sendiri fana adanya, maka dengan tangannya yang jahat ia hanya dapat mengerjakan barang mati saja. Sebab ia sendiri sesungguhnya lebih baik dari pada benda pujaannya, oleh karena ia sendiri pernah hidup sedangkan benda itu tidak pernah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 18, 'Bahkan binatang yang sangat kejipun dipuja pula oleh para musuh umat-Mu, sebab kalau dibandingkan kebodohannya maka binatang-binatang itu lebih rendah dari pada yang lain-lain.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 15, 19, 'Tidak ada rupa yang bagus yang dapat diinginkan, seperti kalau orang memandang binatang, sebab binatang-binatang itu tidak dipuji dan tidak diberkati oleh Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 1, 'Karena itu para pemujanya sebagaimana mestinya dihukum dengan binatang-binatang yang serupa itu, dan disiksa oleh banyak hewan kecil.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 2, 'Tetapi akan ganti hukuman itu telah Kaubuat baik kepada umat-Mu. Untuk seleranya yang hebat telah Kausediakan hidangan istimewa sebagai makanan, yaitu burung-burung puyuh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 3, 'Sedangkan pihak musuh, walaupun ingin makan, kehilangan selera yang perlu, karena jijiknya binatang-binatang yang dikirimkan itu, umat-Mu malah menikmati hidangan istimewa setelah sebentar menderita kekurangan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 4, 'Memang atas pihak para penindas patut datang kekurangan yang tak terelakkan, tetapi kepada umat-Mu patut ditunjukkan, bagaimana musuh-musuhnya disiksa.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 5, 'Sebab juga ketika geram hebat binatang-binatang yang galak mendatangi umat-Mu dan mereka tewas karena dipagut ular-ular yang melilit, maka kemurkaan-Mu tidak berlangsung terus sampai ke penghabisan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 6, 'Melainkan sebagai peringatan mereka dikejutkan sebentar, lalu mendapat tanda keselamatan sebagai kenangan akan hukum Taurat-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 7, 'Sebab barangsiapa berpaling kepada tanda itu tidak diselamatkan oleh apa yang dilihatnya, melainkan oleh-Mu, ya Penyelamat segala orang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 8, 'Dengan itupun telah Kauyakinkan pula para musuh kami, bahwa hanya Engkaulah yang menyelamatkan dari segala malapetaka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 9, 'Musuh-musuh kami ditewaskan dengan gigitan belalang dan lalat, dan tiada terdapat obat mujarab untuk menghidupkan mereka, sebab mereka patut dihukum dengan binatang-binatang semacam itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 10, 'Sedangkan anak-anak-Mu tidak kalah terhadap gigi ular-ular berbisa, sebab belas kasihan-Mu datang menolong serta menyembuhkan mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 11, 'Untuk mengingatkan sabda-Mu kepada mereka maka mereka dipagut, tapi segera mereka disembuhkan pula, supaya mereka jangan terlepas dari kemurahan-Mu dan sama sekali melupakannya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 12, 'Sebab bukan tumbuh-tumbuhan atau balut yang telah menyembuhkan mereka, melainkan Firman-Mu yang memulihkan semua, ya Tuhan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 13, 'Memang Engkau mempunyai kuasa atas hidup dan mati, dan Engkaulah yang menurunkan ke pintu gerbang dunia orang mati dan juga menaikkan dari padanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 14, 'Sudah barang tentu manusia membunuh dalam kejahatannya, tapi ia tak mampu mengembalikan roh yang sudah keluar, dan tak dapat melepaskan jiwa yang sudah diterima dunia orang mati.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 15, 'Mustahillah sama sekali melepaskan diri dari tangan-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 16, 'Sebab para fasik yang menolak untuk mengenal Engkau, telah didera dengan kekuatan lengan-Mu, dan dikejar-kejar oleh hujan lebat yang luar biasa, oleh hujan es dan guntur gemuruh yang tak terelakkan, lalu habis ditelan api.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 17, 'Malah yang paling aneh terjadi, yakni: di dalam air yang memadamkan segala-galanya api itu semakin berdaya, sebab alam semesta berjuang demi orang benar.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 18, 'Ada kalanya nyala api tertahan, supaya jangan membakar binatang-binatang yang dikirimkan melawan para fasik, agar melihat itu mereka menjadi insaf bahwa mereka dikejar-kejar oleh keputusan Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 19, 'Tetapi ada kalanya pula nyala api berkobar-kobar melebihi kekuatan api, malahan di tengah-tengah air, untuk membinasakan tanam-tanaman di tanah orang yang fasik itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 20, 'Sebaliknya umat-Mu telah Kauberi santapan malaikat menjadi makanannya, dan tanpa susah payah mereka Engkau telah mengirimkan dari sorga roti yang telah disediakan, yang mengandung segala kenikmatan dan cocok dengan selera masing-masing.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 21, 'Sebab rezeki yang Kauanugerahkan itu menunjukkan kemanisan-Mu terhadap anak-anak-Mu, dan rezeki itu menyesuaikan diri dengan keinginan orang yang memakannya dan berubah menjadi apa yang dikehendaki masing-masing.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 22, 'Salju dan es bertahan terhadap api tanpa meleleh, supaya diketahui bahwa hanya buah-buahan para musuh habis punah dimakan oleh api yang bernyala-nyala di tengah hujan es dan berkilat-kilat dalam hujan deras.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 23, 'Sebaliknya api lupa akan kekuatannya sendiri, supaya orang benar diberi makan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 24, 'Sebab alam ciptaan-Mu yang mengabdi kepada Pembuatnya memperbantukan tenaganya hendak menghukum para fasik, tetapi juga menahan diri dengan maksud berbuat baik kepada orang yang percaya kepada-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 25, 'Karena itu alam pada saat itu berubah menjadi segala hal dan melayani karunia-Mu yang memelihara segala sesuatu, seperti dibutuhkan masing-masing.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 26, 'Maksudnya supaya anak-anak-Mu yang Kaukasihi, ya Tuhan, menjadi tahu bahwa bukan pelbagai jenis buah-buahan memberi makan kepada manusia, melainkan firman-Mu, yang memelihara semua orang yang percaya pada-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 27, 'Sebab apa yang tidak dapat dihancurkan oleh api, meleleh begitu saja kalau dipanaskan sinaran matahari,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 28, 'agar dimaklumi bahwa sebelum matahari terbit orang hendaknya menyampaikan doa syukur kepada-Mu dan menghadap ke hadirat-Mu sebelum cahaya terbit.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 16, 29, 'Memang harapan orang yang tidak kenal terima kasih meleleh bagaikan embun beku di musim dingin dan lenyap laksana air yang tidak dimanfaatkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 1, 'Tentu besarlah segala keputusan-Mu dan tak terurai, maka itu orang yang tidak terdidik telah tersesat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 2, 'Sebab para fasik yang menyangka dapat memperbudak bangsa yang suci telah ditawan oleh kegelapan dan terbelenggu oleh malam yang panjang, sehingga terkurung berbaring di dalam rumahnya sendiri, seperti orang yang mau melarikan diri dari pemerintahan Tuhan yang abadi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 3, 'Karena mereka menyangka dapat tetap tersembunyi dengan dosa-dosanya yang rahasia, terlupa di bawah selubung kegelapan, maka sangat terkejut mereka dicerai-beraikan dan cemas karena bayangan-bayangan hantu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 4, 'Sebab persembunyian yang melindungi mereka tidak meluputkan mereka dari ketakutan. Sebaliknya bunyi-bunyi yang menakutkan menderu-deru di sekelilingnya, dan tampaklah hantu-hantu muram yang suram mukanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 5, 'Tak suatupun api dapat mendatangkan cahaya, dan nyala bergemerlapan dari bintang-bintangpun tidak mampu menerangi malam kelam yang mengerikan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 6, 'Hanya tampak oleh mereka gumpalan api yang penuh kengerian, yang timbul dengan sendirinya. Maka ketakutanpun menghinggapi mereka, dan apabila gejala itu tidak nampak maka yang telah kelihatan itu dianggapnya semakin mengerikan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 7, 'Percumalah tipu daya dari ilmu sihir mereka, dan bukti kepandaian yang dibanggakannya ternyatalah nista.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 8, 'Sebab semua orang yang telah berjanji akan mengenyahkan ketakutan dan kegelisahan dari jiwa yang sakit, bahkan jatuh sakit sendiri karena kecemasan yang mentertawakan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 9, 'Dan kalau tidak ada sesuatu kengerian menakutkan mereka, namun mereka dikejut-kejutkan oleh binatang-binatang kecil yang berlalu dan oleh ular-ular yang mendesir-desir, sehingga mereka mati ketakutan dan enggan menengadah ke udara yang di manapun tak dapat dihindari.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 10, 'Memang kejahatan yang dihukum atas kesaksiannya sendiri adalah pengecut, sebab selalu menyangka yang terburuk karena diusik-usik suara hatinya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 11, 'Sebab ketakutan tidak lain ialah melepaskan pertolongan dari akal budi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 12, 'Semakin kecil kepercayaan yang ada dalam hati manusia, semakin dianggap buruk ketidaktahuan tentang sebab musabab yang mengakibatkan siksaan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 13, 'Adapun semua orang yang sama-sama tidur pada malam yang tanpa daya dan yang datang dari dunia orang mati yang tanpa daya itu,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 14, 'setengahnya dikejar-kejar oleh bayangan hantu yang dahsyat, setengahnya dilumpuhkan karena putus harapannya. Sebab mendadak dan tidak tersangka-sangka mereka dihinggapi oleh ketakutan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 15, 'Demikianlah siapa saja ditawan di tempat ia rebah dan dikurung dalam penjara tanpa jeruji.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 16, 'Sebab baik ia seorang petani atau gembala maupun seorang buruh yang berjerih payah tersendiri, tiba-tiba ia disergap dan harus mengalami paksaan yang tak terelakkan. Semua dibelenggu dengan rantai kegelapan satu itu juga.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 17, 'Semua dikejutkan dan dilumpuhkan boleh jadi oleh angin yang mendesing, atau kicau burung yang merdu di cabang-cabang yang rindang, atau deru air yang deras arusnya, atau deram batu-batu yang berguling ke bawah,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 18, 'ataupun derap tak kelihatan dari binatang-binatang yang melompat-lompat, atau auman binatang-binatang buas yang meraung-raung atau gema yang berkumandang dari celah-celah di pegunungan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 19, 'Sebab seluruh dunia disinari cahaya terang benderang, dan semua sibuk dengan pekerjaannya dengan tidak terhalang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 17, 20, 'Hanya atas musuh-musuh umat-Mu dibentangkan malam yang menekan, suatu lambang kegelapan yang menerima mereka kelak. Namun demikian dirinya sendiri lebih berat bagi mereka dari pada kegelapan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 1, 'Tetapi bagi orang-orang suci-Mu ada cahaya terang. Dan meskipun mereka telah menderita pula, namun dipuji bahagia oleh orang Mesir, ketika mendengar suara mereka tanpa melihat rupanya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 2, 'Mereka berterima kasih, oleh karena orang-orang Israel yang telah diperlakukannya dengan lalim tidak menganiaya mereka, dan minta maaf atas permusuhannya dahulu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 3, 'Akan ganti kegelapan tadi sudah Kauanugerahkan kepada umat-Mu suatu tiang yang bernyalakan api sebagai penunjuk di perjalanan yang tidak diketahui, bagaikan matahari yang tidak mengganggu guna pengungsian yang penuh kemuliaan itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 4, 'Memang orang-orang Mesir patut dicabut cahayanya dan ditawan dalam kegelapan, oleh karena mereka terus mengurung anak-anak-Mu, yang menjadi perantara untuk menyampaikan cahaya baka hukum Taurat-Mu kepada dunia.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 5, 'Karena mereka telah memutuskan untuk membunuh semua anak orang-orang suci-Mu, -- dalam pada itu satu anak yang telah dibuang diselamatkan -- maka sebagai hukuman Engkau merampas banyak anak mereka, dan mereka sendiri serentak Kautumpas dalam air yang bergelora.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 6, 'Malam itu telah diberitahukan lebih dahulu kepada nenek moyang kami, supaya mereka benar-benar insaf akan sumpah yang mereka percayai lalu mendapat hati.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 7, 'Maka umat-Mu mengharapkan baik keselamatan orang benar maupun kebinasaan para musuh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 8, 'Sebab dengan apa telah Kauhukum para lawan, dengan itupun telah Kaumuliakan kami, setelah kami Kaupanggil.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 9, 'Diam-diam anak-anak suci dari orang yang baik mempersembahkan korban dan sehati membebankan kepada dirinya kewajiban ilahi ini: orang-orang suci sama-sama akan mengambil bagian baik dalam hal-hal yang baik maupun dalam bahaya. Dalam pada itu sebelumnya sudah mereka dengungkan lagu-lagu pujian para leluhur.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 10, 'Sebaliknya teriakan janggal dari para musuh bergaung, dan ratap tangis karena anak-anak yang ditangisi tersebar luas.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 11, 'Baik budak maupun tuan dihukum dengan siksa yang sama, dan rakyat jelata menderita sama seperti raja.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 12, 'Karena kematian yang sama maka pada mereka sekalian ada orang mati yang tidak terbilang jumlahnya, dan jumlah orang hidup tidak cukup untuk menguburkannya, sebab dengan satu pukulan keturunan mereka yang termulia ditumpas.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 13, 'Meskipun karena ilmu sihirnya mereka tidak percaya sama sekali, namun karena anak-anak sulungnya yang tewas terpaksa diakuinya, bahwa bangsa inilah sungguh anak Allah.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 14, 'Sebab sementara sunyi senyap meliputi segala sesuatu dan malam dalam peredarannya yang cepat sudah mencapai separuhnya,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 15, 'maka firman-Mu yang mahakuasa laksana pejuang yang garang melompat dari dalam sorga, dari atas takhta kerajaan ke tengah tanah yang celaka. Bagaikan pedang yang tajam dibawanya perintah-Mu yang lurus,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 16, 'dan berdiri tegak diisinya semuanya dengan maut; ia sungguh menjamah langit sambil berdiri di bumi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 17, 'Maka sekonyong-konyong bayangan-bayangan impian yang ngeri sangat menggelisahkan mereka, dan mereka disergap ketakutan yang tidak tersangka-sangka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 18, 'Setengah mati yang satu rebah di sini dan yang lain di sana, sambil menyatakan apa sebabnya maka ia tewas.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 19, 'Sebab sebelumnya sudah ditunjukkan oleh impian yang mengejutkan mereka, agar supaya mereka jangan tewas dengan tidak mengetahuinya, mengapa mereka harus mengalami bencana yang sedemikian itu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 20, 'Ujian mautpun pula datang atas orang benar, dan pembunuhan orang banyak terjadi di gurun, tetapi kemurkaan itu tidak lama berlangsung.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 21, 'Sebab seseorang laki-laki yang tak bercela segera maju sebagai pendekar sambil membawa senjata pelayanannya sendiri, yaitu doa dan korban dupa pengampunan. Ia menahan kemurkaan dan mengakhiri bencana, dan demikian menunjukkan bahwa ia pelayan-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 22, 'Kemurkaan dialahkannya bukan dengan tenaga jasmani, bukan pula dengan daya senjata, melainkan dengan perkataan ditundukkannya penghukum dengan mengingatkan sumpah dan perjanjian dengan nenek moyang.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 23, 'Sebab ketika mayat sudah menggeletak bertimbun-timbun, maka ia berdiri di tengah dan menangkis kemurkaan serta menghalangi jalan menuju orang-orang yang masih hidup.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 24, 'Sebab seluruh jagat raya ada pada jubahnya yang berlabuh sampai ke kaki, dan nama harum leluhur ada pada keempat baris batu-batu dan keagungan-Mu ada pada destarnya.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 18, 25, 'Terhadap itulah mundur pembasmi, kepada itulah ia ketakutan, sebab cukuplah sudah bahwa mereka hanya mencicipi kemurkaan-Mu.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 1, 'Tetapi atas para fasik datanglah kemurkaan yang tak kenal ampun hingga penghabisan, sebab sebelumnya Allah sudah mengetahui kelakuan mereka di waktu mendatang,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 2, 'yaitu: bahwa mereka dahulu mendesak orang-orang Israel untuk berangkat dan menyuruh mereka pergi dengan tergesa-gesa, lalu menyesal dan mengejar mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 3, 'Sebab ketika mereka masih sibuk berkabung, dan meratap pada kubur orang-orang yang sudah mati, maka diambilnya keputusan kebodohan yang lain, lalu mengejar sebagai orang pelarian mereka yang tadinya diminta untuk pergi.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 4, 'Sebab nasib yang sewajarnya menyeret mereka ke arah ajal mereka, dan membuat mereka lupa akan yang sudah-sudah, supaya mereka menggenapkan hukuman yang masih kurang pada siksaannya,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 5, 'dan supaya umat-Mu mencoba menempuh perjalanan yang ajaib, sementara para musuhnya menemui ajal yang ganjil.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 6, 'Sungguh seluruh ciptaan dalam jenisnya dirubah kembali sama sekali oleh karena taat kepada perintah-perintah-Mu, supaya anak-anak-Mu jangan sampai mendapat celaka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 7, 'Maka orang melihat awan membayangi perkemahan, tanah kering muncul di tempat yang tadinya ada air, jalan yang tidak ada rintangannya muncul dari Laut Merah, dan lembah kehijau-hijauan timbul dari empasan ombak yang hebat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 8, 'Di bawah lindungan tangan-Mu seluruh bangsa berjalan lewat di tempat itu, seraya melihat pelbagai tanda yang mentakjubkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 9, 'Seperti kuda ke padang rumput mereka pergi dan melonjak-lonjak bagaikan anak domba, sambil memuji Engkau, ya Tuhan, yang telah menyelamatkan mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 10, 'Sebab mereka masih ingat akan pengalamannya di perantauan, bagaimana akan ganti pembiakan binatang maka bumilah yang mengeluarkan nyamuk, dan akan ganti binatang-binatang air maka sungailah yang memuntahkan kodok banyak sekali.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 11, 'Kemudian mereka melihat pula burung-burung dijadikan dengan cara baru, yaitu ketika terdorong oleh nafsu makan mereka minta hidangan lezat,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 12, 'sebab sebagai pemuas naiklah burung-burung puyuh dari laut.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 13, 'Hukuman tidak datang atas orang berdosa itu tanpa didahului tanda-tanda, yakni mata petir yang hebat. Memang sudah seadilnya mereka menderita karena segala perbuatannya yang jahat, oleh karena menaruh kebencian yang hebat kepada orang asing.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 14, 'Sebab orang Sodom tidak menyambut orang-orang yang tidak dikenal waktu mereka datang, sedangkan orang Mesir memperbudak tamu yang telah berbuat jasa kepada mereka.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 15, 'Dan tidak hanya itu saja -- dan ini tentu akan diperhitungkan bagi mereka --: Orang-orang Sodom segera menyambut orang asing itu dengan permusuhan,', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 16, 'sedangkan orang-orang Mesir dahulu menyambut dengan meriah mereka yang mendapat bagian dalam segala haknya, tapi kemudian menganiaya mereka dengan kerja paksa yang berat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 17, 'Maka mereka tertimpa kebutaan, sama seperti orang Sodom di depan pintu orang benar, yaitu ketika mereka diliputi dengan kegelapan yang kelam pekat, dan masing-masing mencari jalan ke pintunya sendiri.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 18, 'Anasir berubah bercampur-campur, seperti dalam suara-suara kecapi bercampur-campuran nadanya, namun tetap berbunyi. Dengan memandang apa yang telah terjadi maka hal itu dapat ditetapkan dengan teliti.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 19, 'Sebab binatang-binatang darat telah berubah menjadi binatang air, dan binatang-binatang yang berenang naik ke darat.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 20, 'Di dalam air api telah melampaui kekuatannya sendiri dan air lupa sama sekali akan sifatnya untuk memadamkan.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 21, 'Sebaliknya nyala api tidak sampai menghanguskan daging binatang-binatang yang mudah binasa, meskipun berjalan-jalan di dalam api; lagipula api tidak melelehkan santapan sorgawi, yang menyerupai es dan mudah meleleh.', 'id', 'Deutero'),
  ('70', 'keb', 'Kebijaksanaan Salomo', 19, 22, 'Memang dalam segala-galanya, ya Tuhan, telah Kauagungkan dan Kaumuliakan umat-Mu, tidak pernah Kauhina, melainkan selalu dan di mana-mana Kaudampingi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 1, 'Segala kebijaksanaan dari Tuhan asalnya, dan ada pada-Nya selama-lamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 2, 'Pasir di laut dan tetes hujan, dan hari-hari kekekalan siapa gerangan dapat membilangnya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 3, 'Tingginya langit, luasnya bumi, dan samudera raya dan kebijaksanaan, siapa dapat menduganya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 4, 'Sebelum segala-galanya kebijaksanaan sudah diciptakan, dan pengertian yang arif sejak dahulu kala.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 8, 'Kepada siapakah pangkal kebijaksanaan telah disingkapkan, dan siapakah mengenal segala akalnya? Hanyalah Satu yang bijaksana, teramat menggetarkan, yaitu Yang bersemayam di atas singgasana-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 9, 'Tuhanlah yang menciptakan kebijaksanaan, yang melihat serta membilangnya, lalu mencurahkannya atas segala buatan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 10, 'Pada semua makhluk ia ada sekadar pemberian Tuhan, yang juga membagikannya kepada orang yang cinta kepada-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 11, 'Ketakutan akan Tuhan adalah kemuliaan dan kebanggaan, kesukaan dan puncak kegembiraan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 12, 'Ketakutan akan Tuhan menyegarkan hati, memberikan sukacita, keriangan dan umur panjang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 13, 'Orang yang takut akan Tuhan akhirnya mendapat sejahtera, dan pada hari ajalnya dipuji.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 14, 'Awal kebijaksanaan ialah ketakutan akan Tuhan, dan bersama dengan orang setiawan diciptakan dalam kandungan ibu mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 15, 'Laksana dasar abadi ia telah bersarang di tengah-tengah manusia, dan dengan setia tinggal pada keturunan mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 16, 'Takut akan Tuhan adalah kepenuhan kebijaksanaan, yang memabukkan manusia dengan pelbagai buahnya,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 17, 'serta memenuhi seluruh rumah mereka dengan harta benda, dan semua gudang mereka dengan hasilnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 18, 'Puncak kebijaksanaan ialah ketakutan akan Tuhan, dan iapun menumbuhkan kesejahteraan dan kesehatan segar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 19, 'Tuhan telah melihat serta membilang kebijaksanaan, lalu menghujankan pengertian dan pengetahuan yang arif. Kebijaksanaan mempertinggi kemuliaan semua orang yang memilikinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 20, 'Pangkal kebijaksanaan ialah ketakutan akan Tuhan, dan ranting-rantingnya adalah umur yang panjang. Kesabaran dan kejujuran', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 22, 'Amarah yang tak adil tidak dapat dibenarkan, sebab keterlaluan amarah menjadi keruntuhan manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 23, 'Orang yang sabar bertahan sampai pada waktu tepat, kemudian akan terbit sukacita baginya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 24, 'Sampai pada waktu tepat ia menyembunyikan perkataannya, tetapi kemudian banyak orang akan mewartakan kearifannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 25, 'Perbendaharaan kebijaksanaan berisi amsal penuh pengetahuan, tetapi orang berdosa menganggap sepi kesalehan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 26, 'Jika kebijaksanaan kauinginkan maka perhatikan perintah, lalu Tuhan akan menganugerah-kannya kepadamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 27, 'Sebab kebijaksariaan dan pengajaran adalah ketakutan akan Tuhan, dan Allah berkenan pada kesetiaan dan hati lembut.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 28, 'Jangan keras kepala terhadap ketakutan akan Tuhan, dan jangan mendekatinya dengan mendua hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 29, 'Jangan menjadi orang munafik di depan orang, dan jagalah selalu bibirmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 1, 30, 'Jangan meninggikan dirimu, agar jangan kau jatuh, dan jangan mendatangkan malu bagi dirimu sendiri. Sebab Tuhan akan membuka segala rahasiamu, dan menurunkan dikau di tengah-tengah himpunan rakyat, karena engkau tidak mengusaha-kan ketakutan akan Tuhan dan hatimu penuh tipu daya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 1, 'Anakku, jikalau engkau bersiap untuk mengabdi kepada Tuhan, maka bersedialah untuk pencobaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 2, 'Hendaklah hatimu tabah dan jadi teguh, dan jangan gelisah pada waktu yang malang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 3, 'Berpautlah kepada Tuhan, jangan murtad dari pada-Nya, supaya engkau dijunjung tinggi pada akhir hidupmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 4, 'Segala-galanya yang menimpa dirimu terimalah saja, dan hendaklah sabar dalam segala perubahan kehinaanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 5, 'Sebab emas diuji di dalam api, tetapi orang yang kepadanya Tuhan berkenan dalam kancah penghinaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 6, 'Percayalah pada Tuhan maka lapun menghiraukan dikau, ratakanlah jalanmu dan berharaplah kepada-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 7, 'Kamu yang takut akan Tuhan nantikanlah belas kasihan-Nya, jangan menyimpang, supaya kamu jangan terjatuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 8, 'Kamu yang takut akan Tuhan percayalah pada-Nya, niscaya kamu tidak akan kehilangan ganjaranmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 9, 'Kamu yang takut akan Tuhan harapkanlah yang baik, sukacita kekal dan belas kasihan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 10, 'Pandanglah segala angkatan yang sudah-sudah dan perhatikanlah: Siapa gerangan percaya pada Tuhan lalu dikecewakan, siapa bertekun dalam ketakutan kepada-Nya dan telah ditinggalkan, atau siapa berseru kepada-Nya lalu tidak dihiraukan oleh-Nya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 11, 'Memang Tuhan adalah penyayang dan pengasih, la mengampuni dosa dan menyelamatkan pada saat kemalangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 12, 'Celakalah, hati yang tawar dan tangan kendor, dan orang berdosa yang jalannya mendua.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 13, 'Celakalah, hati yang lembek karena tidak percaya. Karena itulah ia tidak mendapat perlindungan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 14, 'Celakalah, kamu yang kehilangan ketabahan hati. Apakah yang hendak kamu perbuat apabila Tuhan mencobai?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 15, 'Yang takut akan Tuhan taat kepada firman-Nya, dan yang mengasihi Dia mengikuti segala jalan yang ditunjukkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 16, 'Yang takut akan Tuhan mencari perkenanan-Nya, dan yang mengasihi Dia mengenyangkan diri dengan Taurat-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 17, 'Mereka yang takut akan Tuhan terus mempersediakan hatinya serta merendahkan diri di hadapan-Nya:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 2, 18, '"Biarlah kami jatuh ke dalam tangan Tuhan, tetapi jangan ke dalam tangan manusia! Sebab sama seperti keagungan-Nya demikianpun belas kasihan-Nya!"', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 1, 'Anakku, jangan enggan memberikan nafkah kepada orang miskin, dan jangan membuat orang papa rindu dendam.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 2, 'Orang yang kelaparan jangan kausedihkan, dan janganlah memahitkan hati orang yang kekurangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 3, 'Jangan keras terhadap orang yang pahit hatinya, dan jangan kautunda sedekah orang yang kekurangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 4, 'Jangan kautolak permohonan orang yang susah dan jangan membelokkan wajahmu dari orang miskin.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 5, 'Dari yang kekurangan jangan palingkan matamu, jangan memberi orang alasan untuk mengutuk dirimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 6, 'Bila engkau dikutuk seseorang dalam duka nestapanya, niscaya permohonannya didengarkan oleh Penciptanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 7, 'Buatlah dirimu disayangi oleh umat, dan rendahkanlah dirimu di depan pembesar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 8, 'Condongkanlah telinga kepada yang miskin, dan dengan ramah balaslah salamnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 9, 'Selamatkanlah orang tertindas dari tangan penindasnya, dan jangan segan memberi keputusanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 10, 'Jadilah seperti seorang bapa bagi yatim piatu, dan sebagai suami bagi ibu mereka. Maka engkau laksana anak dari Yang Mahatinggi, lalu engkau akan dikasihi olehNya lebih dari pada oleh ibumu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 11, 'Kebijaksanaan meninggikan segala anaknya, dan orang yang mencarinya dihiraukannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 12, 'Siapa yang mencintai kebijaksanaan mencintai kehidupan, dan barangsiapa pagi- pagi menghadapinya akan penuh sukacita.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 13, 'Siapa yang berpaut padanya mewarisi kemuliaan, dan ia diberkati Tuhan di manapun ia berlangkah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 14, 'Barangsiapa melayani kebijaksanaan bergilir bakti kepada Yang Kudus, dan siapa mencintainya dicintai oleh Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 15, 'Siapa mendengarkannya akan memutuskan yang adil, dan aman sentosalah kediaman orang yang mengindahkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 16, 'Jika orang percaya pada kebijaksanaan, niscaya ia mewarisinya, dan keturunannya akan tetap memilikinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 17, 'Boleh jadi ia dituntun kebijaksanaan di jalan yang berbelok- belok dahulu, sehingga didatangi ketakutan dan getaran; boleh jadi kebijaksanaan menyiksa dia dengan siasat sampai dapat percaya padanya, dan mengujinya dengan segala aturannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 18, 'Tetapi kemudian kebijaksanaan kembali kepadanya dengan kebaikan yang menggembirakan, dan menyingkapkan kepadanya pelbagai rahasia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 19, 'Jika orang sampai menyimpang, maka dibuang oleh kebijaksanaan dan diserahkan kepada kebinasaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 20, 'Perhatikanlah waktu tepat dan jagailah dirimu terhadap yang jahat, maka tak perlu engkau malu kelak karena dirimu sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 21, 'Sebab ada malu yang mendatangkan dosa, tetapi juga ada malu yang merupakan kemuliaan dan kasih karunia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 22, 'Jangan pandang orang, sehingga engkau sendiri kerugian, dan jangan segani orang, sehingga menjadi keruntuhanmu sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 23, 'Jangan menahan perkataan apabila dapat menyelamatkan, kebijaksanaanmu jangan kausembunyikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 24, 'Sebab kebijaksanaan dikenal dalam bicara, dan pengajaran ternyata dari ucapan lidah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 25, 'Kebenaran jangan kautentang, tetapi hendaklah malu karena kebodohanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 26, 'Jangan malu- malu mengaku dosamu, dan arus sungai jangan kaulawan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 27, 'Jangan menyerahkan dirimu kepada orang bodoh, pun pula jangan memihak kepada orang yang berkuasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 28, 'Berjuanglah mati- matian untuk kebenaran, maka Tuhan Allah akan berperang untukmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 29, 'Jangan berani dengan lidahmu, sedangkan malas dan segan dalam perbuatanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 30, 'Jangan bagaikan singa dirumahmu, dan dahsyat di tengah- tengah isi rumahmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 4, 31, 'Tanganmu jangan terulur untuk menerima, dan untuk mengembalikan jangan terkatup.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 1, 'Jangan mengandalkan kekayaanmu, dan jangan berkata: "Ini cukup bagiku."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 2, 'Hati dan kekuatanmu jangan kauturut untuk berlaku sesuai dengan hawa nafsu hatimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 3, 'Jangan berkata: "Siapa berkuasa atas diriku?" Memang Tuhan akan menghukum engkau dengan keras.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 4, 'Jangan berkata: "Betul, aku sudah berdosa, tetapi apakah menimpa diriku? Sebab Tuhan panjang hati."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 5, 'Jangan menyangka pengampunan terjamin, sehingga engkau menimbun dosa demi dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 6, 'Jangan berkata: "Memang belas kasihan-Nya besar, dosaku yang banyak ini pasti diampuni-Nya." Sebab baik belas kasihan rnaupun kemurkaan ada pada Tuhan, dan geram-Nya turun atas orang jahat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 7, 'Jangan menunda-nunda berbalik kepada Tuhan, jangan kautangguhkan dari hari ke hari. kemurkaan Tuhan, dan pada saat hukuman engkau dihancurkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 8, 'Jangan percaya pada harta benda yang diperoleh dengan tidak adil, sebab tidak berguna sedikitpun pada hari sial.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 9, 'Jangan menjadi orang yang menampi pada setiap angin, dan jangan berjalan di lorong sembarangan; demikianlah kelafcuan orang berdosa yang bercabang lidahnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 10, 'Hendaklah tetap pada anggapamhu, dan selalu sama hendaknya: perkataanmu', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 11, 'Hendaklah cepat mendengarkan, tetapi laun mengucapkan jawabannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 12, 'Jika engkau tahu, hendaklah menjawab sesamamu, jika tidak, taruhlah tangan pada mulutmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 13, 'Hormat dan malu dalam bicara letaknya, dan lidah manusia menjadi keruntuhannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 14, 'Jangan engkau sampai disebut pengumpat, dan jangan mengadang dengan lidahmu. Sebab nista turun atas pencuri, tetapi hukuman keras atas yang bercabang lidahnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 5, 15, 'Dalam hal kecil tnaupun besar janganlah bodoh, dan jangan dari sahabat menjadi musuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 1, 'Nama buruk mewariskan malu dan nista, dan demikianpun orang berdosa yang bercabang lidahnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 2, 'Jangan meninggikan dirimu dengan keinginan hati, supaya engkau jangan dikerkah laksana lembu jantan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 3, 'Daun-daunanmu akan kautelan dan buah-buahanmu akan kaubinasakan, lalu kau ditinggalkan bagaikan pohon kering.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 4, 'Memang hawa nafsu yang jahat menghancurkan pemiliknya, dan menjadikannya tertawaan musuhnya. Tentang persahabatan', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 5, 'Tenggorokan yang manis mendapat banyak sahabat, dan keramahan diperbanyak oleh lidah yang manis lembut.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 6, 'Mudah-mudahan orang yang damai denganmu banyak adanya, tetapi hanya satu dari seribu hendakriya menjadi penasehatmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 7, 'Jika engkau mau mendapat sahabat, kajilah dia dahulu, dan jangan segera percaya padanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 8, 'Sebab ada orang yang bersahabat hanya menurut ketikanya sendiri, tetapi pada hari kesukaranmu tidak bertahan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 9, 'Ada juga sahabat yang berubah menjadi musuh, lalu menceritakan persengketaan untuk menistakan dikau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 10, 'Ada lagi sahabat yang ikut serta dalam perjamuan makan, tapi tidak bertahan pada hari kesukaranmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 11, 'Pada waktu engkau sejahtera ia adalah seperti engkau sendiri dan lancang berbicara dengan seisi rumahmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 12, 'Tetapi bila engkau mundur maka ia berbalik melawan dikau serta menyembunyikan diri terhadapmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 13, 'Jauhkanlah diri dari para musuhmu, tetapi berhati-hatilah terhadap para sahabatmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 14, 'Sahabat setiawari merupakan perlindungan yang kokoh, barangsiapa menemukan orang serupa itu sungguh mendapat harta.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 15, 'Sahabat setiawan tiada ternilai, dan harganya tidak ada tertimbang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 16, 'Sahabat setiawan adalah obat kehidupan, orang yang takut akan Tuhan memperolehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 17, 'Orang yang takut akan Tuhan memelihara persahabatan dengan lurus hati, sebab seperti ia sendiri demikianpun temannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 18, 'Anakku, sejak rnasa mudamu hendaklah memilih pelajaran, maka kebijaksanaanlah yang akan kaudapat hingga masa tuamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 19, 'Hendaklah mendekatinya baik sebagai pembajak maupun sebagai penuai, dan nantikanlah buahnya yang baik. Sebab dalam mengolah engkau mesti berjerih payah sejurus saja, lalu segera dapat menikmati hasilnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 20, 'Amat kasar sekalilah kebijaksanaan bagi yang tak berpendidikan, dan orang bebal tak dapat bertahan padanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 21, 'Bagi dia kebijaksanaan beratlah rasanya seperti batu uji, dan ia tak segan-segan membuangkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 22, 'Sebab kebijaksanaan sepadan dengan namanya, dan tidak terbuka bagi banyak orang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 23, 'Dengarkanlah, hai anakku dan terimalah pengertianku, dan nasehatku jangan kauabaikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 24, 'Masukkanlah kakimu ke dalam sengkela kebijaksanaan, dan lehermu ke dalam pasungnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 25, 'Tundukkanlah bahumu dan hendaklah ia kaupikul, dan janganlah marah karena ikatan-ikatannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 27, 'Selidiki dan carilah, niscaya ia akan menampakkan diri kepadamu, dan setelah kaupegang jangan kaulepaskan lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 28, 'Engkau akan mendapat istirahat padanya akhirnya, dan ia akan berubah menjadi sukacita bagimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 29, 'Maka sengkelanya akan menjadi suatu benteng kokoh kuat bagimu, dan pasungannya suatu baju kebesaran.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 30, 'Kuknya merupakan perhiasan emas, dan pengikat-pengikatnya adalah pita ungu tua.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 31, 'Laksana baju kebesaran akan kaukenakan, dan kaupasang bagaikan karangan kegembiraan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 32, 'Jika engkau mau, hai anakku, niscaya engkau akan diajar, dan kalau menaruh perhatian, maka engkau menjadi arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 33, 'Jika engkau rela mendengarkan, maka engkau akan belajar, dan kalau kaucondongkan telinga pasti menjadi bjjaksana.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 34, 'Hendaklah berada di kalangan kaum tua-tua. Bijakkah seseorang? Hendaklah melekat kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 35, 'Hendaklah suka mendengarkan tiap-tiap ajaran yang dari Allah asalnya, dan jangan terluput dari padamu satupun amsal yang arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 36, 'Jika engkau melihat seseorang yang bijak, hendaklah pagi-pagi mendapatkannya, dan biar kakimu mengauskan ambang pintunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 6, 37, 'Renungkanlah segala perintah Tuhan, dan hendaklah selalu memikirkan hukum-Nya. Maka la akan memperkuat hatimu, dan menganugerahkan kebijaksanaan yang kauinginkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 1, 'Jangan berbuat jahat, maka yang jahat takkan menimpa dirimu,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 2, 'jauhilah durjana, niscaya engkaupun akan dihindarkannya pula.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 3, 'Anakku, janganlah menabur dalam alur-alur kedurjanaan, supaya engkau jangan memungut tujuh lipat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 4, 'Jangan mengharapkan dari Tuhan pangkat tertinggi, jangan pula tempat terhormat dari raja.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 5, 'Jangan bennuka-muka benar di hadapan Tuhan, dan jangan main arif di depan raja.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 6, 'Menjadi seorang hakim jangan kauinginkan, mungkin engkau tidak cukup berdaya untuk memberantas kelaliman, Mungkin pula engkau takut terhadap orang yang berkuasa, lalu menodai kelurusanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 7, 'Jangan berdosa terhadap orang banyak di kota, supaya jangan menurunkan dirimu sendiri di tengah rakyat. Pedoman bagi kelakuan terhadap Allah dan sesama', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 8, 'Jangan engkau tersangkut dosa sampai dua kali, malahan pertama kalinya engkau tidak terluput.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 9, 'Jangan berpikir: "Banyaknya persajianku akan dipandang Allah dengan rela, dan jika kupersembahkan kepada Yang Mahatinggi, niscaya diterima-Nya."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 10, 'Jangan kecil hati dalam sembahyang, dan berderma jangan kauabaikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 11, 'Orang celaka jangan kauejek-ejek, sebab adalah Satu yang merendahkan dan meninggikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 12, 'Jangan merencanakan dusta terhadap saudaramu, jangan pula terhadap sahabatmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 13, 'Berjagalah agar jangan sampai mengucapkan dusta apapun, sebab tak mungkin dari padanya berasal sesuatupun yang baik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 14, 'Jangan bermulut besar dalam himpunan kaum tua-tua, dan jangan pula mengulang-ulang perkataan dalam sembahyang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 15, 'Jangan benci kepada pekerjaan yang melelahkan, atau kepada kerja di perladangan, yang ditentukan Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 16, 'Jangan membilang dirimu di antara banyaknya orang berdosa, ingatlah akan kemurkaan yang tidak berayal-ayalan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 17, 'Rendahkanlah dirimu dengan amat sangatnya, sebab hukuman kaum fasik ialah api dan ulat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 18, 'Jangan menukar sahabat dengan uang, atau saudara sejati dengan emas dari Ofir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 19, 'Isteri yang bijak dan baik jangan kauabaikan, sebab harga keramahannya melampaui harga emas. 20 Janganlah kauaniaya seorang budak yang bekerja dengan setia, atau buruh upahan yang menyerahkan segenap tenaganya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 21, 'Budak yang arif hendaklah kaukasihi, jangan enggan memberikan kemerdekaan kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 22, 'Adakah engkau mempunyai ternak? Hendaklah kauperhatikan, dan jika berguna, hendaknya tetap tinggal padamu juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 23, 'Adakah engkau mempunyai anak? Hendaklah kaudidik, tundukkanlah kuduknya sejak masa mudanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 24, 'Adakah engkau mempunyai anak-anak perempuan? Lindungilah tubuhnya, dan jangan menunjukkan muka ramah kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 25, 'Persuamikanlah anak perempuanmu, maka perkara berat telah kauselesaikan, tetapi kawinkanlah mereka kepada laki-laki yang arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 26, 'Jika engkau mempunyai isteri sesuai dengan keinginanmu, jangan kauceraikan, tetapi jika tidak kaukasihi maka jangan mempercayakan dirimu kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 27, 'Hormatilah bapamu dengan segenap hati, dan sakit beranak ibumu jangan kaulupakan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 28, 'Ingatlah bahwa engkau adalah anak mereka. Bagaimana gerangan engkau dapat membalas budi atas apa yang mereka perbuat bagimu?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 29, 'Hendaklah bertakwa dengan: segenap jiwamu, dan junjunglah tinggi para imam Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 30, 'Kasihilah Penciptamu dengan segala kekuatanmu, dan para pelayan-Nya jangan kauabaikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 31, 'Takutilah Tuhan dan hormatilah para imam, dan bayarlah hagian mereka seperti yang menjadi kewajibanmu: buah bungaran, korban penebus salah dan bahu binatang korban, korban pengudus serta bagian pertama dari barang kudus.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 32, 'Ulurkanlah tanganmu kepada orangmiskin, agar berkatmu sempurna adanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 33, 'Hendaklah kemurahan hatimu meliputi semua orang yang hidup, tapi orang matipun jangan kaukecualikan pula dari kerelaanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 34, 'Jangan menjauhi orang yang menangis, dan hendaklah berdukacita dengan yang berdukacita.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 35, 'Jangan segan menengok orang sakit, sebab karenanya engkau akan dikasihi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 7, 36, 'Dalam segala urusanmu ingatlah akan akhir hidupmu, maka tak pernah engkau akan berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 1, 'Jangan berjuang melawan orang yang berkuasa, agar engkau jangan jatuh ke dalam genggamannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 2, 'Jangan bersengketa dengan orang kaya, supaya ia jangan menghadapkan segenap kemampuannya kepadamu. Sebab banyak orang telah dibinasakan emas, dan hati raja-raja telah diselewengkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 3, 'Jangan bertengkar dengan seorang pembual, janganlah menaruh kayu hakar di atas api.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 4, 'Dengan orang yang tidak terdidik jangan bersenda gurau, agar nenek moyangrnu jangan sampai dihina.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 5, 'Janganlah menegur orang yang bertobat dari dosanya, ingatlah bahwa kita sekalian patut dihukum.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 6, 'Orang yang sudah lanjut umurnya jangan kaucaci maki, sebab dari antara kitapun ada yang menjadi ubanan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 7, 'Jangan bergembira karena seseorang yang mati, ingatlah bahwa kita sekalian nanti akan mati juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 8, 'Jangan anggap remeh petunjuk orang bijaksana, sebaliknya serahkanlah dirimu. kepada amsalnya. Demikian engkau mendapat didikan serta belajar bagaimana engkau mesti mengabdi kepada para penguasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 9, 'Tuturan orang tua-tua jangan kauabaikan, sebab merekapun berguru pula kepada nenek moyangnya. Dari pada mereka engkau akan memperoleh pengertian, dan bagaimana engkau mesti menjawab pada waktu tepat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 10, 'Arang orang berdosa jangan kaunyalakan, agar engkau jangan sampai terbakar oleh nyala apinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 11, 'Janganlah mundur terhadap orang yang pongah, nanti menjadi bagaikan pengadangan bagi mulutmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 12, 'Jangan meminjamkan kepada orang yang lebih kuat dari padamu, jika engkau telah meminjamkan, maka pandanglah pinjamanmu itu sebagai barang yang hilang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 13, 'Jangan menjadi penanggung melebihi kemampuanmu, dan jika sudah terjadi, anggaplah dirimu wajib membayar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 14, 'Jangan berperkara dengan hakim, niscaya keputusan dijatuhkan untuk menguntungkan dia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 15, 'Jangan berjalan dengan georang pemberani, nanti ia menjadi beban bagimu; sebab sekehendak hatinya ia bertindak, dan engkau binasa oleh karena kepandirannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 16, 'Jangan beradu dengan orang yang panas hati, jangan pergi bersama dengannya melalui padang gurun, sebab menumpahkan darah dianggapnya perkara kecil saja, dan di tempat tidak ada pertolongan engkau akan ditewaskannya. n Dengan orang bodoh jangan berunding, sebab perkara itu tidak dapat dirahasiakannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 18, 'Apa yang mesti dirahasiakan jangan kaulakukan di depan orang luar, sebab engkau tak tahu apa yang akan disiarkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 8, 19, 'Jangan membuka hatimu kepada orang sembarangan, dan jangan membiarkan engkau direlainya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 1, 'Jangan cemburu kepada isterimu sendiri, agarjangan kauajarkan kepadanya berbuat jahat terhadapmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 2, 'Kepada seorang perempuan jangan kauserahkan dirimu, nanti engkau dikepalai olehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 3, 'Jangan pergi kepada perempuan jalang, nanti engkau tertangkap dalam perangkapnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 4, 'Jangan bergaul dengan biduanita, supaya engkau jangan tertawan oleh ketarigkasannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 5, 'Kepada seorang gadis jangan kautaruh perhatianmu, nanti engkau kena hukuman bersama dengannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 6, 'Jangan menyerahkan dirimu kepada pelacur, supaya engkau jangan kehilangan milik pusakamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 7, 'Jangan kaulayangkan pandanganmu keliling di jalan-jalan di kota, jangan pula mengembara di tempat-tempatnya yang sunyi sepi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 8, 'Dari pada perempuan yang cantik palingkanlah pandanganmu, jangan memandang keelokan yang bukan kepuriyaanmu. Banyak yang sudah disesatkan keelokan perempuan, dan syahwat dinyalakannya bagaikan api.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 9, 'Jangan duduk-duduk bersama isteri seseorang, dan jangan semeja dengannya di dalam pesta air anggur, supaya hatimu jangan terpikat kepadanya, lalu engkau diseret nafsumu ke kebinasaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 10, 'Sahabat lama jangan kautinggalkan; niscaya yang baru tidak sebanding dengannya. Sahabat baru serupa dengan air anggur yang baru, setelah menjadi tua dapat kauminum dengan senang hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 11, 'Jangan iri hati kepada hasil orang berdosa, sebab tidak kauketahui bagaimana akhimya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 12, 'Jangan bersenang hati atas kesenangan kaum fasik, ingatlah bahwa ia tak akan terluput hingga masuk dunia orang mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 13, 'Jauhilah orang yang berkuasa untuk membunuh, maka engkau tak akan dikejutkan oleh ketakutan akan mati. Namun jika engkau mendekatinya, jangan berbuat salah apapun juga, agar ia jangan mencabut nyawamu. Insafilah bahwa engkau melangkah di tengah-tengah perangkap perangkap serta berjalan di atas tembok kota.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 14, 'Indahkanlah sesamamu sedapat-dapatnya, dan hendaklah berunding dengan orang bijak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 15, 'Pembicaraanmu hendaknya dengan orang arif, dan percakapanmu mesti mengenai hukum Taurat dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 16, 'Orang jujur hendaknya menjadi teman makan, dan ketakutan akan Tuhan hendaknya kebanggaanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 17, 'Buatan patut dipuji karena tangan para tukangnya, tapi seorang penguasa rakyat yang bijak mesti dipuji karena bicaranya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 9, 18, 'Seorang pembual ditakuti oleh kaum sekotanya, dan si nyinyir dinistakan karena obrolannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 1, 'Pemerintah yang bijak Avf mempertahankan ketertiban pada rakyatnya, dan pemerintahan orang arif adalah teratur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 2, 'Seperti penguasa bangsa demikianpun para pegawainya, dan seperti pemerintah kota demikian pula semua penduduknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 3, 'Raja yang tidak terdidik membinasakan rakyatnya, tetapi sebuah kota sejahtera berkat kearifan para pembesarnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 4, 'Di dalam tangan Tuhan terletak kuasa atas bumi, an pada waktunya la mengangkat orang yang serasi atasnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 5, 'Di dalam tangan Tiihanlah terletak kemujuran seorang manusia, dan kepada para pejabat dikaruniakan oleh-Nya martabatnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 6, 'Hendaklah engkau tidak pernah menaruh benci kepada sesamamu apapun juga kesalahannya, dan jangan berbuat apa-apa terpengaruh oleh nafsu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 7, 'Kecongkakan dibenci oleh Tuhan maupun oleh manusia, dan bagi kedua-duanya kelaliman adalah salah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 8, 'Pemerintahan beralih dari bangsa yang satu kepada bangsa yang lain akibat kelaliman, kekerasan dan uang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 9, 'Mengapa congkak, engkau yang hanya debu dan abu, yang isi perutnya sudah memualkan selagi hidup?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 10, 'Penyakit keras mengejek-ejek tabib, hari ini masih raja dan besok sudah mati!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 11, 'Apabila manusia mati maka nasibnya begini: ulat, binatang buas dan cacing.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 12, 'Permulaan kecongkakan ialah meninggalkan Tuhan serta menjauhkan hati dari pada Penciptanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 13, 'Sebab permulaan kecongkakan ialah dosa, dan siapa yang menyerahkan diri kepadanya menghamburkan kekejian. Itulah sebabnya maka Tuhan menyiksanya dengan hukuman-hukuman ajaib, dan meruntuhkan mereka sampai binasa seluruhnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 14, 'Tuhan menggulingkan takhta orang kuasa, dan menempatkan orang rendah hati ganti mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 15, 'Akar pelbagai bangsa dicabut oleh Tuhan, dan orang-orang rendah ditanam-Nya ganti mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 16, 'Tuhan menjungkirbalikkan daerah pelbagai bangsa serta membasmi mereka sampai dasar-dasar bumi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 17, 'Beberapa di antaranya ditinggikan-Nya dahulu lalu dibasmi-Nya, dan kenangan akan mereka. dilenyapkan-Nya dari muka bumi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 18, 'Kecongkakan tidak patut bagi manusia, dan geram yang hebat tidak serasi dengan yang lahir dari perempuan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 19, 'Manakah bangsa yang mesti dihormati? Bangsa manusia. Manakah bangsa yang mesti dihormati? Orang yang takut akan Tuhan. Manakah bangsa yang mesti dicela? Bangsa manusia. Manakah bangsa yang mesti dicela? Yang melanggar hukum;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 20, 'Si penguasa dihormati di kalangan saudaranya, tetapi orang yang takut akan Tuhan dihormati di hadapan Allah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 22, 'Orang yang kaya, yang terhormat dan yang miskin, kebanggaan mereka semua ialah ketakutan akan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 23, 'Tidak bolehlah orang miskin yang arif dihina, dan orang berdosa tak patut dihormati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 24, 'Pemuka, hakim dan yang kuasa dihormati, namun demikian di antaranya tidak ada seorangpun yang lebih besar dari pada takut akan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 25, 'Orang-orang merdeka mengabdi kepada budak yang bijaksana, dan orang berilmu tidak mengeluh karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 26, 'Jangan main orang cerdik dalam melakukan pekerjaanmu, jangan pula berlagak orang besar pada waktu engkau kekurangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 27, 'Lebih baiklah prang yang bekerja dan berlimpah-limpah segala macam barangnya dari pada orang yang berlagak orang besar tapi kekurangan makanan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 28, 'Anakku, hendaklah engkau berbangga tapi dengan rendah hati, hargailah dirimu sesuai dengan nilaimu sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 29, 'Siapa gerangan akan membenarkan orang yang berbuat dosa terhadap dirinya sendiri, dan siapa menghonnati orang yang menistakan dirinya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 30, 'Orang miskin dihormati karena pengetahuannya, tapi orang kaya dihormati karena kekayaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 10, 31, 'Kalau orang sudah dihormati dalam kemiskinannya, apa lagi dalam kekayaannya, kalau orang sudah dihina dalam kekayaannya, apa lagi dalam kemiskinannya!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 1, 'Kebijaksanaan orang yang hina menegakkan kepalanya serta memberi dia tempat di tengah-tengah orang besar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 2, 'Jahgan memuji nianusia karena keelokahnya, dan jangan eriggan terhadap seorangpun karena rupanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 3, 'Yang terkecil di antara segala binatang bersayap ialah si lebah, tetapi apa yang dihasilkannya adalah kemuncak kemanisan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 4, 'Jangan membanggakan pakaian yang kaupakai, jangan pula bermegah-megah pada saat engkau dihormati. Sebab pekerjaan Tuhan adalah ajaib dan tersembunyi bagi manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 5, 'Banyak raja mesti dudukdi lantai, sedangkan yang tak dikirakan orang, telah bermahkota.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 6, 'Banyak orang kuasa sudah menjadi amat terhina, dan orang terhormat telah diserahkan ke dalam tangan orang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 7, 'Jangan meneela sebelum kauselidiki, setelah berpikir dahulu barulah menegur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 8, 'Jangan menjawab sebelum kaudengarkan, dan jangan menyela pembicaraan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 9, 'Tentang perkara yang dengannya engkau tak bersangkutan jangan bertikai, dan jangan mencampuri sengketa orang berdosa. Percayalah pada Tuhan semata-mata', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 10, 'Anakku, jangan sibuk dengan banyak urusan, jika kauperbanyak, niscaya tak terluputlah engkau dari rugi. Meskipun engkau berkejar-kejar, namun tidak kau sampai juga, dan dengan laripun engkau tak dapat lepas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 11, 'Ada orang yang bersusah payah, berjerih lelah dan berburu-buru, namun semakin kekurangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 12, 'Ada juga orang yang berlambat, yang minta-minta tolong, yang kurang kuat dan miskin sekali, tetapi dengan rela dipandang Tuhan serta diangkat dari kemalangannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 13, 'Tuhan menegakkan kepala orang itu, sehingga banyak orang tercengang karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 14, 'Baik dan buruk, mati dan hidup, kemiskinan dan kekayaan berasal dari Tuhan semua.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 15, 'Untuk sementara waktu musuh akan tinggal sertamu,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 16, 'Seorang musuh manis dengan bibirnya, tetapi dalam hati merencanakan bagaimana ia dapat menjatuhkan dirimu ke dalam lobang,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 17, 'Anugerah Tuhan tetap ada pada orang bertakwa, dan perkenanan-Nya selalu menyertai mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 18, 'Ada orang yang menjadi kaya karena cermat lagi hemat, namun demikian bagian ganjarannya begini:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 19, 'Pada saat ia berkata: "Kini aku telah mendapat istirahat, sekarang hendak kunikmati harta milikku," maka tidak tahulah ia berapa lamakah akan berlangsung, hingga terpaksa ia meninggalkan semuanya kepada orang lain lalu mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 20, 'Hendaklah tetap berpegang kepada jabatanmu serta menunaikannya, jadilah tua dalam pekerjaanmu itu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 21, 'Karena segala pekerjaan orang berdosa jangan keheran-heranan, percayalah pada Tuhan dan hendaklah tekun berjerih lelah. Sebab dalam pandangan Tuhan mudah sekali dalam sekejap mata tiba-tiba membuat orang miskin menjadi kaya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 22, 'Berkat Allah menjadi ganjaran orang bertakwa, dan dalam sekelip mata Tuhan membuat berkat-Nya berkembang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 23, 'Jangan berkata: "Apakah masih kubutuhkan, apakah kepunyaanku kelak?"', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 24, 'Jangan berkata: "Aku sudah kecukupan, bencana manakah masih dapat menimpa diriku nanti?"', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 25, 'Memang pada masa sejahtera orang lupa akan kemalangan, dan pada masa kemalangan orang tidak ingat akan kesejahteraan dahulu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 26, 'Tentu mudah bagi Tnhan pada hari terakhir membalas manusia sekedar tingkah lakunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 27, 'Sejam kemalangan membuat orang lupa akan kemewahannya, dan pada akhir hidup manusia disingkapkanlah segala pekerjaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 28, 'Jangan memuji seseorang bahagia sebelum ia mati, sebab manusia dikenal dalam anak-anaknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 29, 'Jangan membawa setiap orang masuk ke rumahmu, sebab orang cerdik ada banyak tipu muslihatnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 30, 'Seperti ayam hutan pemikat dalam kurungnya, demikianlah hati orang congkak, seperti mata-mata ia mengintip keruntuhanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 31, 'Seorang pemfitnah memutarbalikkan bahkan yang baik menjadi jahat, dan malahan sifat-sifat terbaik dicela olehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 32, 'Satu bunga api saja menyalakan arang, dan orang berdosa mengadang untuk menumpahkan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 33, 'Berawas-awaslah terhadap orang jahat, sebab yang buruk direncanakannya hendak menodai engkau selama-lamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 11, 34, 'Jika engkau menjamu orang asing, maka ia mengusutkan dirimu serta mengasingkan dikau dan seisi rumahmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 1, 'Jika engkau berbuat baik, hendaklah memperhatikan kepada siapakah kauperbuat, maka engkau mendapat balas budi karena perbuatanmu yang baik', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 2, 'Hendaklah berbuat baik kepada orang bertakwa, niscaya engkau mendapat balasan, kalaupun tidak dari pada dia sendiri, pasti dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 3, 'Tidak ada sesuatupun yang baik bagi orang yang tekun dalam kejahatan, ataupun bagi yang tidak bersedekah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 4, 'Berikanlah kepada orang bertakwa, tapi jangan menolong orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 5, 'Hendaklah berbuat baik kepada orang yang rendah hati, tapi jangan memberikan kepada orang fasik; rotinya hendaklah kautolak kepadanya, jangan kauberi, supaya karena itu ia jangan menjadi lebih kuat dari padamu. Sebab dua lipat engkau akan mendapat kejahatan pengganti semua kebaikan yang kauperbuat kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 6, 'Memang juga Yang Mahatinggi sendiri benci kepada orang berdosa, dan kepada kaum fasik ditimpakan-Nya hukuman.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 7, 'Jadi berikanlah kepada orang yang baik, tapi jangan menolong orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 8, 'Di masa kesejahteraan orang tak sampai mengenal sahabat, dan di masa kemalangan musuh tak tersembunyi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 9, 'Waktu seseorang sejahtera para musuhnya sakit hati, tetapi waktu kemalangan bahkan sahabatpun mengundurkan diri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 10, 'Jangan pernah menaruh percaya pada musuh, sebab sama seperti tembaga berkarat keburukannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 11, 'Pun kalau ia merendahkan diri dan membungkuk jalannya, awaslah terhadapnya dan hendaklah waspada. Hendaklah berlaku terhadapnya seperti penggosok certain, ingatlah karatnya tidak akan bertahan hingga akhir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 12, 'Musuh jangan kautempatkan di sampingmu, nanti engkau sendiri digeser dan ia menduduki tempatmu; jangan ia kaubiarkan duduk di sisi kananmu, nanti ia mencoba merebut tempat dudukmu Maka akhirnya engkau akan memahami perkataanku serta menyesal sambil teringat kepada nasehatku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 13, 'Siapa gerangan menarah kasihan kepada tukang ular yang dipagut atau kepada orang yang mendekati binatang buas?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 14, 'Demikian halnya orang yang menjadi teman orang berdosa, dan terlibat dalam dosa-dosanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 15, 'Untuk sementara waktu musuh akan tinggal sertamu, tapi apabila engkau goyah, ia tidak bertahan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 16, 'Seorang musuh manis dengan bibirnya, tetapi dalam hati merencanakan bagaimana ia dapat menjatuhkan dirimu ke dalam lobang, Seorang musuh menangis dengan matanya, tetapi apabila mendapat kesempatan ia tidak puas-puas dengan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 17, 'Kalau kemalangan menimpa dirimu, musuh kaudapat di sana sebelum engkau sendiri, dan pura-pura menolong ia mencengkam tumitmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 12, 18, 'Ia menggelengkan kepalanya dan bertepuk tangan, banyak berbisik-bisik dan berubah muka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 1, 'Barangsiapa menyentuh gala-gala mendapat noda dan siapa bersekutu dengan orang congkak menjadi serupa dengannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 2, 'Jangan mengangkat beban yang terlalu berat, pun pula jangan bersekutu dengan orang yang lebih kuat dan lebih kaya dari pada dirimu. Bagaimana periuk dapat berteman dengan kuali besi, periuk berbenturan dengan kuali lalu pecah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 3, 'Orang kaya berbuat lalim tapi masih juga bermegah- megah, orang miskin menderita kelaliman, namun mesti minta maaf.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 4, 'Jika engkau berguna, maka dipergunakan oleh orang kaya, tapi kalau engkau kekurangan, niscaya ditinggalkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 5, 'Apabila engkau berharta, maka orang kaya hidup bersama denganmu, lalu tanpa menyesalkan diri sedikitpun engkau dirampasinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 6, 'Manakala orang kaya membutuhkan dikau, engkau diperdayakannya, ia bersenyum- senyum kepadamu dan engkau diberinya harapan juga; ia berkata- kata manis kepadamu serta bertanya: "Apakah yang kau butuhkan."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 7, 'Tetapi engkau dipermalukan dengan makanannya dan sampai dua tiga kali engkau dirampasinya, akhirnya engkau diremoohkan olehnya. Kemudian ia melihat dikau tapi melalui saja, sambil menggelengkan kepalanya karena dirimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 8, 'Awaslah, jangan sampai diperdaya, sehingga engkau direndahkan karena kebodohanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 9, 'Jika engkau dipanggil oleh seseorang yang berkuasa, hendaklah menahan dirimu, maka engkau akan dipanggilnya dengan semakin mendesak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 10, 'Jangan menonjolkan dirimu sendiri, supaya jangan ditolak, tetapi jangan pula terlalu menjauh, nanti engkau sampai terlupa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 11, 'Jangan menyangka engkau boleh akrab dengan yang berkuasa, jangan pula percaya pada perkataannya yang melimpah. Sebab dengan banyak bicara hendak menguji dirimu dan sambil bersenyum simpul ia memancing.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 12, 'Sungguh tanpa kasihanlah orang yang tidak menahan perkataannya, ia tidak segan menyiksa ataupun membelenggu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 13, 'Berawas-awaslah dan hendaklah waspada, sebab engkau ditemani oleh keruntuhanmu sendiri', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 15, 'Tiap- tiap makhluk yang hidup mengasihi yang serupa dengan dia, demikianpun manusia mengasihi sesamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 16, 'Tiap- tiap makhluk bergabung dengan yang sejenis, dan manusiapun melekat kepada yang serupa dengannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 17, 'Bertemankah serigala dengan anak domba? Tidak pula orang berdosa dengan orang bertakwa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 18, 'Mungkinkah si dubuk berdamai dengan anjing, dan dapatkah orang kaya berdamai dengan orang miskin?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 19, 'Keledai liar di padang rumput menjadi mangsa singa, demikianpun orang miskin menjadi perumputan orang kaya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 20, 'Kerendahan hati dianggap keji oleh orang congkak dan demikianpun orang miskin dianggap keji oleh orang kaya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 21, 'Manakala seorang yang kaya menjadi goyah, niscaya ia ditopang teman kawannya, tetapi kalau seorang yang lemah sampai terjatuh, maka ia malah didepak oleh teman kawannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 22, 'Manakala orang kaya tersandung, niscaya banyaklah penolongnya, dan meskipun ia mengucapkan yang bukan- bukan, namun dinyatakan benar. Tetapi manakala orang miskin tersandung, ia pasti ditegur juga, dan meskipun berbicara dengan bijaksana, namun tidak diberi tempat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 23, 'Bilamana orang kaya berbicara, maka semua berdiam diri serta memuji- muji perkataannya setinggi langit. Sebaliknya, bilamana orang miskin berbicara, lalu orang berkata: "Siapa gerangan orang ini?" dan kalau ia tergelincir, maka ia direbahkan sama sekali.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 24, 'Memang kekayaan adalah baik, kalau tiada dosa sertanya, tetapi kemiskinan adalah buruk menurut anggapan kaum fasik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 25, 'Hati manusia merubah roman mukanya jadi baik ataupun buruk.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 13, 26, 'Muka yang berseri- seri merupakan tanda hati bahagia, tapi menemukan amsal menuntut pemikiran berat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 1, 'Berbahagialah orang yang tidak terpeleset dengan mulutnya, dan tidak digelisahkan oleh sesal atas dosa-dosanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 2, 'Berbahagialah orang yang tidak ditegur oleh hatinya sendiri, dan tidak kehilangan kepercayaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 3, 'Kekayaan tidak serasi dengan orang yang lokek, dan bagi orang kikir apa faedahnya segala harta bendanya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 4, 'Barangsiapa yang mengumpulkan dengan merugikan dirinya, ia menimbun bagi orang lain, dan orang luar akan hidup mewah dengan harta bendanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 5, 'Seseorang yang keras terhadap dirinya sendiri, terhadap siapakah ia baik hati, ia malah tidak sampai menikmati harta miliknya sendiri!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 6, 'Tidak ada seorangpun yang lebih buruk dari pada yang iri kepada dirinya. Itulah ganjaran kejahatannya sendiri!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 7, 'Kalau ia berbuat baik, niscaya ia berbuat tidak dengan sengaja, tapi akhirnya menyatakan kejahatannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 8, 'Buruklah orang yang matanya mengiri, yang memaling mukanya dan memandang rendah orang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 9, 'Mata orang serakah tidak puas dengan miliknya sendiri, dan mata duitan menyusutkan manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 10, 'Mata orang yang kikir menghemat makanan, maka kekurangan ada di atas mejanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 11, 'Anakku, apabila ada milik hendaklah baik memelihara dirimu, tetapi juga sampaikanlah persembahan yang patut kepada Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 12, 'Ingatlah bahwa maut tidak berayal-ayalan dan penetapan dunia orang mati tidak ditunjukkan kepadamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 13, 'Sebelum meninggal berbuatlah baik kepada sahabat, ulurkanlah tangan dan berikanlah kepadanya menurut kemampuanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 14, 'Kebahagiaan sekarang jangan kautolak dari dirimu sendiri dan jangan melewatkan bagian kebahagiaan yang diinginkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 15, 'Tidakkah hasil jerih lelahmu mesti kautinggalkan kepada orang lain, dan hasil jerih payahmu dibagikan dengan undian?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 16, 'Hendaklah memberi dan menerima serta bersenang-senang, sebab di dalam dunia orang mati orang tidak dapat lagi mencari hidup senang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 17, 'Segala makhluk menjadi tua seperti baju, dan ada penetapan kekal, yakni: Orang mesti mati!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 18, 'Sama seperti daun yang tumbuh pada pohon yang rindang: ada yang rontok ada yang tumbuh, demikianpun halnya bangsa yang berdarah daging: yang satu mati dan yang lain lahir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 19, 'Semua pekerjaan yang fana jatuh binasa, dan bersama dengannya lenyaplah yang mengerjakannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 20, 'Berbahagialah orang yang merenungkan kebijaksanaan serta menimbang-nimbang dengan pengertian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 21, 'Barangsiapa yang dalam hati memikirkan jalan-jalan kebijaksanaan merenungkan pula segala rahasianya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 22, 'Kejarlah kebijaksanaan seperti seorang pemburu, dan pasanglah pengadangan di jalan-jalannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 23, 'Barangsiapa mengintip melalui jendela-jendelanya mendengarkan pula pada pintu-pintunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 24, 'Barangsiapa memasang kediamannya dekat pada rumah kebijaksanaan menancapkan pula pasak kemahnya di dalam dinding-dindingnya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 25, 'ia membentangkan kemahnya di sisinya dan berkemah di tempat yang baik;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 26, 'semua anaknya ditempatkannya di bawah perlindungannya dan diam di bawah dedaunannya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 14, 27, 'maka ia terlindung olehnya terhadap panas terik, dan diam di dalam kemuliaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 1, 'Begitulah perbuatan orang yang takut akan Tuhan, dan siapa yang melekat pada Taurat memperoleh kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 2, 'Seperti ibu kebijaksanaan menjemput dia, dan bagaikan isteri yang masih perawan menyambutnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 3, 'Kebijaksanaan memberi dia makanan pengertian, dan memberi minum air kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 4, 'Bersandar kepadanya orang tidaklah goncang, yang percaya padanya tidak dikecewakan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 5, 'Kebijaksanaan meninggikan orang ke atas teman kawan, dan mulut orang dibuka olehnya di tengah-tengah jemaah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 6, 'Orang mendapat kegembiraan dan puncak sukacita, dan kemasyhuran abadi diberikan kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 7, 'Tetapi orang bodoh tidak sampai , memperoleh kebijaksanaan, dan orang berdosa tidak memperhatikannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 8, 'Kebijaksanaan adalah jauh dari kecongkakan, dan para pendusta tidak ingat kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 9, 'Tidak serasilah lagu pujian di mulut orang berdosa, sebab tidak diilhamkan oleh Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 10, 'Lagu pujian diucapkan berkat kebijaksanaan dan dibimbing oleh Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 11, 'Jangan berkata: "Tuhanlah yang membuat aku murtad," sebab la tidak perbuat apa yang dibenci-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 12, 'Jangan berkata: "Tuhanlah yang menyesatkan daku," sebab Tuhan tidak membutuhkan orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 13, 'Apa yang keji dibenci oleh Tuhan pun pula tidak diperkenankan oleh mereka yang takut kepada-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 14, 'Pada awal mula Tuhan menjadikan manusia serta menyerahkannya kepada keputusannya sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 15, 'Asal sungguh mau engkau dapat menepati hukum, dan berlaku setiapun dapat kaupilih.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 16, 'Api dan air telah ditaruh oleh Tuhan di hadapanmu, kepada apa yang kaukehendaki dapat kauulurkan tanganmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 17, 'Hidup dan mati terletak di depan manusia, apa yang dipilih akan diberikan kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 18, 'Sungguh besarlah kebijaksanaan Tuhan, la adalah kuat dalam kekuasaan-Nya dan melihat segala-galanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 19, 'Mata Tuhan tertuju kepada orang yang takut kepada-Nya, dan segenap pekerjaan manusia la kenal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 15, 20, 'Tuhan tidak menyuruh orang menjadi fasik, dan tidak memberi izin kepada siapapun untuk berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 1, 'Jangan menginginkan banyak AO anak yang nakal, dan atas anak-anak yang fasik jangan bergembira.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 2, 'Biarpun mereka banyak jumlahnya, namun jangan bergembira karenanya, jika mereka tidak menaruh ketakutan akan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 3, 'Jangan mengandalkan umur mereka yang panjang, jangan pula bersandar kepada jumlah mereka. Sebab lebih baiklah hanya seorang dari pada seribu, dan lebih baik pula mati taiipa anak dari pada mempunyai anak-anak yang fasik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 4, 'Karena satu orang yang arif maka kota menjadi ramai, tetapi bangsa kaum fasik akan jatuh binasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 5, 'Banyak hal yang serupa itu telah dilihat mataku dan lebih hebat lagi yang didengar telingaku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 6, 'Api akan berkobar-kobar di tengah-tengah gerombolan orang berdosa, dan kemurkaan bernyala pada bangsa yang fasik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 7, 'Tuhan tidak menyayangi para raksasa purbakala, yang memberontak berdasarkan kekuatan mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 8, 'Allahpun tidak mengasihani pula kaum sekota Lot, dan la membenci mereka karena kecongkakan mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 9, 'Bangsa yang patut diharamkan tidak disayangkan-Nya, melainkan dibasmi karena segala dosanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 10, 'Demikianpun nasib enam ratus ribu orang yang berjalan kaki, yang berkumpul dalam ketegaran hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 11, 'Sekiranya hanya ada seorang saja yang bertegang leher, niscaya suatu keajaiban kalau ia tetap terluput dari hukuman. Sebab pada Allah baik belas kasihan maupun kemurkaan, la kuasa mengampuni dan mencurahkan kemurkaan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 12, 'Hukuman-Nya sebesar belas kasihan-Nya, dan tiap-tiap orang diadili oleJi-Nya sekadar perbuatannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 13, 'Orang berdosa serta rampasannya tidak akan lolos, sedangkan kesabaran orang bertakwa tidak dikecewakan pula.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 14, 'Allah memberi jalan kepada segenap belas kasihan-Nya, namun setiap orang mendapat apa yang setimpal dengan perbuatannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 15, 'Jangan berkata: "Aku akan bersembunyi dari Tuhan, siapakah di atas sana yang teringat kepadaku?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 17, 'Niscaya di tengah-tengah orang banyak aku tidak dikenal, dan apakah aku ini di dalam segenap ciptaan yang tidak berhingga?"', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 18, 'Sungguh, langit, bahkan langit tertinggi, induk samudera dan bumi goncang, apabila Allah datang mengunjunginya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 19, 'Gunung-gemunung bersama segala alas bumi disergap kegentaran, manakala la memandangnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 20, 'Tetapi kesemuanya itu tidak terpikir oleh hati seorang juapun, siapa gerangan menghiraukan perbuatan Allah?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 21, 'Taufan tetap tak kelihatan bagi manusia, demikianpun kebanyakan pekerjaan Tuhan tersembunyi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 22, 'Tindakan-Nya yang adil, siapakah yang mewartakannya, siapakah yang menantikannya? Sebab: "perjanjian jauhlah adanya."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 23, 'Demikian pendapat orang yang singkat akal; orang pandir dan yang tersesat mereka-reka kebodohan belaka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 24, 'Anakku, dengarkanlah aku dan berolehlah pengetahuan, perhatikanlah segala perkataanku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 25, 'Aku hendak menyampaikan pengajaran secara terukur, dan dengan teliti memaklumkan pengetahuan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 26, 'Tatkala pada awal mula Tuhan menciptakan makhluk-Nya, maka sejak dibuat-Nya lapun menetapkan pembagiannya pula.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 27, 'Segenap ciptaan-Nya diatur-Nya untuk selama-lamanya, dan wilayah kuasa makhluk ditentukan untuk segala keturunannya. Semua tidak kelaparan dan tidak menjadi lelah, dan tak pernah melalaikan tugasnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 28, 'Yang satu tidak menyesakkan yang lain, dan tak pernah berontak terhadap firman Allah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 29, 'Kemudian Tuhan melayangkan pandangan-Nya ke bumi, lalu diisi-Nya dengan pelbagai anugerah yang baik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 16, 30, 'Dengan segala macam makhluk yang hidup Tuhan menutupi permukaannya, dan semua akan kembali pula kepada bumi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 1, 'Manusia diciptakan Tuhan dari tanah, dan ke sana akan dikembalikan juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 2, 'Ia menetapkan waktu tertentu bagi mereka dan sejumlah hari, sambil memberi mereka kekuasaan atas segala sesuatu diatas bumi,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 3, 'Kepadanya dikenakan kekuatan yang serupa dengan kekuatan Tuhan sendiri dan menurut gambar Allah dijadikan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 4, 'Di dalam segala makhluk yang hidup Tuhan menaruh ketakutan kepada manusia, agar manusia merajai binatang dan unggas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 6, 'Lidah, mata dan telinga dibentuk-Nya, dan manusia diberi-Nya hati untuk berpikir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 7, 'Tuhan memenuhi manusia dengan pengetahuan yang arif, dan menunjukkan kepadanya apa yang baik dan apa yang jahat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 8, 'la menanamkan mata-Nya sendiri di dalam hati manusia untuk menyatakan kepadanya keagungan pekerjaan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 10, 'Maka manusia mesti memuji nama Tuhan yang kudus untuk mewartakan pekerjaan-Nya yang agung.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 11, 'Tuhan telah mengaruniai manusia pengetahuan lagi dengan memberi mereka hukum kehidupan menjadi milik pusaka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 12, 'Perjanjian kekal diikat-Nya dengem mereka, dan segala hukum-Nya dipermaklumkan-Nya kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 13, 'Mata mereka telah melihat kemuliaan Tuhan yang agung, dan suara-Nya yang dahsyat telah didengar telinga mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 14, 'la berkata kepada mereka: "Jauhilah setiap kelaliman," dan masing-masing diberi-Nya perintah mengenai sesamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 15, 'Langkah laku manusia selalu terbentang di hadapan Tuhan, dan tak tersembunyi bagi mata-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 17, 'Bagi tiap-tiap bangsa diangkat-Nya penguasa, tetapi Israel menjadi bagian Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 19, 'Segala pekerjaan manusia seperti matahari terbentang di hadapan Tuhan, dan mata-Nya selalu tertuju kepada langkah laku mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 20, 'Kedurjanaan manusia tak lot tersembunyi bagi Tuhan, dan segala dosa terbuka hadapanNya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 22, 'Seperti cincin meterai demikian derma seseorang tersimpan pada Tuhan, dan bagaikan biji mata dipelihara-Nya sedekah manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 23, 'Kelak Tuhan bangkit dan membalas mereka, dan balasan diturunkan-Nya ke atas kepala mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 24, 'Namun untuk orang yang menyesalpun Tuhan membuka jalan kembali, dan orang yang kehilangan ketabahan hati dilipur oleh-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 25, 'Berpalinglah kepada Tuhan dan lepaskanlah dosa, berdoalah di hadapan-Nya dan berhentilah menghina.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 26, 'Kembalilah kepada Yang Mahatinggi dan berpalinglah dari yang durjana, dan hendaklah sangat benci kepada kekejian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 27, 'Siapa gerangan di dunia orang mati memuji Yang Mahatinggi, sebagai pengganti orang yang hidup dan yang mempersembahkan pujian?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 28, 'Dari orang mati lenyaplah pujian seperti dari yang tiada sama sekali, sedangkan barangsiapa yang hidup dan sehat memuji Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 29, 'Alangkah besarnya belas kasihan Tuhan serta pengampunan-Nya bagi semua yang berpaling kepada-Nya!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 30, 'Sebab tidak semua dapat ada pada manusia, oleh sebab anak manusia tidaklah baka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 31, 'Apakah yang lebih terang dari pada matahari? Namun iapun menjadj kelamjuga, tetapi kejahatan belakalah apa-u yang dipikirkan daging dan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 17, 32, 'Tuhan mengamat-amati kuasa-kuasa di langit yang tinggi, tetapi manusia debu dan abu belaka semuanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 1, 'Dia yang hidup untuk selama-lamanya menciptakan segala-galanya bersama-sama.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 2, 'Tuhanlah melulu yang.ternyata benar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 4, 'Tidak ada seorangpun diberi-Nya kuasa mewartakan pekerjaan-Nya. Siapa gerangan menyelami perbuatan agung-Nya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 5, 'Siapa gerangan dapat mengukur keagungan-Nya yang dahsyat, dan siapakah yang tambah menceritakan belas kasihan-Nya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 6, 'Tak dapat dikurangkan maupun ditambahkan; keajaiban-keajaiban Tuhan tak terselami.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 7, 'Apabila seseorang berakhir maka ia baru mulai, dan setelah berhenti orang kebingungan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 8, 'Apakah manusia dan manakah gunanya, manakah kebaikari dan manakah keburukannya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 9, 'Paling-paling seratus tahun lamanya umur manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 10, 'Seperti setetes air dari laut dan laksana sebutir pasir, demikianlah tahun yang sedikit di masa kekal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 11, 'Karena itulah maka Tuhan panjang hati terhadap manusia, dan belas kasihan dicurahkan-Nya ke atas mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 12, 'la melihat dan mengetahui betapa buruklah kesudahan mereka, dan karenanya kerelaan dilipatgandakan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 13, 'Belas kasihan manusia hanya merangkum sesamanya, sedangkan belas kasihan Tuhan melingkungi segala makhluk. dan membawa kembali seperti seorang gembala kawanannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 14, 'la berbelas kasihan terhadap niereka yang menerima ketertiban-Nya serta ihencari-cari ketentuan-ketentuan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 15, 'Anakku, jangan menyertakan suatu noda dengan amalanmu; atau perkataan pahit dengan setiap pemberianmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 16, 'Bukankah panas terik disusutkan embun? Demikianpun sebuah perkataan baik lebih berhargalah dari pada pemberian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 17, 'Bukankah sebuah perkataan sungguh lebih tinggi harganya dari pada hadiah yang indah? Tetapi seorang dermawan menghubungkan kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 18, 'Tanpa beramal seorang bodoh mencaci, dan pemberian seorang yang memaki membuat mata memudar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 19, 'Sebelum berbieara belajarlah dahulu, dan peliharalah dirimu sebelum jatuh sakit.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 20, 'Sebelum tampil di depan pengadilan periksalah dirimu dahulu, maka engkau mendapat kerelaan di waktu pencobaain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 21, 'Rendahkanlah dirimu sebelum jatuh sakit, dan apabila berdosa hendaklah nyata bertobat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 22, 'Jangan ada sesuatupun mencegah dirimu dari membayar nazaf tepat pada waktunya, . dan jangan bertangguh sampai mati akan menepatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 23, 'Sebelum bernazar siapkanlah dirimu dahulu* janganlah engkau menjadi seperti orang yang mencobai Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 24, 'Pada hari ajalmu ingatlah akan murka Tuhan, dan akan Waktu balas dendam pabila la beralih wajah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 25, 'Di masa kelimpahan ingatlah akan waktu kelaparan, dan akan kemiskinari dan kekurangan di kala kekayaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 26, 'Dari pagi sampai malam waktu beralih, dan di hadapan Tuhan segala-galanya bergegas-gegas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 27, 'Dalam segala-galanya orang bijak beringat-ingat, dan menghindarkan kesalahan bahkan di masa dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 28, 'Setiap orang arif mengenal" kebijaksanaan, dan memuji orang yang telah mendapatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 29, 'Orang yahg memahami aaisal menjadi mahir sendiri, dan mengalirkan pepatah yang jitu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 30, 'Jangan menuruti Segenap keinginanmu, melainkan jauhkanlah dirimu dari segala nafsumu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 31, 'Dengan memuaskan segala keinginan-hatimu engkau menjadikan dirimu tertawaah musuhmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 32, 'Jangan senang hati karena kemewahan besar, janganlah mengikat dirimu kepada persekutuan serupa itu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 18, 33, 'Jangan jatuh miskin karena berpesta-pesta dengan uang pinjaman, bila tidak ada apa-apa di dalam pundi-pundimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 1, 'Buruh peminum tak pernah akan kaya, dan barangsiapa mengabaikan yang kecil-kecil lambat laun jatuh miskin.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 2, 'Anggur dan perempuan telah menjatuhkan orang-bijak, dan siapa yang mehgunjungi pelacur lebih gegabah lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 3, 'la akan dimiliki kebusukan dan ulat, dan si gegabah akan dicabut nyawanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 4, 'Orang yang segera percaya kurang berpikir, barangsiapa berdosa bersalah terhadap dirinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 5, 'Barangsiapa senang pada yang buruk pasti mendapat hukuman,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 6, 'tetapi barangsiapa benci kepada obrolan lepaslah ia dari yang jahat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 7, 'Jangan sekali-kali menyiarkan suatu omongan, niscaya engkau tak akan kekurangan apapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 8, 'Baik kepada kawan maupun kepada lawan jangan bercerita, jangan menyingkapkannya, kecuali kalau itu berarti berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 9, 'Sebab engkau didengar salah seorang yang lalu berjaga-jaga terhadapmu dan pada waktunya benci kepadamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 10, 'Jika kaudengar obrolan, biarlah mati denganmu. Jangan kuatir, engkau tidak akan pecah karenanya!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 11, 'Orang bodoh kesakitan karena satu perkataan saja, seperti perempuan yang melahirkan kesakitan karena anaknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 12, 'Seperti anak panah yang tertancap dalam otot paha, demikian halnya suatu perkataan dalam hati orang bodoh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 13, 'Minta keterangan kepada kawan, mungkin ia tidak berbuat apa-apa, dan andaikata ia berbuat, jangan berbuat lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 14, 'Minta keterangan kepada tetangga, barangkali ia tidak mengatakan apa-apa, dan andaikata dikatakannya, jangan diulanginya lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 15, 'Minta keterangan kepada kawan, sebab sering kali hanya fitnah belaka, dan jangan percaya akan setiap perkataan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 16, 'Ada beberapa orang tergelincir tapi tidak dengan disengaja, siapa gerangan belum pernah berdosa dengan lidahnya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 17, 'Minta keterangan kepada sesamamu, sebelum ia kauancam, dan berikanlah jalan kepada hukum dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 20, 'Segenap kebijaksanaan ialah ketakutan akan Tuhan dan pelaksanaan hukum Taurat tercantum di dalam setiap kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 22, 'Mengenal yang jahat bukanlah kebijaksanaan, dan tidak ada pengertian di mana orang berdosa berunding.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 23, 'Ada semacam kepintaran yang merupakan kengerian belaka, tetapi hanya bodoh saja orang yang kekurangan kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 24, 'Lebih baiklah kurang pandai tapi bertakwa dari pada sangat berilmu tapi pelanggar hukum Taurat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 25, 'Ada kepintaran yang tajam tapi: kurang adil, dan ada orang yang memutarbalikkan hukum untuk memenangkan perkara.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 26, 'Ada orang yang berjalan sambil membungkuk karena susah,tetapi batinnya penuh penipuan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 27, 'Orang semacam itu menundukkan mukanya dan bersituli, tetapi tanpa diketahui ia menyemu engkau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 28, 'Kalau mereka karena kurang kuat terhalang untuk berdosa, niscaya segera yang jahat dilakukannya, manakala ada sempat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 29, 'Seseorang dikenal pada rupa lahirnya, dan orang bijakpun dikenal pada air mukanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 19, 30, 'Pakaian seseorang dan ketawa terbahak-bahak serta peri langkah manusia menyatakan siapa dirinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 1, 'Ada teguran yang tidak tepat pada waktunya, dan ada orang yang berdiam diri dan justru dialah arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 2, 'Betapa lebih baiknya menegur dari pada bergeram.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 3, 'Barangsiapa mengakui bersalah akan terluput dari kerugian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 4, 'Seperti seorang kebiri yang ingin memperkosa seorang gadis, demikianlah orang yang dengan kekerasan memaksakan hukum', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 5, 'Ada pendiam yang kedapatan bijaksana, dan ada orang yang dibenci karena obrolannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 6, 'Ada orang yang diam karena tidak tahu menjawab, tetapi ada pula yang diam karena mengindahkan waktunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 7, 'Orang bijak berdiam diri sampai pada saatnya, sedangkan pembual dan orang bodoh membiarkan waktu tepat berlalu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 8, 'Barangsiapa banyak bicara akan disegani orang, dan dibencilah orang yang menyalahgunakan wewenangnya untuk bicara.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 9, 'Boleh jadi orang berhasil gemilang dalam kemalangan, dan ada kalanya barang yang ditemukan sebenarnya kehilangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 10, 'Ada pemberian yang tidak menguntungkan kepadamu sama sekali, tetapi juga ada pemberian yang dua kali lipat balasannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 11, 'Ada kalanya orang direndahkan karena kemuliaannya, tetapi ada juga orang yang dapat mengangkat kepalanya setelah direndahkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 12, 'Ada orang yang membeli banyak dengan sedikit, namun membayar tujuh lipat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 13, 'Dengan perkataannya orang bijak membuat dirinya disayang, sedangkan keramahan orang bodoh sia-sia belaka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 14, 'Pemberian dari orang pandir tidak berfaedah bagimu, sebab bukan satu melainkan banyaklah matanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 15, 'Sebab hanya sedikitlah yang diberinya, namun banyak mencela, dan ia angkat bicara seperti pencanang; hari ini ia meminjamkan dan besok dimintanya kembali. Dibencilah orang semacam itu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 16, 'Orang bodoh berkata: Tidak ada kawari padaku, dan aku tidak mendapat terima kasih bagi amal-amalku;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 17, 'orang yang makan rotiku busuklah lidahnya." Betapa sering dan betapa banyak orang mencemoohkannya!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 18, 'Lebih baiklah jatuh tergelincuh karena lantai dari pada karena lidah; demikianpun keruntuhan kaum jahat datang dengan amat cepatnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 19, 'Orang yang tidak menyenangkan adalah sama seperti cerita yang tidak pada waktu tepat dan yang diulang-ulang oleh mulut orang biadab.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 20, 'Amsal dari mulut orang bodoh diabaikan, sebab tidak diucapkannya tepat pada waktunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 21, 'Boleh jadi orang menahan diri dari berdosa karena miskin, maka dalam istirahatnyapun hatinya tidak terganggu juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 22, 'Ada orang yang membinasakan dirinya karena malu, dan jatuh binasa karena memandang orang bodoh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 23, 'Ada orang yang karena malu berjanji-janji kepada kawan dan begitu menjadikannya lawan tanpa alasan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 24, 'Suatu noda yang buruk ialah dusta; senahtiasa terdapat dalam mulut orang biadab.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 25, 'Lebih baiklah seorang pencuri dari pada orang yang berdusta terus, namun kedua-duanya mendapat kebinasaan sebagai warisan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 26, 'Kebiasaan pembohong adalah suatu keaiban, dan malunya selalu melekat kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 27, 'Barangsiapa yang bijak dalam bicara memajukan dirinya, dan para pembesar berkenan akan manusia yang arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 28, 'Orang yang mengolah tanah menimbun panenannya, dan barangsiapa berkenan kepada para pembesar dapat memulihkan kelaliman.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 29, 'Sumbangan dan pemberian menyilaukan rnata orang bijak, dan seperti sumbat dalam mulut mendiamkan teguran.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 30, 'Kebijaksanaan tersembunyi dan harta terpendam, apa gunanya kedua-duanya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 20, 31, 'Lebih baiklah orang yang menyembunyikan kebodohannya dari pada yang menyembunyikan kebijaksanaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 1, 'Jika engkau, anakku, telah berbuat dosa, janganlah berbuat lagi, melainkan hendaklah berdoa oleh karena dosa-dosamu yang sudah-sudah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 2, 'Seperti terhadap seekor ular larilah dari pada dosa, sebab engkau dipagutnya apabila engkau mendekat. Giginya adalah laksana gigi singa, dan mencabut nyawa manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 3, 'Setiap pelanggaran seperti sebilah pedang bermata dua, dan tidak ada penyembuhan bagi luka-Iukanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 4, 'Kelaliman dan kepongahan menghancurkan kota; demikianpun rumah orang congkak dirobohkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 5, 'Doa dari mulut orang miskin sampailah ke telinga Tuhan, dan amat cepat pengadilan-Nya akan tiba.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 6, 'Barangsiapa membenci teguran mengikuti jejak orang berdosa, sedangkan orang yang takut akan Tuhan bertobat dalam hatinya,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 7, 'Yang benhulut besar dikenal dari jauh, tetapi orang yang bijak mengetahui pabila tergelincir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 8, 'Siapa yang membangun rumahnya dengan harta orang lain menyerupai seseorang yang mengumpulkan batu guna kuburnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 9, 'Himpunan orang fasik merupakan timbunan ampas kayu lenan, dan nyala api menjadi kesudahannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 10, 'Jalan orang berdosa licin tanpa batu, tetapi di ujungnya terletak tubir dunia orang mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 11, 'Barangsiapa menepati hukum menguasai pikiran-pikirannya, dan penyempurnaan ketakutan akan Tuhan ialah kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 12, 'Orang yang tidaklah arif tidak dapat diasiih, tetapi juga ada kearifan yang menimbulkan kepahitan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 13, 'Pengetahuan orang bijak seperti banjir sebak, dan nasehatnya laksana sumber air hidup;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 14, 'Batin orang bodoh seperti tempayan yang meretak, tak dapat menahan kebijaksanaan manapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 15, 'Jika sebuah perkataan yang bijak didengar orang yang berpengetahuan, niscaya dipujinya dan suatu perkataan lain ditambah olehnya. Sebaliknya: jika didengar orang yang kurang berpikir, maka ia merasa segan terhadapnya serta membuangnya ke belakang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 16, 'Cakap orang bodoh adalah seperti beban di perjalanan, tetapi kemanisan terdapat pada bibir orang arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 17, 'Ucapan orang arif dicari-cari dalam jemaah, dan perkataannya direnungkan dalam hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 18, 'Kebijaksanaan bagi orang bodoh laksana rumah yang sudah lenyap, dan pengetahuan orang tumpul ialah bicara yang kacau-balau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 19, 'Ketertiban bagi orang bebal laksana sengkela pada kaki, dan seperti belenggu.pada tangan kanannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 20, 'Orang bodoh tertawa terbahak-bahaks sedangkan orang pintar diam-diam tersenyum.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 21, 'Ketertiban bagi orang cerdik bagaikan perhiasan emas, dan bagaikan gelang di tangan kanannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 22, 'Kaki orang bodoh segera masuk rumah, tetapi orang yang berpengalaman mengambil sikap yang sopan di depannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 23, 'Orang pandir mengintip dari pintu ke dalam rumah, sedangkan orang terdidik berdiri di luar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 24, 'Mendengar pada pintu sungguh kurang ajar, orang cerdik merasa keaibannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 25, 'Bibir pembual mengulangi perkataan orang lain, tetapi perkataan orang cerdik ditimbang-timbang dalam neraca.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 26, 'Hati orang bodoh ada di dalam mulutnya, tetapi mulut para bijaksana ialah hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 27, 'Jika orang fasik mengutuk lawannya, maka ia mengutuk dirinya sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 21, 28, 'Seorang pemfitnah mencemarkan dirinya sendiri dan dibenci oleh semua orang di tempat kediamannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 1, 'Seorang pemalas mirip dengan ?t?i batu yang kotor, siapa saja bersiul karena jijiknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 2, 'Seorang pemalas mirip dengan sekepal kotoran, siapa saja menyentuhnya mengebaskan tangannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 3, 'Malu benar bagi seorang ayah memperanakkan anak laki-laki yang tidak terdidik, tetapi seorang anak perempuan semacam itu dilahirkan akan keaibannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 4, 'Seorang anak perempuan cerdik mendapat suaminya, tetapi seorang anak perempuan keji menjadi kesusahan bagi yang melahirkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 5, 'Anak perempuan biadab mendatangkan malu bagi bapa serta suaminya, dan akan dihina oleh kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 6, 'Seperti musik di kala berkabung, demikian ucapan yang tidak tepat pada waktunya; tetapi siksa dan ketertiban selalu kebijaksanaan adanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 9, 'Barangsiapa mengajar orang bodoh merekatkan pecah-pecahan, ataupun membangunkan orang dari tidur nyenyak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 10, 'Orang yang bercerita kepada orang yang bodoh bercerita kepada orang yang tidur lelap, pada akhirnya ia berkata: "Ada apa sih?"', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 11, 'Tangisilah orang mati karena ia kehilangan cahaya, tetapi tangisilah orang bodoh karena ia kehilangan akalnya. Hendaklah kurang menangisi orang mati, sebab ia sudah mendapat ketentraman, sedangkan hidup orang bodoh lebih buruk dari pada mati adanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 12, 'Berkabung atas orang mati lamanya tujuh hari, tetapi atas orang bodoh dan orang fasik orang berkabung seumur hidupnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 13, 'Jangan banyak bicara dengan orang bodoh, dan jangan mengunjungi orang yang tumpul; berawaslah terhadapnya, supaya engkau jangan mendapat kesusahan, dan dicemarkan manakala ia mengebas-ngebaskan dirinya. Hindarilah dia maka engkau akan tenteram, dan tidak akan mendapat susah karena kebebalannya', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 14, 'Apakah lebih berat dari timah hitam? Siapa gerangan namanya kecuali "SiBodoh".', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 15, 'Pasir, garam, dan batang besi lebih ringan dipikul dari pada manusia yang tumpul.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 16, 'Kasau yang kokoh disambung dalam bangunan tidak terlepas karena segala macam gempa bumi; demikianpun hati yang bersandar pada pikiran yang masak-masak dipertimbangkan tidaklah goyah pada waktu manapun juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 17, 'Hati yang bersandar pada pemikiran yang tajam adalah mirip dengan perhiasan turap pada dinding terlampas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 18, 'Batu-batu yang terpasang di atas tembok tidak bertahan terhadap angin; demikianpun halnya hati yang takut karena angan-angan yang bodoh tidak bertahan terhadap kekejutan manapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 19, 'Yang menyentuh mata membuat air mata bercucuran, siapa yang menyentuh hati menimbulkan perasaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 20, 'Melemparkan batu orang menghalau burung, dengan mencaci maki kawan orang memutuskan persahabatan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 21, 'Bahkan apabila kauhunus pedang terhadap kawan, janganlah putus asa. Masih juga ada jalan kembali.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 22, 'Kalau engkau telah membuka mulut terhadap kawan, jangah kuatir, sebab masih dapat berdamai; terkecuali caci maki, kecongkakan, membuka rahasia dan pukulan cedera, sebab terhadap kesemuanya itu setiap kawan lari.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 23, 'Hendaklah tetap setia kepada sesama dalam kemiskinannya, supaya engkaupun dapat ikut pula dalam kesejahteraannya. Berpautlah kepadanya di masa kesusahan, supaya engkaupun dapat mengambil bagian juga dalam warisannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 24, 'Asap dapur dan sulang mendahului api, demikian pula penghinaan mendahului penumpahan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 25, 'Aku tidak malu-malu melindungi kawan, dan tidak menyembunyikan diri terhadapnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 26, 'Tetapi jika aku ditimpa .kemalangan karena dia, maka siapa saja mendengarnya akan waspada terhadapnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 22, 27, 'Siapa gerangan menaruh penjagaan pada mulutku dan memasang meterai pertimbangan pada bibirku, supaya aku jarigan terjatuh karena lidah, dan jangan dibinasakan olehnya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 1, 'Ya Tuhan, Bapa dan Penguasa hidupku, janganlah aku Kauserahkan kepada canda mulut dan bibir, jangan Kaubiarkan aku terjatuh karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 2, 'Siapa kiranya mengenakan cambuk pada pikiranku dan cemeti kebijaksanaan pada hatiku, supaya kesalahanku jangan disayangkan, dan dosaku jangan terlupvit dari padanya,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 3, 'sehingga kekhilafianku tidak bertambah dan dosa mulutku tidak berlimpah; maka aku tidak akan jatuh dihadapan para lawanku dan musuhku tidak akan bergirang atas diriku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 4, 'Ya Tuhan, Bapa dan Allah hidupku, jangan memberi aku mata yang angkuh,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 5, 'melainkan jauhkanlah dari padaku keinginan keji.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 6, 'Semoga aku tidak digenggam oleh gelojoh dan syahwat, dan jangan aku Kauserahkan kepada nafsu keji.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 7, 'Hendaklah, hai anak-anak, -mendengarkan pengajaranku tentang mulut; siapa yang menepatinya tidak akan terjebak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 8, 'Orang berdosa tertangkap dengan bibirnya sendiri, dan pemfitnah dan orang congkak terjatuh karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 9, 'Jangan membiasakan mulutmu bersumpah, dan menyebut nama Yang Mahakudus jangan menjadi lazim.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 10, 'Sebab seperti seorang budak yang terus diperiksa tidak terluput dari bilur-bilur, demikianpun orang yang biasa bersumpah dan menyebut nama Yang Mahakudus tidak pula bersih dari dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 11, 'Orang.yang banyak bersumpah akan penuh dengan kefasikan, dan cemeti tidak akan lenyap dari rumahnya. Kalau bersalah ia dibebani dosanya sendiri, dengan tidak mengindahkannya ia berdosa dua lipat. Kalau telah bersumpah dusta ia tidak akan dibenarkan, melainkan rumahnya akan penuh dengan malapetaka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 12, 'Ada semacam omongan yang boleh disamakan dengan maut. Mudah-mudahan tidak terdapat dalam milik pusaka Yakub. Sebab semuanya itu mesti jauh dari orang bertakwa, dan mereka tidak holeh berguling-guling dalam dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 13, 'Jangan membiasakan mulutmu kepada carut-marut yang tak terkendali, sebab perkataan dosa terkandung di dalamnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 14, 'Ingatlah akan bapa ibumu, manakala kau duduk di kalangan para pembesar, supaya engkau jangan lupa daratan di hadapan mereka, dan bersibodoh akibat kebiasaanmu. Maka kauinginkan bahwa tidak dilahirkan, dan hari kelahiranmu akan kaukutuk.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 15, 'Orang yang sudah biasa dengan, perkataan kurang senonoh tak akan memperbaiki dirinya selama umur hidup mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 16, 'Dua golongan orang mehimbun-nimbun dosa dan yang ketiga mendatangkan kemurkaan, yakni:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 17, 'nafsu yang panas bagaikan api yang menyala tak akan padam sebelum habis diminum; orang yang berbuat cabul pada tubuhnya sendiri tak berhenti sebelum habis terbakar oleh api; bagi orang yang cabul roti apa saja manis rasanya dan tak jemu-jemulah ia sampai mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 18, 'Orang berdosa di ranjangnya sendiri seraya berkata dalam hati: "Siapakah yang melihat aku? Kegelapan menudungi aku dan dinding-dinding menyembunyikan daku dan tidak ada seorangpun melihat aku! Mengapa aku mesti takut? Yang Mahatinggi tidak ingat akan segala dosaku."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 19, 'la hanya takut terhadap mata manusia, dan tidak ingat bahwa mata Tuhan seribu kali lebih terang-benderang dari pada matahari dan memandang segala tingkah laku manusia serta menembus sampai ke sudut yang paling tersembunyi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 20, 'Segala-galanya dikenal-Nya bahkan sebelum dijadikan, dan demikianpun halnya setelah diselesaikan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 21, 'Orang tadi akan dihukum di jalan-jalan di kota, dan akan ditangkap dimana tidak tersangka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 22, 'Demikianpun halnya seorang isteri yang meninggalkan suaminya dan dari orang lain melahirkan waris.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 23, 'Sebab pertama-tama ia tidak taat kepada hukum dari Yang Mahatinggi, keduanya ia bersalah terhadap suaminya, ketiganya ia berzinah dengan melacur, dan akhirnya melahirkan anak dari laki-laki lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 24, 'Perempuan itu sendiri akan dibawa ke hadapan jemaah, dan tentang anak-anaknya akan diadakan pemeriksaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 25, 'Anak-anaknya tidak akan berakar, dan ranting-rantingnya tidak akan berbuah. Sebagai kutukan kenang-kenangannya ditinggalkannya, dan keaibannya tak akan terhapus.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 23, 27, 'Maka orang yang masih tertinggal akan menjadi insaf, bahwa tidak ada sesuatupun lebih baik dari pada takut akan Tuhan, dan tidak ada sesuatupun lebih manis dari pada menepati perintah-perintah Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 1, 'Kebijaksanaan memuji dirinya sendiri dan di tengah-tengah umatnya bermegah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 2, 'Di dalam jemaah Yang Mahatinggi ia membuka mulutnya dan bermegah di hadapan kekuasaan-Nya:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 3, 'Seperti pohon aras di gunung Libanon aku berkembang, dan bagaikan pohon saru di pegunungan Hermon.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 4, 'Aku telah tinggal di tempat yang tinggi dan takhtaku di atas tiang awan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 5, 'Seorang diri telah kujelajah lingkaran langit dan berkeliling di dalam lubuk tubir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 6, 'Aku telah berkuasa dalam gelombang-gelombang laut, di atas bumi seluruhnya, pada tiap-tiap bangsa dan rakyat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 7, 'Di dalam semuanya itu telah kucari tempat istirahat, dan di dalam milik siapakah dapat kupasang tempat tinggalku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 8, 'Maka berfirmanlah kepadaku Pencipta alam semesta, dan yang menciptakan daku menetapkan tempat kemahku. Sabda-Nya: Di Yakublah mesti kaupasang kemahmu, dan Israel kaudapat milik pusaka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 9, 'Sebelum masa purba sejak awal mula aku telah diciptakan-Nya, dan sampai selama-lamanya aku tidak akan lenyap.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 10, 'Aku berbakti kepada-Nya dalam Kemah yang kudus, dan dengan demikian aku menetap di Sion.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 11, 'Di kota kesayangan-Nya aku diberi-Nya tempat istirahat, dan wilayah kekuasaanku ada di Yerusalem.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 12, 'Pada umat terhormat aku berakar, di dalam bagian Tuhan, milik pusaka-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 13, 'Seperti pohon aras di gunung Libanon aku berkembang, dan bagaikan pohon saru dipegunungan Hermon', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 14, 'Seperti pohon korma di En-Gedi aku berkembang, dan laksana pokok ma war di Yerikho; aku tumbuh laksana pohon zaitun yang elok di dataran, dan seperti pohon berangan di tepi air.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 15, 'Aku harum semerbak seperti kayu mam"s dan aspalat, dan meratakan wangian laksana kemenyan pilihan, seperti galbanum, oniks-dan stakte, dan bagaikan asap dupa di Kemah suci.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 16, 'Seperti pohon tusam kurambatkan cabang-cabangku, dan ranting-rantingku adalah elok jelita.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 17, 'Bagaikan pokok anggur kutumbuhkan tunas-tunas jelita, dan bungaku menjadi buah yang banyak dan masak sedap.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 19, 'Hai kamu sekalian yang menginginkan daku, datanglah kemari, kenyangkanlah dirimu dengan hasilku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 20, 'Sebab kenanganku lebih manis dari pada madu, dan pusakaku lebih manis dari cairan sarang lebah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 21, 'Yang mengenyam aku masih lapar terus, dan yang meminum aku masih dahaga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 22, 'Barangsiapa mendengarkan daku tidak akan dikecewakan, dan yang bekerja dengan daku tidak akan berdosa."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 23, 'Semuanya itu ialah Kitab Perjanjian dari Allah Yang Mahatinggi, Taurat yang diperintahkart Musa kepada kita sebagai pusaka bagi seluruh jemaah Yakub.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 25, 'Taurat melimpahkan kebijaksana-an bagaikan sungai Pison, seperti sungai Tigris di musim buah baru;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 26, 'ia meluapkan pengertian seperti sungai Efrat, laksana sungai Yordan di musim panen;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 27, 'pengajaran dialirkannya bagaikan sungai Nil, seperti sungai Gihon di musim petik anggur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 28, 'Manusia pertama tidak mengetahuinya dengan sempurna, dan yang terakhirpun tidak sampai menyelaminya pula.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 29, 'Sebab lebih berisi dari pada lautlah pikiran-pikirannya, dan nasehatnya lebih dalam dari pada samudera besar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 30, 'Aku hanya mengalir seperti selokan dari sungai, dan bagaikan saluran air menuju taman raya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 31, 'Pikirku: "Aku hendak menyirami kebunku, dan hendak mengairi segala petakku." Tetapi tiba-tiba selokanku menjadi sungai, dan sungai itu menjadi laut;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 32, 'Maka aku hendak memancarkan ajaranku bagaikan fajar, dan menyinarkannya sampai kejauhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 33, 'Bagaikan nubuat hendak kusiarkan pengajaranku, dan kutinggalkan kepada semua angkatan yang datang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 24, 34, 'Sungguh, aku tidak beijerih payah untuk diriku melulu, tetapi untuk semua orang yang mencari kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 1, 'Tiga hal yang disukai jiwaku: Allah dan manusiapun berkenan kepadanya, yakni: kerukunan di antara saudara dan persahabatan di antara kawan dan suami isteri yang selaras.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 2, 'Jiwaku benci kepada tiga macam orang, dan cara hidupnya sangat mengesalkan hatiku, yakni: orang miskin yang congkak dan orang kaya pendusta dan orang beruban yang berzinah dan kurang pengertian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 3, 'Di masa muda engkau tidak mengumpulkan, bagaimana gerangan engkau mendapat sesuatu di masa tuamu? 4 Betapa cocoklah pertimbangan dengan uban, dan betapa serasilah mengetahui nasehat tepat dengan orang tua!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 5, 'Betapa cocoklah kebijaksanaan dengan tua-tua, dan pertimbangan serta nasehat dengan orang terhormat!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 6, 'Mahkota tua-tua ialah pengalaman yang banyak, dan ketakutan akan Tuhan adalah kebanggaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 7, 'Sembilan hal yang terbayang dalam hati kupuji bahagia, dan yang kesepuluh hendak kumasyhurkan dengan mulutku, yakni: orang yang bersukacita karena anak-anaknya, orang yang selama hidupnya boleh menyaksikan keruntuhan musuhnya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 8, 'berbahagialah orang yang hidup bersama isteri arif dan tidak membajak dengan lembu dan keledai sepasang; berbahagialah orang yang tidak tergelincuh karena lidahnya, dan yang tidak perlu mengabdi kepada orang yang tidak layak baginya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 9, 'berbahagialah orang yang menemukan pengertian, dan yang dapat berbicara kepada telinga orang yang mendengar-kan;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 10, 'betapa besarnya orang yang menemukan kebijaksanaan, tetapi tidak ada seorangpun melebihi orang yang takut akan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 11, 'Ketakutan akan Tuhan melampaui segala-galanya, siapa yang berpegang kepadanya, dengan apa gerangan dapat dibandingkan?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 13, 'Biar luka apa saja, asal bukan luka hati; biar keburukan apa saja, asal bukan keburukan perempuan;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 14, 'biar malapetaka apa saja, asal bukan malapetaka oleh pembenci; biar hukuman mana saja, asal bukan hukuman dari musuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 15, 'Tidak ada racun lebih hebat dari racun ular, dan tidak ada amarah lebih hebat dari amarah musuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 16, 'Lebih aku suka berumah bersama singa dan naga dari pada bersama dengan isteri yang jahat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 17, 'Kejahatan perempuan mengubah roman mukanya, dan menyuramkan air mukanya seolah-olah beruang betina.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 18, 'Suaminya duduk makan di tengah-tengah kawannya, dan mau tak mau mesti mengeluh dengan pahitnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 19, 'Setiap keburukan hanya kecil dibandingkan dengan keburukan perempuan, mudah-mudahan ia ditimpa nasib orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 20, 'Seperti jalan pasir yang naik bagi kaum tua, demikianlah isteri cerewet bagi suami pendiam.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 21, 'Jangan terjatuh karena kecantikan perempuan, dan jangan kaugairahkan perempuan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 22, 'Hanya amarah, teguran dan malu besar, apabila isteri mesti memberikan nafkah kepada suaminya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 23, 'Hati murung, muka suram dan luka hati disebabkan isteri jahat; jangan kendor dan lutut lumpuh, demikian isteri yang tidak membahagiakan suaminya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 24, 'Permulaan dosa dari perempuan dan karena dialah kita sekalian mesti mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 25, 'Jangan membiarkan air meluap, dan jangan pula membiarkan isteri yangjahat berleluasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 25, 26, 'Jika ia tidak berjalan menurut tuntunanmu, pisahkanlah ia dari tubuhmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 1, 'Berbahagialah suami dari isteri yang baik, dan panjang umurnya akan berlipat ganda.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 2, 'Isteri berbudi menggembirakan suaminya, yang dengan tenteram akan menggenapi umurnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 3, 'Isteri yang baik adalah bagian yang baik, yang dianugerahkan kepada orang yang takut akan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 4, 'Entah kaya, entah miskin giranglah hatinya, dan selalu rianglah roman muka-nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 5, 'Tiga hal ditakuti hatiku, dan karena yang keempat aku cemas, yakni: fitnah di kota dan huru-hara umum, dan tuduhan palsu: semuanya itu lebih buruk dari mati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 6, 'Tetapi inilah kepahitan hati dan kesedihan, apabila perempuan yang satu iri hati terhadap perempuan yang lain; dan cemeti lidah yang memberitahukannya di muka umum.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 7, 'Perempuan jahat sama seperti kuk lembu yang goyah, barangsiapa menyentuhnya seolah-olah menyentuh kalajengking.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 8, 'Apabila seorang perempuan mabuk maka orang marah sekali, dan malunya tidak dapat disembunyikannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 9, 'Perempuan sundal dikenal pada gerak-gerik matanya, dan diketahui pada bulu matanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 10, 'Hendaklah ketat menjagai anak perempuan yang tak tabu malu, agar ia jangan mendapat kesempatan yang disalahgunakannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 11, 'Waspadalah terhadap yang panjang mata, dan janganlah kaget pabila ia bersalah terhadapmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 12, 'Seperti pengembara yang kehausan ia membuka mulutnya, dan meminum air apapun yang didapatinya; duduklah ia di depan setiap pasak, dan membuka bumbungnya bagi anak panah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 13, 'Keelokan isteri menyenangkan suaminya, tetapi kepandaiannya membesar-kan hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 14, 'Suatu anugerah dari Tuhan ialah isteri pendiam, dan tak terbayarlah pendidikannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 15, 'Karunia berlipat dualah seorang isteri yang sopan, dan perempuan murni tidak ada imbangannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 16, 'Laksana matahari yang terbit di atas pegunungan Tuhan, emikianlah keelokan isteri baik di tengah rumah tangga yang rapih.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 17, 'Bagaikan pelita yang bercahaya di atas kaki yang suci, demikianpun kecantikan paras di atas tubuh tegap.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 18, 'Seperti tiang emas di atas alas perak, demikianlah betis yang gagah di atas tumit yang kukuh kuat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 28, 'Atas dua hal hatiku merasa sedih, dan karena yang ketiga aku didatangi kesal hati, : yaitu: prajurit yang kekurangan karena miskin, dan orang arif yang dinistakan orang; orang yang dari kesalehan berbelok kepada dosa, teruntukkanlah dia oleh Tuhan bagi pedang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 26, 29, 'Sukar benar seorang pedagang terluput dari kesalahan, dan seorang saudagar tak akan dinyatakan bersih dari dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 1, 'Karena uang sudah banyak orang berdosa, dan barang siapa berdaya upaya menjadi kaya, memalingkan muka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 2, 'Antara rapatan dua batu tertancap pasak, dan demikianpun dosa menyisip antara jual dan beli.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 3, 'Kalau ketakutan akan Tuhan tidak dikukuhi orang, niscaya cepat dan segera hancurlah rumahnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 4, 'Kalau ayakan digoyang-goyangkan maka sampahlah yang tinggal, demikianpun keburukan manusia tinggal dalam bicaranya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 5, 'Perapian menguji periuk belanga penjunan, dan ujian manusia terletak dalaiti bicaranya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 6, 'Nilai ladang ditampakkan oleh buah pohon yang tumbuh di situ, demikian pula bicara orang menyatakan isi hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 7, 'Jangan memuji seseorang sebelum ia bicara, sebab justru itulah batu ujian manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 8, 'Kalau keadilan kaukejar, niscaya akan kaudapat, dan bagaikan pakaian kebesaran akan kaukenakan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 9, 'Burung berkawan dengan yang sejenis, demikianpun kebenaran kembali kepada yang melakukannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 10, 'Seekor singa mengincar mangsanya, dan demikian dosa mengincar mereka yang melakukannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 11, 'Bicara orang takwa adalah kebijaksanaan selalu, tetapi si tolol beralih seperti rembulan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 12, 'Di kalangan kaum tumpul tunggulah kesempatan untuk pergi, tetapi hendaklah tetap tinggal di kalangan orang-orang yang berpikir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 13, 'Omongan orang bodoh suatu kengerian benar, dan ketawanya di tengah keriangan berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 14, 'Cakap orang yang banyak bersumpah meremangkan bulu roma, dan pertengkaran mereka menyumbat telinga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 15, 'Pertikaian orang yang congkak menumpahkan darah, dan caci maki mereka keji untuk didengar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 16, 'Barangsiapa membuka rahasia melenyapkan kepercayaan, dan tidak mendapat kawan lagi sesuai dengan keinginan hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 17, 'Hormatilah sahabat dan hendaklah setia kepadanya, tetapi jikalau rahasianya sudah kaubuka, janganlah mengejarnya lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 18, 'Sebab seperti seseorang membinasakan musuhnya, demikian pula telah kaurusakkan persahabatan sesamamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 19, 'Sama seperti seekor burung kaulepaskan dari tanganmu, demikian telah kaulepaskan kawanmu dan tidak akan kautangkap kembali.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 20, 'Jangan kejar sebab ia sudah jauh, dan telah lari seperti kambing hutan dari jaring,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 21, 'Sebab luka masih dapat dibalut, dan setelah menghina, orang masih dapat berdamai, tetapi tidak ada harapan lagi bagi orang yang membuka rahasia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 22, 'Barangsiapa mengejamkan mata merencanakan yang jahat, dan tidak ada seorangpun dapat menahan dia dari padanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 23, 'Di muka matamu ia bermulut manis, dan mengagumi segala ucapanmu, tetapi kemudian ia akan membalik perkataannya, dan ucapanmu dijadikannya batu sandungan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 24, 'Banyak yang kubenci, tetapi tidak ada sesuatupun yang kubenci seperti orang macam itu, dan iapun dibenci oleh Tuhan juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 25, 'Barangsiapa melemparkan sebuah batu ke atas melemparkannya ke atas kepalanya sendiri, dan pukulan cedera menyebabkan luka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 26, 'Orang yang menggali pelubang akan terperosok ke dalamhya, dan yang memasang jaring akan terjerat sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 27, 'Kejahatan yang dilakukan orang akan berguling atas dirinya sendiri, dan ia tidak tahu dari mana datangnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 28, 'Cemooh dan caci maki untuk orang yangcongkak, dan hukuman mengadang bagaikan singa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 29, 'Orang yang bergembira atas kebinasaan orang takwa terjerat dalam jaring, dan sengsara akan memakannya habis sebelum ia meninggal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 27, 30, 'Dendam kesumat dan amarahpun sangat mengerikan juga, dan orang berdosalah yang dikuasainya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 1, 'Barangsiapa membalas dendam akan dibalas oleh Tuhan. Tuhan dengan saksama mengindahkan segala dosanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 2, 'Ampunilah kesalahan kepada sesama orang, niscaya dosa-dosamupun akan dihapus juga, jika engkau berdoa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 3, 'Bagaimana gerangan orang dapat memohon penyembuhan pada Tuhan, jika ia menyimpan amarah kepada sesama manusia?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 4, 'Bolehkah ia berdoa karena dosa-dosanya, kalau tidak menaruh belas kasihan terhadap seorang manusia yang sama dengannya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 5, 'Meskipun ia hanya daging belaka, namun ia menaruh dendam kesumat, siapa gerangan akan memulihkan dosa-dosanya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 6, 'Ingatlah akan akhir hidup dan hentikanlah permusuhan, ingatlah akan kebusukan serta maut dan hendaklah setia kepada segala perintah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 7, 'Ingatlah akan perintah-perintah dan jangan mendendami sesama manusia, hendaklah ingat akan perjanjian dari Yang Mahatinggi, lalu ampunilah kesalahannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 8, 'Jauhilah pertikaian, maka dosa kaukurangkan, sebab orang yang panas hati mengobar-ngobarkan pertikaian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 9, 'Orang yang berdosa mengganggu orang-orang yang bersahabat, dan melontarkan permusuhan di antara orang-orang yang hidup dengan damai.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 10, 'Api menyala sesuai dengan bahan bakarnya, dan pertikaian berkobar sesuai dengan kekerasan hati; amarah manusia adalah sepadan dengan kekuasaannya, dan sekadar kekayaannya hebatlah geramnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 11, 'Pertengkaran yang tiba-tiba muncul menyalakan api, dan pertikaian yang tergopoh-gopoh menumpahkan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 12, 'Jika bunga api kautiupi, maka bernyala-nyalalah ia, sedangkan jika kauludahi, niscaya ia padam; namun kedua-duanya keluar dari mulutmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 13, 'Terkutuklah pemfitnah dan lidah bercabang, sebab banyak orang yang hidup dengan tenteram telah dibinasa-kannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 14, 'Orang yang panjang lidah sudah menggoncangkan banyak orang dan mengusir mereka dari bangsa ke bangsa; kota-kota yang kukuh kuat telah dihancurkannya dan dirobohkannya rumah pembesar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 15, 'Orang yang panjang lidah sudah menceraikan isteri yang berbudi, dan hasil pekerjaannya dirampas olehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 16, 'Barangsiapa menghiraukannya tidak mendapat istirahat, dan tidak dapat hidup dengan tenteram.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 17, 'Dera cambuk menyebabkan bilur, tetapi dera lidah mematahkan tulang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 18, 'Sudah banyak yang tewas karena mata pedang, tetapi belum sebanyak yang gugur karena lidah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 19, 'Berbahagialah orang yang terlindung terhadap lidah dan tidak tertimpa oleh geramnya; dan juga berbahagia orang yang tidak perlu memikul kuknya dan tidak terikat dengan belenggu-belenggunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 20, 'Sebab kuknya adalah kuk besi, dan dari perunggu belenggu-belenggunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 21, 'Kematian ngerilah kematian karena lidah, bahkan dunia orang mati lebih menguntungkan dari pada dia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 22, 'Orang takwa tidak akan dikuasai olehnya, dan tidak dihanguskan oleh nyala apinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 23, 'Orang yang meninggalkan Tuhan akan jatuh menjadi korbannya, dan di dalam mereka ia akan membakar dengan tak kunjung padam. Bagaikan singa akan dikirimkan kepada mereka, dan mereka dicabik-cabik olehnya seperti oleh harimau akar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 24, 'Awaslah, hendaklah kaupagari milikmu dengan onak, dan menguncikan perak serta emasmu;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 25, 'buatlah pula timbangan dan batu timbangan untuk perkataanmu, dan pintu dan palang pintu bagi mulutmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 28, 26, 'Waspadalah, jangan sanipai engkau tergelincuh karena lidah, kalau tidak maka engkau akan jatuh binasa di depan yang mengadang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 1, 'Barangsiapa menaruh belas kasihan memberi pinjam kepada sesamanya, dan orang yang mengulas tangannya memenuhi perintah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 2, 'Pinjamkanlah kepada sesamamu di kala ia kekurangan, tetapi kembalikanlah kepada sesama tepat pada waktunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 3, 'Teguhkanlah janjimu dan hendaklah setia kepadanya, niscaya senantiasa engkaupun akan mendapat apa yang kaubutuhkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 4, 'Banyak orang menganggap pinjaman seolah-olah barang terdapat, dan begitu mempersusah para penolongnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 5, 'Sampai menerima orang menciumi tangan, dan demi uang sesamanya akan berbicara dengan rendah hati; tetapi pada saat mesti melunasi ia menangguhkan saja, dan akan membayar dengan kata-kata yang buruk dan ia menyalahkan keadaan waktu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 6, 'Jika pemberi pinjam mendesak, dengan susah separuhnya ia dapat kembali, dan itu bahkan dapat dianggapnya sebagai keuntungan. Kalau tidak, maka peminjam telah merampas uangnya, dan dengan tak semena-mena menjadikannya musuhnya. Dengan kutuk dan caci maki ia membalas, dan sebagai pengganti hormat mengembalikan nista.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 7, 'Banyak orang enggan meminjamkan bukan karena kejahatannya, tetapi karena kuatir akan dirampas dengan tak semena-mena.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 8, 'Namun demikian hendaklah sabar terhadap orang yang miskin, janganlah mempertangguhkan dermamu kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 9, 'Demi perintah tolonglah orang miskin, dan mengingat kekurangannya jangan menyuruh dia pergi dengan tangan hampa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 10, 'Biar perakmu hilang karena saudara dan kawan; jangan kaubiarkan berkarat dibawah batu sampai jatuh binasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 11, 'Gunakanlah harta milikmu menurut perintah dari Yang Mahatinggi, niscaya lebih berfaedahlah itu bagimu dari pada emas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 12, 'Kuncikanlah segenap dermamu dalam perbendaharaanmu, maka dari segala malapetaka engkau akan diluputkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 13, 'Maka dermamu akan berperang untukmu dengan musuh lebih baik dari pada perisai kuat dan tombak berat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 14, 'Orang yang baik budi menanggung sesama manusia, tetapi oleh yang telah kehilangan rasa malu ditinggalkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 15, 'Jangan melupakan segala jasa si penanggung, sebab demi engkau ia telah menyerahkan nyawanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 16, 'Barang penanggung diboroskan orang berdosa,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 17, 'dan orang yang tak tahu terima kasih melupakan penolongnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 18, 'Menjadi penanggung sudah meruntuhkan banyak orang yang berada, dan diombang-ambingkannya seperti gelombang laut; orang yang berkuasa telah diusirnya dari tanah airnya, sehingga mereka mesti mengembara di tengah-tengah bangsa-bangsa asing.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 19, 'Orang berdosa yang bergesa-gesa untuk menanggung dan memburu-buru keuntungan, bergegas-gegas menuju hukuman.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 20, 'Tolonglah sesamamu sesuai dengan kemampuanmu, tetapi hendaklah waspada supaya jangan sampai terjatuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 21, 'Kebutuhan pokok untuk hidup ialah air dan makanan serta pakaian dan perumahan untuk menudungi ketelanjangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 22, 'Hidup seorang miskin di bawah pondok dari papan adalah lebih baik dari pada sedap-sedapan yang mewah di rumah orang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 23, 'Baik jika banyak maupun kalau sedikit, hendaklah sejuk hati, maka takkan kaudengar comelan karena merantau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 24, 'Buruklah kehidupan orang yang mesti pergi dari rumah ke rumah, sebab tempat merantau engkau tidak boleh membuka mulut.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 25, 'Sebab engkau hanya seorang pendatang dan memberi minum tanpa mendapat terima kasih, dan di samping itu mesti mendengar perkataan yang menyakiti hati ini:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 26, 'Kemari, hai perantau, siapkanlah meja, dan kalau mempunyai apa-apa, berilah aku makan!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 27, 'Silakan pergi, hai perantau, guna orang terhormat, saudaraku datang bertamu padaku; aku membutuhkan rumahku,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 29, 28, 'Sungguh beratlah semuanya itu bagi orang yang halus perasaan-nya, yaitu: dicaci maki karena merantau dan dicemoohkan sebagai orang yang berhutang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 1, 'Barangsiapa cinta kepada anaknya menyediakan cambuk baginya, supaya akhirnya ia mendapatkan sukacita karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 2, 'Barangsiapa mendidik anaknya dengan tertib akan beruntung karenanya, dan di kalangan para kenalan boleh membanggakannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 3, 'Orang yang mengajar anaknya menjadikan musuhnya iri hati dan di depan teman kawan dapat bersukaria karena dia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 4, 'Meskipun ayahnya meninggal, namun seolah-olah tidak mati, sebab gambarnya telah ditinggalkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 5, 'Selama masih hidup ia dapat memandang anaknya dengan sukacita, dan waktu meninggal tidak berdukacita.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 6, 'la meninggalkan anaknya sebagai pembalas dendam kepada musuh, dan untuk teman kawan ditinggalkannya seseorang yang balas budi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 7, 'Barangsiapa memanja-manjakan anak membalut luka-lukanya sendiri, dan pada setiap teriakan gemetarlah batinnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 8, 'Kuda yang tak dijinakkan menjadi degil, dan anak yang tak terkekang menjadi terlanjur-lanjur akhirnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 9, 'Timanglah anak maka engkau akan dikejutkannya, berguraulah dengannya, niscaya engkau disedihkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 10, 'Jangan ketawa sama dia, agar engkau jangan sedih bersama dengannya, dan supaya jangan sampai mengeritkan gigi akhirnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 11, 'Jangan ia kauberi kebebasan di masa mudanya, dan matamu jangan kaututup terhadap kebodohannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 12, 'Tuhdukkanlah kuduknya di masa kecilnya, dan siksalah pinggangnya waktu masih kecil, kalau tidak ia menjadi degil dan tidak taat kepadamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 13, 'Didiklah anakmu dengan tertib dan suruhlah ia kerja, supaya engkau jangan sakit hati karena keangkaraannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 14, 'Lebih baiklah orang yang miskin tapi sehat lagi kuat dari pada orang kaya tapi yang badannya bersakit-sakit.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 15, 'Sehat dan walafiat lebih baik dari segala emas, dan badan tegap lebih baik dari pada kemewahan yang tidak terukur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 16, 'Tiada kekayaan melebihi kesehatan badan, dan tiada kesukaan melebihi keriangan hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 17, 'Lebih baik mati dari pada hidup yang pahit getir, dan lebih baiklah istirahat kekal dari pada sengsara tetap.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 18, 'Seperti makanan enak-enak yang disajikan kepada mulut terkatup, demikianlah pesajian yang ditempatkan di atas kubur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 19, 'Apa gunanya pesajian bagi berhala, yang tidak memakannya atau menghirup? DemikianpUn halnya seseorang yang dikejar oleh Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 20, 'la memandang dengan matanya lalu mengeluh, sama seperti seorang kebiri yang memeluk seorang gadis lalu mengeluh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 21, 'Jangan menyerahkan diri kepada kesedihan, dan jangan pula menyiksa dirimu dengan disengaja.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 22, 'Keriangan hati merupakan kehidupan bagi manusia, dan umur hidupnya diperpanjang oleh sukacitanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 23, 'Legakanlah dadamu dan hiburkanlah hatimu, dan jauhkanlah segala kemasygulan. Sebab banyak orang sudah dibinasakan oleh kesedihannya, dan kesedihan hati tidak ada gunanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 24, 'Iri hati dan sakit hati memperpendek hidup, dan kesusahan membuat orang menjadi tua sebelum waktunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 30, 25, 'Hati yang riang dengan girang makannya, dan makanannya selamat baginya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 1, 'Berjaga-jaga karena kekayaan memperkurus badan, dan kesusahan karenanya mengenyahkan tidur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 2, 'Kesusahan karena naikah tidak membiarkan orang mengantuk, dan tidur dihalaukan sakit keras.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 3, 'Orang kaya bersusah payah sementara hartanya bertambah, dan apabila berhenti ia limpah mewah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 4, 'Sebaliknya, orang miskin bersusah payah oleh sebab nafkahnya berkurang, dan kalau berhenti ia serba kekurangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 5, 'Barangsiapa gila emas tidak terlepas dari dosa, dan orang yang memburu-buru uang akan tersesat karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 6, 'Banyak orang telah terjatuh karena emas dan mesti menghadapi kebinasaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 7, 'Sebab emas menjadi batu sandungan bagi mereka yang mendewakannya, dan setiap orang tolol tertangkap olehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 8, 'Berbahagialah orang kaya yang kedapatan tidak bersalah, dan yang tidak mengejar emas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 9, 'Siapa gerangan orangnya, maka mesti kita puji bahagia, sebab sesuatu yang ajaib dilakukannya di tengah-tengah bangsanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 10, 'Siapa gerangan yang tahan uji terhadapnya dan menyatakan diri sempurna? Itu sungguh menjadi suatu kebanggaan baginya! Siapa orangnya yang dapat bersalah tetapi tidak bersalah juga, yang dapat berbuat jahat tetapi tidak melakukannya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 11, 'Maka itu kesejahteraannya terjamin, dan amalannya akan diwartakan jemaah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 12, 'Adakah engkau duduk di meja yang melimpah-limpah makanannya? Janganlah membuka mulut karenanya. Jangan berkata: "Betapa melimpah-limpah ia."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 13, 'Ingatlah bahwa mata rakus buruk adanya. Dijadikankah sesuatupun lebih buruk dari padanya? Karenanya ia mencucurkan air mata pada setiap muka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 14, 'Janganlah mengulurkan tangan ke mana saja mata tertuju, supaya engkau jangan bertemu dengan orang lain di pinggan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 15, 'Hendaklah menilai sesamamu sesuai dengan dirimu sendiri, dan dalam segala sesuatunya hendaklah berpikir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 16, 'Sebagaimana sopan bagi manusia, hendaklah makan apa saja dihidangkan kepadamu, Janganlah rakus, nanti sampai dibenci.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 17, 'Demi adat hendaklah berhenti sebagai yang pertama, janganlah lahap, nanti mengecilkan hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 18, 'Kalau duduk di tengah-tengah banyak orang, janganlah mengulurkan tangan sebelum orang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 19, 'Hanya sedikit sajalah yang mencukupi orang yang tahu adat, dan di atas pembaringannya ia tidak sesak nafas.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 20, 'Makan sedikit saja disertai tidur nyenyak, pagi-pagi orang bangun dan segarlah rasanya. Tidak dapat tidur, muntah dan sakit perut, itulah bagian orang yang lahap.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 21, 'Jika engkau terpaksa makan terlalu banyak, bangunlah, pergi memuntah, maka engkau akan merasa lega.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 22, 'Dengarkanlah aku, hai anakku, jangan abaikan, niscaya perkataanku kaupahami akhirnya. Dalam segala tingkah laku hendaklah bersahaja, maka engkau tidak akan ditimpa penyakit.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 23, 'Orang yang dengan tangan murah menjamu akan dipuji orang, dan pujian tentang kemurahannya tak akan kunjung berhenti.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 24, 'Tetapi orang yang dengan kikir menjamu akan dicela di kota, dan tepatlah obrolan tentang kekikirannya itu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 25, 'Janganlah gagah berani dalam hal minum anggur, sebab sudah banyak orang dibinasakan air anggur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 26, 'Kekerasan baja diuji oleh perapian, demikianpun anggur menguji hati dalam pertandingan para pelagak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 27, 'Air anggur merupakan kehidupan bagi manusia, asal saja diminumnya dengan ukuran. Macam apa kehidupan dimiliki manusia kalau tidak ada anggur baginya? Ia diciptakan untuk menggembirakan hati manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 28, 'Sebaliknya, air anggur menjadi kepahitan hati kalau diminum dengan keterlaluan, dengan pedas hati dan pertikaian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 30, 'Orang bodoh yang mabuk menjadi marah akan kebinasaannya sendiri, mengurangkan tenaganya dan menimpakan luka kepada dirinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 31, 31, 'Dalam pesta anggur jangan mencela kawanmu, janganlah ia kauhina dalam keriangannya; jangan kaukatakan suatu kata nista kepadanya, dan jangan mengganggu dia dengan menuntut sesuatu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 1, 'Engkaukah yang dijadikan OM pemimpin perjamuan? Jangan meninggikan diri! Di kalangan tetamu jadilah seperti seorang di antara mereka. Layanilah mereka dahulu, kemudian barulah engkaupun boleh duduk juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 2, 'Setelah semua kewajibanmu kaupenuhi barulah duduk di tempatmu, sehingga dapat bersuka hati karena mereka serta menerima mahkota sebagai pengganti urusanmu yang baik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 3, 'Berbicaralah, hai tua-tua, sebab memang sewajarnya, tetapi dengan pengetahuan yang saksama dan tanpa mengganggu musiknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 4, 'Sementara sebuah lagu dibawakan jangan bertutur, dan jangan main bijak pada waktu yang tidak tepat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 5, 'Suatu meterai manikam pada perhiasan emas, demikianlah sebuah lagu dengan musiknya dalam pesta anggur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 6, 'Laksana meterai zamrud dalam rangka emas, demikianpun lagu bersama musiknya dengan air anggur yang manis.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 7, 'Hai pemuda, berbicaralah hanya kalau sungguh perlu, karena orang bertanya dan paling-paling dua kali!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 8, 'Hendaknya singkat dan katakanlah banyak dengan kata sedikit, dan hendaklah seperti orang yang tahu tapi pendiam.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 9, 'Di tengah-tengah para pemuka jangan berlaku seolah-olah setara, dan manakala orang lain berbicara jangan berkelakar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 10, 'Halilintar mendahului guntur, dan kerelaan mendahului orang yang sopan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 11, 'Manakala tiba waktunya jangan menunda-nunda, pulanglah ke rumah dan janganlah berlambat-lambat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 12, 'Senangkanlah dirimu di sana dan berbuatlah sesuka hatimu, hanya jangan berdosa dengan kata yang congkak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 13, 'Tetapi terlebih pujilah Penciptamu, yang mengenyangkan dirimu dengan segala anugerah-Nya yang baik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 14, 'Barangsiapa takut akan Tuhan menerima siasat-Nya, dan orang yang pagi-pagi menghadap Dia mendapat karunia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 15, 'Barangsiapa asyik menelaah hukum Taurat akan dikenyangkan dengannya, tetapi orang munafik akan tersandung padanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 16, 'Orang yang takut akan Tuhan akan menemukan paham tepat, lalu bagaikan cahaya menyinarkan kebajikannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 17, 'Orang berdosa menolak teguran, dan akan menemui dalihnya untuk menuruti kehendak sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 18, 'Jangan berbuat apapun tanpa timbang-menimbang, supaya setelah mengerjakan sesuatu jangan menyesal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 20, 'Jangan menempuh jalan yang jendal-jendul, nanti engkau tersandung karena batu-batunya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 21, 'Jangan merasa diri aman terhadap penyamun di jalan,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 22, 'dan di lorong-lorongmu hendaklah berjaga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 23, 'Hendaklah waspada dalam segala pekerjaanmu, sebab demikianlah kaupenuhi segala perintah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 32, 24, 'Barangsiapa percaya akan hukum Taurat pasti memperhatikan segala perintah, dan orang yang percaya pada Tuhan takkan ditimpa kerugian apapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 1, 'Orang yang takut akan Tuhan OO tidak kena malapetaka, sebaliknya bahkan di dalam pencobaan ia terus diluputkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 2, 'Orang bijak tidak membenci hukum Taurat, tetapi orang yang munafik terhadapnya merupakan sebuah perahu dalam taufan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 3, 'Orang yang berpengertian akan percaya pada hukum Taurat, dan Taurat adalah kepercayaannya sama seperti firman dari undi suci.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 4, 'Siapkanlah pidatomu maka akan didengarkan, susunlah wejanganmu dahulu dan kemudian hendaklah menjawab.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 5, 'Batin orang bodoh sama seperti roda kereta, dan pikiran-pikirannya merupakan poros yang berputar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 6, 'Kawan yang suka mencemoohkan adalah seperti kuda yang gasang, ia meringkik di bawah setiap penunggang. Kebijaksanaan Tuhan dalam ciptaan-Nya', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 7, 'Mengapa hari yang satu melebihi yang lain, walaupun sepanjang tahun cahaya datang dari matahari yang sama?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 8, 'Karena pikiran Tuhan diperbedakan, dan Dialah yang memperlainkan musim dan hari raya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 9, 'Beberapa di antaranya ditinggikan serta disucikan oleh-Nya, sedangkan yang lain-lain dijadikan-Nya hari biasa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 10, 'Segala manusia berasal dari tanah liat, dan Adam diciptakan dari tanah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 11, 'Namun demikian dalam kebijaksanaan-Nya yang besar Tuhan membedakan mereka, dan menetapkan pelbagai jalan bagi mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 12, 'Beberapa di antaranya diberkati dan ditinggikan Tuhan, dan Iain-lain lagi disucikan oleh-Nya dan didekatkan kepada diri-Nya, sedangkan beberapa dikutuk serta direndahkan, bahkan diusir dari tempat tinggalnya oleh Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 13, 'Seperti tanah liat di tangan penjunan, sebab segenap tingkah laku-Nya sesuai dengan perkenanan-Nya demikianlah manusia di tangan Penciptanya untuk memberikan kepada mereka menurut keputusan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 14, 'Yang berhadapan dengan yang jahat ialah yang baik, dan kehidupan berhadapan dengan maut. Demikianpun orang yang berdosa berhadapan dengan orang yang takwa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 15, 'Pandanglah semua buatan Yang Mahatinggi: semuanya berpasang-pasang, yang satu berhadapan dengan yang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 16, 'Aku sendiri sebagai yang terakhir berjaga-jaga, seperti orang yang memungut di belakang pemetik buah anggur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 17, 'Karena berkat Tuhan aku tampil kedepan, dan seperti pemetik buah anggur kuisi pasuku.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 18, 'Sesungguhnya aku tidak melulu bersusah payah guna diriku sendiri, melainkan guna semua orang yang mencari pengajaran.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 19, 'Hai para pembesar umat, dengarkanlah aku, hendaklah memperhatikan, hai para pemimpin jemaah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 20, 'Anak, isteri, saudara atau kawan jangan kaubiarkan berkuasa atas dirimu sepanjang umur hidupmu. Jangan menyerankan harta milikmu kepada orang lain, nanti engkau mesti menyesal dan memintanya kembali.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 21, 'Selama engkau masih hidup dan masih ada nafas di dalam dirimu jangan mengalihkan tempatmu kepada siapapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 22, 'Sebab lebih baiklah anak-anakmu meminta kepadamu dari pada engkau sendiri mesti mengindahkan tangan anak-anakmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 23, 'Hendaklah berkuasa dalam segala urusanmu, dan jangan menodai nama baikmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 24, 'Pada saat sudah genaplah umur hidupmu, pada hari ajalmu bagikanlah warisanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 25, 'Rumput kering, tongkat dan beban bagi keledai, roti, siasat dan kerja bagi hamba.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 26, 'Suruhlah budakmu bekerja, maka kaudapat istirahat; kalau tangannya kaubiarkan bermalas, niscaya ia mencari kemerdekaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 27, 'Kuk dan kekang membungkukkan tengkuk, dan aniaya dan siksa adalah serasi dehgan hamba yang jahat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 28, 'Bebankanlah pekeijaan kepada budakmu, sehingga ia tidak menganggur, sebab pengangguran mengajar banyak kejahatan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 29, 'Hendaklah menyuruh dia bekerja sebagaimana mestinya, dan kalau ia tidak menurut, beratkanlah rantainya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 30, 'Tetapi jangan melampaui batas terhadap siapapun, dan jangan berbuat apa-apa tanpa pertimbangan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 31, 'Jika engkau mempunyai seorang hamba, hendaknya ia seperti dirimu sendiri, sebab dengan darahmu sendiri telah kauperoleh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 32, 'Kalau ada seorang hamba padamu, hendaklah kauperlakukan seperti saudara, sebab ia kaubutuhkan seperti dirimu sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 33, 33, 'Kalau ia kauperlakukan dengan buruk, lalu ia melarikan dirinya; di mana gerangan akan kaucari? Jangan percaya pada mimpi', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 1, 'Harapan sia-sia yang memper dayakan bagi orang tumpul adanya, dan mimpi hanya membingungkan orang yang pandir.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 2, 'Sama seperti orang yang menangkap bayangan dan memburu-buru angin adalah orang yang mengukuhi mimpi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 3, 'Penglihatan dalam mimpi adalah suatu cerminan: di depan roman muka nampaklah gambarannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 4, 'Bagaimana dari yang najis dapat datang yang tahir, dan bagaimana dari dusta dapat lahir kebenaran?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 5, 'Tenung, nujum dan mimpi adalah sia-sia belaka, dan sama seperti yang dibayangkan hati wanita yang sedang bersalih.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 6, 'Apabila tidak dikirim dari Yang Mahatinggi sebagai kunjungannya, jangan menaruh perhatian kepadanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 7, 'Mimpi sudah menyesatkan banyak orang, dan yang percaya kepadanya tergelincuh karenanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 8, 'Sebaliknya hukum Taurat akan dipenuhi tanpa tipu daya, dan kebijaksanaan di mulut yang dapat dipercaya menjadi sempurna. Percayalah pada Tuhan', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 9, 'Orang yang banyak perjalanannya, banyak pula pengetahuannya, dan yang banyak pengalamannya mengucapkan pengertian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 10, 'Qrang yang tidak berpengalaman hanya mengetahui sedikit, sedangkan orang yang banyak perjalanannya mengumpulkan kecerdikan besar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 11, 'Banyaklah yang telah kulihat dalam segala perjalananku, dan aku mengerti lebih banyak dari pada dapat kukatakan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 12, 'Kerapkali aku di dalam bahaya maut, tetapi diselamatkan dari padanya berkat pengalamanku itu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 13, 'Roh orang yang takut akan Tuhan akan hidup, sebab harapannya tertaruh pada Dia yang menyelamatkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 14, 'Barangsiapa takut akan Tuhan tidak kuatir terhadap apapun, dan tidak menaruh ketakutan sebab Tuhanlah pengharapannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 15, 'Berbahagialah orang yang takut akan Tuhan. Kepada siapakah ia berpegang dan siapakah sandarannya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 16, 'Mata Tuhan tertuju kepada orang yang cinta kepada-Nya. Tuhan menjadi perisai kuat dan sandaran yang kokoh, naungan terhadap angin yang panas dan perlindungan terhadap panas terik siang hari, penjagaan sehingga tidak tersandung dan pertolongan sehingga tidaklah runtuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 17, 'Tuhan menegakkan hati dan menerangi mata, memberi kesembuhan, hidup serta berkat. Korban gadungan', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 18, 'Orang yang mempersembahkan korban dari barang yang diperoleh dengan tidak adil hanya mencemoohkan; memang persembahan kaum fasik tidak diperkenan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 19, 'Yang Mahatinggi tidak berkenan pada persembahan orang fasik dan dosa tidak diampuni-Nya karena korban berlimpah-limpah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 20, 'Sama seperti orang yang menyembelih anak di depan mata ayahnya, demikianlah orang yang mempersembahkan korban dari milik orang miskin.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 21, 'Roti orang yang kekurangan adalah kehidupan bagi kaum miskin; barangsiapa merampasnya mengisap darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 22, 'Merampas nafkah sesamanya sama saja dengan membunuhnya, dan barangsiapa menahan upah buruhnya menumpahkan darah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 23, 'Apabila yang satu membangun dan yang lain merombak, apa gerangan hasil mereka kecuali jerih payah?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 24, 'Kalau yang satu berdoa dan yang lain mengutuk, suara siapa gerangan mesti didengarkan Tuhan?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 25, 'Apabila seseorang membasuh dirinya habis menyentuh mayat, lalu menyentuhnya lagi, apa gerangan gunanya pembasuhan baginya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 34, 26, 'Demikianpun halnya seseorang yang berpuasa demi dosa-dosanya, lalu pergi melakukan yang sama pula! Siapakah akan mendengarkan doanya, dan untuk apa ia merendahkan dirinya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 1, 'Barangsiapa memenuhi hukum Taurat mempersembahkan banyak korban, dan orang yang memperhatikan segala perintah menyampaikan korban keselamatan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 2, 'Orang yang membalas kebaikan mempersembahkan korban sajian dan yang memberikan derma menyampaikan korban syukur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 3, 'Yang direlai oleh Tuhan ialah menjauhi kejahatan, dan menolak kelaliman merupakan korban penghapus dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 4, 'Jangan tampil di hadirat Tuhan dengan tangan yang kosong, sebab semuanya wajib menurut perintah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 5, 'Persembahan orang jujur melemaki mezbah, dan harumnya sampai ke hadapan Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 6, 'Tuhan berkenan kepada korban orang benar, dan ingatannya tidak akan dilupakan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 7, 'Muliakanlah Tuhan dengan kemurahan, dan buah bungaran di tanganmu janganlah kausedikitkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 8, 'Sertakanlah muka yang riang dengan segala pemberianmu, dan bagian sepersepuluh hendaklah kaukuduskan dengan suka hati.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 9, 'Berikanlah kepada Yang Mahatinggi berpadanan dengan apa yang la berikan kepadamu, dengan murah hati dan sesuai dengan hasil tanganmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 10, 'Sebab Dia itu Tuhan pembalas, dan engkau akan dibalas-Nya dengan tujuh lipat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 11, 'Jangan mencoba menyuap Tuhan, sebab tidak diterima-Nya, dan janganlah percaya pada korban kelaliman!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 12, 'Sebab Tuhan adalah Hakim, yang tidak memihak.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 13, 'la tidak memihak dalam perkara orang miskin, tetapi doa orang yang terjepit didengarkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 14, 'Jeritan yatim piatu tidak diabaikan-Nya, ataupun jeritan janda yang mencurahkan permohonannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 15, 'Bukankah pipi seorang janda bercucuran air mata, dan tidakkah ia menjerit karena orang yang menyebabkannya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 16, 'Tuhan berkenan kepada siapa yang dengan sebulat hati berbakti kepada-Nya, dan doanya naik sampai ke awan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 17, 'Doa orang miskin menembusi awan, dan ia tidak akan terhibur sampai mencapai tujuannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 18, 'la tidak berhenti hingga Yang Mahatinggi memandangnya, dan memberikan hak kepada orang benar dan menjalankan pengadilan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 19, 'Tuhanpun tidak akan berayal pula, dan tidak sabarlah la terhadap orang lalim;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 20, 'sampai pinggang orang yang tidak tahu belas kasihan diremukkan-Nya, dan bangsa-bangsa dibalas-Nya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 21, 'sampai gerombolan orang pongah dicabut-Nya, dan tongkat kuasa kaum durjana dipatahkan-Nya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 22, 'sampai Ia membalas orang sekedar perbuatannya dan pekerjaan manusia setimpal dengan rancangannya;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 23, 'sampai hak umat-Nya dipulihkan-Nya, dan hati umat-Nya digembirakan dengan belas kasihan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 35, 24, 'Belas kasihan memang sangat tepat pada waktu kesusahannya, bagaikan mega mendung di musim kemarau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 1, 'Kasihanilah kami hai Penguasa, Allah semesta alam, dan pandangilah kami dan curahkanlah kedahsyatan-Mu ke atas segala bangsa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 2, 'Angkatlah tangan-Mu terhadap segenap bangsa asing, supaya kekuasaan-Mu dilihat oleh mereka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 3, 'Seperti Engkau telah menyatakan diri-Mu kudus di dalam kami di hadapan mata mereka, demikianpun hendaklah memuliakan diri-Mu di dalam mereka di depan mata kami.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 4, 'Maka Engkau akan diketahui mereka seperti telah kami ketahui, bahwa tidak ada Allah kecuali Engkau, ya Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 5, 'Hendaklah membaharui tanda dan mengulang mujizat, memuliakan tangan-Mu serta lengan kanan-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 6, 'Bangkitkanlah murka-Mu dan curahkanlah geram-Mu, binasakanlah lawan dan basmilah musuh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 7, 'Percepatlah waktunya dan ingatlah sumpah-Mu, supaya orang memuji segala perbuatan-Mu yang gagah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 8, 'Semoga orang yang terluput ditelan murka yang menyala, dan semua penindas umat-Mu tertimpa kebinasaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 9, 'Hendaklah menghancurkan kepala para penguasa musuh, yang berkata: "Selain dari kita tidak ada seorangpun."', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 10, 'Sudilah mengumpulkan segala suku Yakub serta mengembalikan kepada mereka tanah pusakanya seperti sediakala.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 11, 'Kasihanilah umat yang disebut menurut nama-Mu, yaitu Israel yang telah Kausamakan dengan anak sulung.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 12, 'Kasihanilah kota-Mu yang kudus, yaitu Yerusalem, kota tempat istirahat-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 13, 'Penuhilah Sion dengan pujian karena perbuatan-Mu yang perkasa, dan Bait-Mu dengan kemuliaan-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 14, 'Berikanlah kesaksian tentang makhluk-makhluk-Mu yang pada awal mula Kauciptakan, dan penuhilah segala nubuat yang telah dibawakan atas nama-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 15, 'Berikanlah ganjaran kepada mereka yang menantikan Dikau, dan buktikanlah kebenaran segala nabi-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 16, 'Ya Tuhan, dengarkanlah doa hamba-hamba-Mu ini sesuai dengan berkat Harun atas umat-Mu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 17, 'Semoga semua penghuni bumi ini mengakui, bahwa Engkaulah Tuhan, Allah kekal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 18, 'Setiap macam makanan dicernakan perut, namun demikian makanan yang satu lebih baik dari pada yang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 19, 'Seperti langit-langit mengenal. perburuan atas rasanya, demikianpun hati yang berpengertian mengenal perkataan dusta.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 20, 'Hati yang pintar busuk menyebabkan kesedihan, tetapi orang yang berpengalaman akan mengembalikannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 21, 'Seorang perempuan menerima suami manapun, tetapi anak perempuan yang satu adalah lebih baik dari pada yang lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 22, 'Kecantikan perempuan menggirangkan roman muka dan mengatasi segenap keinginan manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 23, 'Jika kebaikan hati dan kemanisan keluar dari mulutnya, maka suaminya tidak sama seperti manusia lain.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 24, 'Barangsiapa mendapat isteri memperoleh milik yang unggul, seorang pembantu yang serasi dengannya dan sebuah tiang penyangga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 25, 'Tempat tidak ada pagar tanah akan dirampoki, dan tempat tidak ada isteri suami mengembara sambil mengeluh.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 26, 'Sebab siapa gerangan akan percaya pada perampok di jalan raya, yang lari dari kota ke kota?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 36, 27, 'Demikianpun halnya seseorang yang tidak bertempat tinggal dan menginap di mana saja kemalaman.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 1, 'Setiap kawan akan berkata: "Akujugaseorang kawan," tetapi ada beberapa kawan yang cuma namanya saja kawan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 2, 'Bukankah suatu kesedihan yang mematikan, kalau seorang kawan atau teman berubah menjadi musuh?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 3, 'Celakalah pikiran yang buruk! Di mana gerangan diciptakan untuk meliputi permukaan bumi dengan penipuan?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 4, 'Ada kawan yang menggunakan teman selama ia dalam kesukaan, tetapi di kala kesukaran berubah menjadi lawan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 5, 'Ada kawan yang membantu temannya untuk keuntungan sendiri, dan waktu menghadap pertempuran mengambil perisai.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 6, 'Janganlah melupakan seorang kawan dalam perjuangan, dan manakala engkau kaya ia jangan lenyap dari ingatanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 7, 'Memang setiap penasehat memberikari nasehatnya, tetapi ada penasehat yang memberikan nasehat guna keuntungan sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 8, 'Hendaklah waspada terhadap penasehat, dan selidikilah dahulu apa yang dibutuhkannya, - sebab boleh jadi ia memberikan nasehat demi kepentingan sendiri -kalau tidak nanti ia membuang undi yang merugikan dirimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 9, 'la berkata kepadamu: "Memang tindakanmu bagus sekali, " kemudian ia berdiri jauh hendak melihat apakah yang menimpa dirimu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 10, 'Jangan berunding dengan orang yang iri hati kepadamu, dan sembunyikamlah rencana terhadap orang yang berdengki akan dikau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 11, 'Jangan berunding dengan perempuan tentang saingannya, atau dengan seorang penakut tentang perang, ataupun dengan pedagang mengenai jual beli, dan dengan seorang pembeli tentang belian; jangan pula berunding dengan orang yang iri hati tentang terima kasih, atau dengan seorang pemalas mengenai suatu pekerjaan, ataupun dengan buruh bermusim perihal menyelesaikan pekerjaan, atau dengan hamba yang malas tentang pekerjaan berat. Jangan percaya pada orang-orang macam itu dalam nasehat manapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 12, 'Sebaliknya, hendaklah selalu menghadap orang yang bertakwa, yang setahumu menuruti segala perintah, yang hatinya serasi dengan hatimu sendiri, dan yang merasa kasihan kepadamu, sekiranya engkau gagal.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 13, 'Lagipula kukuhkanlah nasehat hatimu sendiri, sebab tidak ada sesuatupun yang lebih setia kepadamu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 14, 'Sebab kerapkali dugaan hati lebih teliti dalam memberitahu dari pada tujuh peninjau yang berkawal di atas menara yang tinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 15, 'Tetapi terlebih berdoalah kepada Yang Mahatinggi, supaya tindakanmu dibimbing-Nya menurut kebenaran.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 16, 'Pikiran merupakan permulaan segala pekerjaan dan pertimbangan mesti mendahului setiap perbuatan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 17, 'Akar rencana ialah hati. Sebagai tanda perubahan hati muncullah keempat bagian ini:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 18, 'baik dan jahat, hidup dan mati, tetapi semua dikuasai oleh lidah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 19, 'Boleh jadi orang menjadi cerdik pandai dan guru bagi banyak orang lain, sedangkan bagi dirinya tidak berguna sedikitpun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 20, 'Boleh jadi orang pintar bicara namun dinistakan, dan akhirnya kekurangan segenap makanan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 21, 'Sebab Tuhan tidak memberikan kasih karunia-Nya, sehingga ia kekurangan kebijaksanaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 22, 'Ada orang yang hanya bijaksana guna dirinya sendiri dan yang berkata bahwa hasil kebijaksanaannya dapat dipercaya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 23, 'Tetapi adajuga orang bijaksana yang mendidik bangsanya sendiri, dan yang hasil kebijaksanaannya terjamin adanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 24, 'Orang yang bijak akan dilimpahi dengan pujian, dan dipuji bahagia oleh semua yang melihatnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 25, 'Kehidupan manusia hanya beberapa hari saja lamanya, sedangkan jumlah hari Israel tidak terbilang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 26, 'Orang bijak mendapat kepercayaan di tengah-tengah bangsanya, dan namanya akan hidup untuk selama-lamanya. Penyakit dan Tabib', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 27, 'Anakku, periksalah dirimu mengenai cara hidupmu, perhatikanlah apa yang buruk bagimu, lalu jangan kaubiarkan terus.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 28, 'Sebab tidak semua adalah baik bagi setiap orang, dan bukan setiap orang dapat menikmati segala-galanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 29, 'Janganlah seperti seseorang yang tak terpuaskan dengan kenikmatan apapun, dan jangan pula melahap segala makanan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 30, 'Sebab makan banyak mehgakibatkan penyakit, dan gelojoh menyebabkan sakit perut.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 37, 31, 'Banyak orang mati karena rakus, sedangkan orang yang menjaga dirinya memperpanjang hidup.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 1, 'Hormatilah tabib sebagaimana OO mestinya, sebab ia kaubutuhkan, oleh karena iapun diciptakan Tuhan juga.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 2, 'Memang penyembuhan datang dari Yang Mahatinggi, dan sebagai pemberian diterima dari Raja.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 3, 'Namun kepandaian seorang tabib meninggikan kepalanya, dan di hadapan para pembesar ia dikagumi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 4, 'Tuhan menciptakan obat-obatan dari bumi, dan tidak diabaikan oleh orang yang arif.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 5, 'Bukankah air menjadi tawar karena sepotong kayu, sehingga dayanya menjadi nyata?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 6, 'Tuhan memberikan kepada manusia pengetahuan, supaya dimuliakan karena pekerjaan-pekerjaan-Nya yang ajaib.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 7, 'Dengannya tabib menyembuhkan dan melenyapkan derita, dan juru obatpun mengolah campurannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 8, 'Dengan demikian pekerjaan Tuhan tak pernah berhenti, dan kesejahteraan dipertahankan di bumi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 9, 'Anakku, kalau jatuh sakit janganlah berayal-ayalan. Berdoalah kepada Tuhan, niscaya engkau disembuhkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 10, 'Jauhilah yang salah dan tanganmu hendaknya lurus, dan bersihkanlah hatimu dari segala dosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 11, 'Hendaklah mempersembahkan korban harum-haruman dan korban peringatan dari pati tepung, serta minyak tuangan sesuai dengan kemampuanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 12, 'Tetapi berikanlah tempat kepada tabib juga, sebab iapun diciptakan Tuhan, janganlah tabib jauh dari padamu, sebab kaubutuhkan pula.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 13, 'Adakalanya kesehatan terletak di tangan tabib.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 14, 'Mereka juga berdoa kepada Tuhan, semoga la menganugerahkan keringanan penyakit serta penyembuhan akan keselamatan hidup.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 15, 'Orang yang berdosa terhadap Pembuatnya jatuh kiranya ke dalam tangan tabib.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 16, 'Anakku, hendaklah bercucuran air matamu karena orang yang meninggal, dan hendaklah meratap seperti orang yang bersengsara. Uruslah jenazahnya sebagaimana pantas baginya dan janganlah melalaikan penguburannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 17, 'Hendaklah menangis dengan pedih dan meratap dengan sangatnya, dan berkabunglah sebagaimana layak baginya, satu dua hari supaya engkau jangan dicela, kemudian hendaklah menghibur hatimu atas kesedihanmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 18, 'Sebab duka nestapa mendatangkan kematian, dan kemurungan hati mematahkan kekuatan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 19, 'Habis penguburan duka nestapa boleh berhenti, sebab hidup penuh dukacita tak tertanggung padanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 20, 'Jangan membiarkan hatimu dimakan kesedihan enyahkanlah dan ingatlah akan hari depan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 21, 'Janganlah lupa bahwa orang itu tidak akan kembali lagi engkau tidak berguna sedikitpun bagi yang mati sedangkan merugikan dirimu sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 22, 'Ingatlah saja bahwa nasibnya menjadi nasibmu juga dia kemarin dan engkau hari ini!', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 23, 'Apabila orang mati beristirahat, biar kenang-kenangan akan dia beristirahat pula, hiburkanlah hatimu atas dia setelah nyawanya bercerai.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 24, 'Kebijaksanaan ahli Kitab diperolehnya dalam waktu senggang, dan hanya orang yang urusannya sedikit sajalah dapat menjadi bijaksana.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 25, 'Bagaimana gerangan dapat menjadi bijaksana orang yang memegang batang bajak dan yang membanggakan tangkai penghalaunya; atau orang yang menggiring sapi dan sibuk dengan pekerjaannya, yang hanya omong tentang anak kerbau.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 26, 'Hatinya tertuju pada membuat alur-alur, dan ketelitiannya terarah pada makanan anak-anak sapi,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 27, 'Demikianpun halnya dengan semua tukang dan mandur,yang sibuk siang dan malam; orang yang mengukir cincin .meterai dan bertekun dalam membuat macam-maeam coraknya, orang yang memberikan perhatiannya untuk meniru seni lukis dan dengan teliti mau menyelesaikan pekerjaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 28, 'Demikian pula halnya pandai besi yang duduk di dekat paron dan memperhatikan besi mentah jadi apa? Bahang api menghanguskan dagingnya, dan ia bergiat-giat dalam panas dapur api; telinganya ditulikan gemertuk martil, dan matanya tertuju kepada acuannya; perhatiannya terarah kepada penyelesaian buatannya, dan dengan teliti menyelesaikan penghiasannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 29, 'Begitu pula penjunan yang duduk bekerja, dan dengan kakinya menjalankan pelarikan; selalu ia berpikir kepada pekerjaannya, dan segenap kegiatannya tertuju kepada jumlah besar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 30, 'Dengan tangannya ia membentuk tanah liat, dan dengan kakinya menjadikannya lunak; perhatiannya tertuju kepada rengas yang dikenakannya, dan dengan teliti ia membersihkan dapurnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 31, 'Semua orang itu percaya pada tangan mereka, dan masing-masing pandai dalam pekerjaannya sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 32, 'Tanpa mereka tidak ada kota satupun dapat dibangun, dan orangpun tidak dapat berdiam di sana atau hidup.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 33, 'Namun demikian bagi dewan rakyat tidak dipilihlah mereka, dan dalam jemaah mereka tidak mendapat kedudukan tinggi. Mereka tidak duduk di kursi pengadilan, dan mereka tidak tahu-menahu tentang tata hukum.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 38, 34, 'Ajaran dan hukum tidak dapat mereka terangkari, dan tidak mahirlah mereka dalam pepatah. Tetapi mereka mempertahankan susiinan dunia semesta, dan doanya terletak dalam melaksanakan pertukangannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 1, 'Lainlah orang yang menyerahkan dirinya dan segenap kecerdasannya kepada Taurat dari Yang Mahatinggi. Kebijaksanaan segala leluhur diselidikinya, dan sibuklah ia dengan nubuat-nubuat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 2, 'Ajaran orang yang masyhur dipeliharanya, dan segala seluk-beluk amsal ia selami.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 3, 'la menyelidiki arti rahasia dari pepatah, dan teka-teki amsal disibukkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 4, 'Di kalangan para pembesar ia mengabdi, dan nampak di hadapan para penguasa. Negeri-negeri bangsa asing dijelajahinya, dan baik dan jahat di tengah-tengah manusia diuji olehnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 5, 'Pagi-pagi benar ia mengarahkah hatinya kepada Tuhan yang telah membuatnya, dan berdoa kepada Yang Mahatinggi. la membuka mulutnya untuk bersembahyang, dan memohon ampun atas dosa-dosanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 6, 'Jika Tuhan yang besar menghendakinya, maka terpenuhilah ia dengan roh pengertian. Maka ia sendiri membualkan kata-kata yang bijak,dan memuji Tuhan dengan sembahyangnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 7, 'Dengan lurus nasehat serta ilmunya disampaikannya,dan dipikirkannya rahasia-rahasia hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 8, 'la memperlihatkan ajaran dari wejangannya serta membanggakan Taurat Perjanjian Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 9, 'Pengertiannya akan dipuji banyak orang, dan tidak pernah akan lenyap. Kenang-kenangan akan dia tidak akan terhapus, melainkan namanya akan hidup turun temurun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 10, 'Kebijaksanaannya akan diceritakan pelbagai bangsa, sedangkan jemaah mewartakan pujiannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 11, 'Jika lama hidupnya maka lebih dari seribu nama akan ditinggalkannya, dan jikalau wafat cukuplah juga baginya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 12, 'Masih lain pikiran-pikiran mesti kuutarakan, sebab penuhlah aku laksana bulan purnama.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 13, 'Dengarkanlah aku, hai kamu anak-anak yang suci, dan hendaklah bertunas bagaikan pokok mawar yang berkembang di tepi sungai.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 14, 'Hendaklah harum semerbak laksana dupa, dan berbunga seperti bakung. Ratakanlah keharumanmu dan angkatlah pujian, pujilah Tuhan karena segala perbuatan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 15, 'Berikanlah hormat kepada nama-Nya, dan wartakanlah pujian-Nya dengan nyanyian dari bibirmu dan dengan kecapi; dan sambil memuji hendaklah berkata begini:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 16, 'Betapa agunglah segala perbuatan Tuhan! Setiap perintah-Nya terjadi pada waktu tepat. Tidak bolehlah orang berkata: "Apakah ini? Mengapa begitu?" Sebab semua diselidiki pada waktu yang ditetapkan Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 17, 'Atas firman-Nya berdirilah air seolah-olah bertimbun,dan atas sabda-Nyapun simpanan air terbuka.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 18, 'Segala sesuatunya yang dikehendaki-Nya terjadi atas perintah-Nya, dan tidak ada seorangpun dapat mencegah kuasa penyelamatan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 19, 'Pekerjaan segala makhluk terbuka di hadapan-Nya,dan tidak ada sesuatupun tersembunyi bagi mata-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 20, 'Dari kekal sampai kekal la memandang ke bawah, tidak ada barang sesuatupun yang luar biasa bagi-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 21, 'Tidak bolehlah orang berkata: "Apakah ini! Mengapa begitu?" Sebab semua telah diciptakan untuk tujuannya sendiri.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 22, 'Meluaplah berkat-Nya laksana sungai, dan menggenangi daratan seperti air bah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 23, 'Para bangsa akan mendapat murka-Nya, seperti air dirubah-Nya menjadi garam.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 24, 'Jalan-jalan-Nya adalah lurus bagi orarig suci, tetapi bagi kaum fasik menjadi batu sandungan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 25, 'Sejak awal mula hal-hal yang baik diciptakan bagi orang yang baik, sedangkan barang yang buruk bagi orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 26, 'Kebutuhan pokok untuk hidup manusia ialah: air, api, besi dan garam, terigu dan susu serta madu, air anggur, minyak dan pakaian.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 27, 'Semuanya itu teruntukkan bagi orang takwa sebagai barang yang baik, tepat sebagaimana menjadi buruk bagi orang berdosa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 28, 'Ada angin yang diciptakan untuk menghukum, dan dalam badainya angin itu menghebatkan deranya. Pada waktu penyelesaian angin itu melepaskan segenap kekuatannya dan meredakan murka Penciptanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 29, 'Api, hujan es, kelaparan dan kematianpun diciptakan semua untuk menghukum;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 30, 'gigi binatang buas, kalajengking dan ular beludakdan pedang yang menghukum juga diciptakan untuk membinasakan kaum fasik.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 31, 'Dengan riang semua melaksanakan perintah-perintah Tuhan, dan disediakan di bumi untuk menunaikan tugasnya; dan pada saatnya tidak akan melanggar firman Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 32, 'Dari sebab itu sejak awal mula aku sudah yakin benar, sudah mempertimbangkan dan mencantumkannya dalam sebuah karangan,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 33, 'bahwasanya pekerjaan Tuhan adalah baik semuanya dan pada waktu tepat memenuhi setiap keperluan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 34, 'Tidak dapat dikatakan: "yang ini lebih buruk dari pada yang itu," sebab pada saatnya semua ternyata baiklah adanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 39, 35, 'Dan kini hendaklah bernyanyi dengan segenap hati dan suara yang nyaring serta memuji nama Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 1, 'Suatu kesusahan besar telah Tt vF diciptakan untuk setiap manusia, dan semua anak Adam tertekan oleh kuk yang berat sejak mereka keluar dari rahim ibunya sampai kembali kepada ibu pertiwi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 2, 'Segala pikiran serta ketakutan hatinya ialah: ingatan akan apa yang datang, yaitu hari ajalnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 3, 'Mulai dengan orang yang duduk di atas takhta yang mulia sampai dengan orang yang malang yang duduk dalam debu dan abu,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 4, 'mulai dengan orang yang berpakaian ungu tua dan bermahkota sampai dengan yang kasar pakaiannya, semua kena amarah, iri hati, kemasygulan dan kecemasan, takut maut, geram dan perselisihan;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 5, 'bahkan waktu beristirahat di pembaringannya tidur malam hanya mengubah angan-angan yang menyusahkan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 6, 'Orang hanya mendapat istirahat sedikit saja atau tidak sama sekali, dan kemudian sedang tidur ia dibingungkan seperti di siang hari oleh khayalan-khayalan hatinya seperti seseorang yang melarikan diri dari pertempuran.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 7, 'Pada ketika diselamatkan ia terbangun, dan heranlah ia karena ketakutannya yang ternyata tidak apa-apa.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 8, 'Segala makhluk, mulai derigan manusia sampai dengan ternak, dan segala orang berdosa bahkan tujuh kali lipat didatangi', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 9, 'kematian dan darah, perselisihan dan pedang, malapetaka, kelaparan, kesusahan dan bencana.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 10, 'Semuanya itu diciptakan untuk kaumfasik, dan karena mereka itupun air bah telah datang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 11, 'Segala sesuatunya yang berasal dari bumi kembali ke bumi, dan apa yang berasal dari air berbalik ke laut.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 12, 'Setiap suapan dan kelaliman akan dihapus, sedangkan kesetiaan akan tetap selama-lamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 13, 'Harta kaum durjana akan menjadi kering seperti batang air, dan menggeledek seperti mata petir dalam hujan lebat.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 14, 'Orang yang murah hati akan bergembira kelak, dan demikianpun para pelanggar hukum lenyaplah akhirnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 15, 'Taruk kaum fasik tidak akan banyak cabangnya dan akar-akar yang buruk akan menemui wadas keras.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 16, 'Gelagah yang tumbuh di tepi setiap air dan sungai akan dicabut sebelum segala rumput.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 17, 'Tetapi kebaikan hati adalah laksana taman penuh berkat, dan kedermawanan bertahan untuk selama-lamanya. 18 Manislah kehidupan bagi orang yang berdiri sendiri dan para pekerja, tetapi orang yang menemukan harta lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 18, 'Segala sesuatunya yang dikehendaki-Nya terjadi atas perintah-Nya, dan tidak ada seorangpun dapat mencegah kuasa penyelamatan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 19, 'Keturunan dan mendirikan kota mengabadikan nama, tetapi isteri yang tak bercela dianggap lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 20, 'Air anggur dan musik meriangkan hati, tetapi cinta kepada kebijaksanaan lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 21, 'Sending dan celempung memperindah langgam, tetapi suara merdu lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 22, 'Kemolekan dan kecantikan digemari mata, namun lebih dari pada kedua-duanya digemarinya rumput di ladang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 23, 'Sahabat dan teman hanya bertemu untuk sementara waktu saja, tetapi suami isteri lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 24, 'Saudara-saudara dan pertolongan bermanfaat pada waktu kesukaran, tetapi kedermawanan meluputkan lebih baik dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 25, 'Emas dan perak menyangga kaki, tetapi nasehat yang baik lebih bernilai dari pada kedua-duanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 26, 'Kekayaan dan kekuasaan menegakkan hati, tetapi ketakutan akan Tuhan lebih baik dari pada kedua-duanya. Manakala ada ketakutan akan Tuhan tidak ada lagi kekurangan apapun, dan di sampingnya tak perlu dicari pertolongan lain lagi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 27, 'Ketakutani akan Tuhan sebagai taman penuh berkah layaknya, dan melindungi manusia lebih baik dari kemuliaan manapun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 28, 'Anakku, janganlah hidup sebagai pengemis, lebih baiklah mati dari pada minta-minta.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 29, 'Hidup seseorang yang mesti melirik kepada meja orang lain tidak dapat dikatakan hidup. la menodai dirinya dengan makanan orang lain. Orang yang berpengertian dan terdidik menjaga diri terhadapnya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 40, 30, 'Memang dalam mulut orang biadab mengemis manis juga rasanya, tetapi di dalam batinnya dinyalakan api.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 1, 'Hai maut, betapa pahitlah ft -L ingatan akan dikau bagi orang yang hidup dengan tenteram di tengah-tengah harta miliknya, untuk orang yang tidak mengalami pencobaan dan berhasil dalam segala-galanya dan masih cukup berdaya untuk menikmati makanannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 2, 'Hai maut, betapa baiklah keputusanmu bagi orang yang kekurangan dan yang menyusut kekuatannya, yang lanjut usia dan yang tersesak dalam segala-galanya; bagi orang yang degil dan yang habis ketabahan hatinya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 3, 'Janganlah takut terhadap keputusan maut, ingatlah akan mereka yang mendahului engkau dan yang akan menyusul.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 4, 'Demikianlah keputusan dari Tuhan mengenai segala yang hidup, mengapa kiranya kautolak apa yang diperkenankan Yang Mahatinggi? Apakah kau hidup sepuluh tahun, atau seratus atau seribu, di dunia orang mati tidak diperiksa hidupmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 6, 'Milik pusaka anak-anak orang berdosa akan jatuh binasa, dan keturunan mereka akan ternista selama-lamanya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 7, 'Seorang ayah yang fasik akan dicela oleh anak-anaknya, sebab karena dialah mereka ternista.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 8, 'Celakalah kamu, hai orang-orang yang fasik, yang telah meninggalkan Taurat dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 9, 'Ketika kamu lahir maka kamu lahir untuk dikutuk, dan pada saat kamu mati maka kutuklah yang kamu terima sebagai bagianmu.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 10, 'Segala sesuatunya yang berasal dari bumi berbalik ke bumi, demikianpun orang fasik beralih dari kutuk kepada kebinasaan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 12, 'Hendaklah engkau memelihara namamu, sebab ia tinggal padamu lebih lama dari pada seribu harta emas yang besar.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 13, 'Hidup bahagia hanya berlangsung sejumlah hari terbatas, sedangkan nama yang baik tinggal untuk selama-lamanya. Beberapa pepatah', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 14, 'Hai anak-anakku, laksanakan . ajaran dengan tenteram. Kebijaksanaan tersembunyi dan harta terpendam, apa gunanya kedua-duanya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 15, 'Lebih baiklah orang yang menyembunyikan kebodohannya dari pada yang menyembunyikan kebijaksanaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 16, 'Dari sebab itu bermalulah karena perkataanku. Bukan setiap rasa malu baik untuk dipelihara, dan tidak semua dengan tepat dinilai oleh sekalian orang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 17, 'Hendaklah malu terhadap ibu bapa karena kemesuman, dan karena kebohongan terhadap pembesar;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 18, 'hendaklah malu terhadap hakim dan penguasa karena kesalahan, dan terhadap himpunan rakyat karena melanggar hukum;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 19, 'hendaklah malu terhadap teman dan sahabat karena kurang adil, dan terhadap orang di tempat , tinggalmu karena mencuri;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 20, 'hendaklah malu terhadap kebenaran Allah dan perjanjian. Hendaklah malu karena bersandar siku tengah makan,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 21, 'karena menghina dalam menerima dan memberi, dan karena mendiamkan saja orang yang memberi salam;', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 22, 'hendaklah malu karena melirik kepada pelacur, dan karena menolak orang sebangsamu,', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 23, 'karena mengambil bagian orang lain ataupun apa yang diberikan kepadanya, dan karena memandang perempuan yang bersuami.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 24, 'Hendaklah malu karena mengaribi pelayan perempuan, janganlah mendekati tempat tidurnya', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 25, 'dan terhadap sahabat karena kata penghina, - setelah memberi jangan menghina -', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 26, 'Hendaklah malu karena mengulang serta mencerita apa yang kaudengar, dan karena membuka apa yang dikatakan sebagai rahasia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 41, 27, 'Kalau demikian maka kau taruh rasa malu tepat, dan mendapat sambutan baik pada segala manusia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 1, 'Tetapi tentang hal-hal yang TC?t berikut ini janganlah malu, dan jangan berdosa karena memihak:', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 2, 'Pada terbitnya dan pada masuknya matahari mewartakan dirinya, sebagai alat ajaib buatan dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 3, 'Apabila rembang ia menghanguskan tanah, dan siapa gerangan dapat bertahan terhadap panas teriknya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 4, 'Orang mengopak dapur supaya menjadi panas, tetapi matahari membakar gunung-gemunung tiga kali lipat; ia mengembuskan uap yang berapi, dan menyilaukan mata dengan sinar yang dipancarkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 5, 'Agunglah Tuhan yang menciptakannya dan dengan firman-Nya mempercepat peredarannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 6, 'Bulanpun selalu tepat pada waktunya serta menunjukkan musim-musim sebagai tanda abadi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 7, 'Dari bulanlah datang tanda untuk mengadakan perayaan-perayaan, sebuah penerang yang bersusut setelah menjadi purnama.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 8, 'Dari padanyalah bulan mendapat namanya, dan ia bertambah secara ajaib dalam peredarannya. la merupakan sebuah alamat bagi bala tentara di angkasa,dan bersinar di cakrawala.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 9, 'Keindahan langit ialah semarak bintang-bintangnya, perhiasan gilang-gemilang di tempat tinggi Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 10, 'Sesuai dengan aturannya semua berdiri tetap karena firman dari Yang Mahakudus, dan tak jemu-jemu dalam penjagaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 11, 'Pandangilah pelangi dan pujilah Penciptanya, sebab teramat eloklah ia dalam semaraknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 12, 'Dengan serinya ia melingkungi bentangan langit, dan direntangkan oleh tangan dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 13, 'Tuhan menurunkan salju dengan firman-Nya, dan anak panah penghukuman-Nya dikilatkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 14, 'Karenanya gudang-gudang terbuka, dan awan-awan bagaikan burung terbang.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 15, 'Dengan kebesaran-Nya la menebalkan awan-awan, dan terpecahlah batu-batu es.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 17, 'Kepada orang-orang-Nya yang kudus Tuhan tidak memberikan kemampuan untuk menceritakan segala buatan-Nya yang mengagumkan, yang telah ditentukan Tuhan alam semesta, supaya jagat raya didukung dengan kemuliaan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 18, 'Bagaikan garam embun beku ditaburkan Tuhan, yang menjadi mata duri karena kedinginan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 19, 'Yang sudah-sudah diberitahukan-Nya dan juga apa yang datang, dan bekas dari apa yang tersembunyipun disingkapkan-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 20, 'Bertiuplah angin utara yang dingin, dan di atas air terbentuklah es, Duduklah ia di atas setiap kumpulan air yang dilapisi seolah-olah dengan baju zirah.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 21, 'Angin utara menelan gunung-gemunung dan menghanguskan padang gurun, dan perumputan dimakannya seperti nyala api.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 22, 'Semuanya cepat disembuhkan oleh kabut, dan sesudah panas terik semua disegarkan embun.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 23, 'Samudera raya diteduhkan oleh Tuhan dengan pikiran-Nya, dan di dalamnya pulau-pulau ditanam oleh-Nya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 24, 'Oleh Tuhan maka pesuruh-Nya berhasil, dan karena firman-Nya semuanya rapih teratur.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 42, 25, 'Yang satu menguatkan kebaikan dari yang lain, dan siapa gerangan pernah kenyang-kenyang memandang kemuliaan Tuhan? Kebanggaan langit yang tinggi ialah cakrayala terang-benderang, dan langit kelihatan sebagai tontonan yang mulia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 1, 'Kebanggaan langit yang tinggi ialah cakrawala terang benderang, dan langit kelihatan sebagai tontonan yang mulia.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 2, 'Pada terbitnya dan pada masuknya matahari mewartakan dirinya, sebagai alat ajaib buatan dari Yang Mahatinggi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 3, 'Apabila rembang ia menghanguskan tanah, dan siapa gerangan dapat bertahan terhadap panas teriknya?', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 4, 'Orang mengopak dapur supaya menjadi panas, tetapi matahari membakar gunung gemunung tiga kali lipat; ia mengembuskan uap yang berapi, dan menyilaukan mata dengan sinar yang dipancarkannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 5, 'Agunglah Tuhan yang menciptakannya dan dengan firmanNya mempercepat peredarannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 6, 'Bulanpun selalu tepat pada waktunya serta menunjukkan musim- musim sebagai tanda abadi.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 7, 'Dari bulanlah datang tanda untuk mengadakan perayaan- perayaan, sebuah penerang yang bersusut setelah menjadi purnama.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 8, 'Dari padanyalah bulan mendapat namanya, dan ia bertambah secara ajaib dalam peredarannya. Ia merupakan sebuah alamat bagi bala tentara di angkasa, dan bersinar di cakrawala.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 9, 'Keindahan langit ialah semarak bintang- bintangnya, perhiasan gilang- gemilang di tempat tinggi Tuhan.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 10, 'Sesuai dengan aturannya semua berdiri tetap karena firman dari Yang Mahakudus, dan tak jemu- jemu dalam penjagaannya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 11, 'Pandangilah pelangi dan pujilah Penciptanya, sebab teramat eloklah ia dalam semaraknya.', 'id', 'Deutero'),
  ('71', 'sir', 'Yesus bin Sirakh', 43, 12, 'Dengan serinya ia melingkungi bentangan langit, dan direntangkan oleh tangan dari Yang Mahatinggi.', 'id', 'Deutero'),
